  select md5(content::text) into h from public.sop_documents where id = 'a48f7a01-3847-4be8-9df8-ef44fa51d20a' and status = 'active' and revision = 'v3';
  if h is distinct from 'fb2e79645bb99b888298135b29ce7540' then raise exception 'SOP-902 is not the document that was read (md5 %).', h; end if;
