  if h is distinct from '5efe2dc3a87ccc65a7f22a101a8ae6b3' then raise exception 'SOP-903 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '18c0a2c5-2ba7-4708-bbfb-d49c53ab6984' and status = 'active' and revision = 'v2';
