  select md5(content::text) into h from public.sop_documents where id = 'db25397d-d4a3-49ee-9222-eca3ba47131d' and status = 'active' and revision = 'New';
  if h is distinct from 'd785c9adb1dac09c95e4492ce9f28d4d' then raise exception 'SOP-906 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '281fcce4-5b09-435e-b6d2-72ab815863be' and status = 'active' and revision = 'New';
  if h is distinct from 'a698537723548ceed465b2fbd88db716' then raise exception 'SOP-503 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'cc10d49f-e228-4f35-a267-4e28af7e1836' and status = 'active' and revision = 'New';
  if h is distinct from 'e54fdf12377317b6a71c486cd479e1f3' then raise exception 'SOP-504 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'f0ad5f61-a2b2-4e07-a363-9da74f96133f' and status = 'active' and revision = 'v5';
  if h is distinct from 'd2681121447cb4c4da7d1b0ef4001ceb' then raise exception 'FSQM-016 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '2d9682eb-ff5b-4e74-ab9a-c5fe1a2423d9' and status = 'active' and revision = 'v2';
  if h is distinct from 'c25e8e27fe840a30c60fcf5b4cdad561' then raise exception 'FSQM-005 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '6d069d17-c19f-4ef2-bbfd-1a9968046d81' and status = 'active' and revision = 'v2';
  if h is distinct from 'f624164d77fbddde2024f9fd20019c66' then raise exception 'FSQM-009 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'ceccac3f-b5b7-4267-b38a-c72cb36f3d0b' and status = 'active' and revision = 'v3';
  if h is distinct from '3a71d009ff4d22eca24d00ece8f5e891' then raise exception 'FSQM-014 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '89390225-eda9-46d9-8c84-6963652eae08' and status = 'active' and revision = 'v21';
  if h is distinct from '15f75913de1f847fa5d26cd4df8efc8f' then raise exception 'FSQM-017 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '7e7d7f8b-af7a-4433-b941-93615e47ccd6' and status = 'active' and revision = 'New';
  if h is distinct from 'ed8f91ab7aa9836921c897f1e4de17e3' then raise exception 'FSQM-036 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '50f1511f-941c-4664-97ae-cae250ae8173' and status = 'active' and revision = 'New';
  if h is distinct from 'b4373050d996e6de5b1ea6268ae0c8de' then raise exception 'FSQM-039 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '2363dbc0-d209-4cc4-a1cb-b2d77efc27e4' and status = 'active' and revision = 'New';
  if h is distinct from 'c5154f21e88e26d85352e3116bc52db3' then raise exception 'FSQM-027 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '7282e1cc-b6a9-4355-8b30-5e9b30b4468f' and status = 'active';
  if h is distinct from '43f0d7adfc198fd396f4a91c45027ef7' then raise exception 'SOP-2.1.2 is not the document that was read (md5 %).', h; end if;
  if (select count(*) from public.sop_documents where id in ('e0208578-ebb7-45c1-be4d-dcbafe6cc581', '395c9058-db59-494c-9bc5-5148a4437880', 'c3c9dab8-4516-4331-8e2a-328376b6c6d6', '3e09017b-ea1d-4900-bbbb-90cf18ee1456', '76c28fb3-2dcf-40db-b7e6-c6e73aadb1f3', '12144e6d-b151-448c-855b-fb7cecf93002') and status = 'draft' and content is null) <> 6 then
    raise exception 'the six empty placeholders are not as read.';
  end if;
end $guard$;

update public.sop_documents set content = $jx${"scope": "Applies to all persons entering food handling, processing or storage areas at the Adventure Bakery facility — employees, temporary staff, contractors, maintenance personnel, auditors, visitors and management.\n\nThis program is the umbrella document for SQF Food Safety Code: Food Manufacturing, Edition 9, Module 11.3 (Personnel Hygiene) and Module 11.4 (Personnel Processing Practices). The remaining Module 11 GMPs are implemented through documents that already exist and are referenced here rather than restated:\n\nPre-operational inspection and release — SOP-11.2.12, recorded on FRM-903.\nEquipment and utensil cleaning — SOP-901 to SOP-906 (SSOPs).\nSanitation schedule and verification — FRM-901, FRM-902, FRM-903.\nGlass and brittle plastic — SOP-11.7.3, FRM-907, FRM-908.\nAllergen changeover — FSQM-027.\nSite food safety inspections — FSQM-022.\nTraining and records — SOP-2.9, FRM-952, FRM-953, REP-951.\n\nNot covered here: premises and equipment construction (11.2), water, ice and air (11.5), storage and transport (11.6), and separation of functions (11.7) other than glass control.", "purpose": "To document the Good Manufacturing Practices applied at Adventure Bakery, LLC — personnel health and hygiene, handwashing, clothing and personal effects, visitors and contractors, staff amenities, and processing practices — and to state how each is implemented, verified and trained, so that food safety is controlled and assured across the scope of certification.", "records": "Visitor sign-in and GMP acknowledgement — FRM-905 and FRM-906, retained a minimum of 12 months.\nDaily pre-operation and amenity check — FRM-903, retained per the record retention policy.\nPeriodic GMP and food safety inspections and their corrective actions — per FSQM-022, retained per the record retention policy.\nRisk assessments for permitted jewellery exceptions — held by the SQF Practitioner with this program, for as long as the exception stands plus one audit cycle.\nIllness, injury and bodily-fluid incident dispositions — held by QA, retained per the record retention policy.\nTraining assignment, completion and competency — Team Portal, FRM-952, FRM-953 and REP-951, retained per SOP-2.9.", "procedure": ["SCOPE AND APPLICATION OF GOOD MANUFACTURING PRACTICES (SQF 2.4.2.1, 2.4.2.2)", "• The Good Manufacturing Practices set out in Module 11 of the SQF Food Safety Code: Food Manufacturing apply in full to the scope of certification — the manufacture, baking, packing and storage of baked products at this facility.", "• **No exemption from any Module 11 requirement is claimed by this program.** Where the site determines that a requirement does not apply, or that an alternative control achieves the same outcome, that determination is recorded in **FSQM-013** (Module 11 Applicability & Exemption Analysis) as a written risk analysis stating the justification or the evidence of effectiveness, approved by the SQF Practitioner, **before** it takes effect. An undocumented exemption is a non-conformance against 2.4.2.1.", "• The GMPs in Module 11.3 and 11.4 are stated in Parts 2 to 8 below. The remaining Module 11 GMPs are implemented through the documents listed in the Scope: SOP-11.2.12 and FRM-903 (pre-operational inspection), SOP-901 to SOP-906 (equipment and utensil cleaning), FRM-901 and FRM-902 (sanitation schedule and verification), SOP-11.7.3 with FRM-907 and FRM-908 (glass and brittle plastic), FSQM-027 (allergen changeover), FSQM-022 (site food safety inspections), and SOP-2.9 (training and records).", "HEALTH, ILLNESS AND INJURY (SQF 11.3.1.1, 11.3.1.2, 11.3.1.3)", "• Personnel known to be carriers of an infectious disease that presents a health risk to others shall not engage in processing or packing food, and shall not enter storage areas where food is exposed.", "• Staff shall report to their supervisor, **before starting work**, any of: vomiting, diarrhoea, jaundice, fever with sore throat, discharge from the eyes, ears or nose, or an infected wound, boil or sore. A person reporting any of these shall not enter a food handling or processing area.", "• A person excluded under this Part returns to food handling work only when free of symptoms and cleared by their supervisor.", "• **Exposed cuts, sores or lesions** — personnel with these shall not handle exposed product, primary (food-contact) packaging, or food-contact surfaces. Minor cuts or abrasions on exposed skin shall be covered with a **coloured, metal-detectable bandage** or an equivalent waterproof, coloured dressing; where the injury is on the hand, a glove shall be worn over the dressing. A lost dressing is treated as a foreign-material incident and reported immediately.", "• Staff shall not cough, sneeze or spit over product, ingredients, packaging or food-contact surfaces, and shall wash their hands afterwards.", "• **Spillage of bodily fluid** — the area is cleared, and a trained staff member ensures every affected area is cleaned and sanitized and that all affected materials and product are quarantined or disposed of. The incident and its disposition are recorded.", "HANDWASHING (SQF 11.3.2.1 to 11.3.2.6)", "• **Hands shall be clean.** All staff, contractors and visitors shall wash their hands: (i) on entering a food handling or processing area; (ii) after each visit to a toilet; (iii) after using a handkerchief or tissue; (iv) after smoking, eating or drinking; and (v) after handling wash-down hoses, cleaning materials, dropped product or contaminated material.", "• Hands shall also be washed after handling waste, after touching the face, hair or clothing, and after handling a mobile phone.", "• **Method** — wet hands with potable water, apply liquid soap, lather and scrub all surfaces including between the fingers and under the nails for at least twenty seconds, rinse, and dry with a single-use paper towel.", "• **Gloves do not replace handwashing.** Hands are washed before gloves are put on and at every trigger listed above; gloves are changed, not washed, at those points.", "• **Handwashing stations — three are provided:** one in each of the two lavatories, and one immediately inside the personnel access point into the production area from the office, break room and reception. Each is supplied with hot and cold running potable water, a paper towel dispenser, and a bin for used paper towels.", "• **Soap is supplied from a hands-free dispenser** — more than the fixed dispenser 11.3.2.3 (ii) asks for. **Paper towels are presented so that a towel can be taken without touching the dispenser housing or anything else.** What 11.3.2.3 (iii) is protecting is clean hands on the way to being dried: hands washed and then pressed against a housing that dirty hands last touched are no longer clean. Taking the towel without contact meets that, and no member of staff need touch the dispenser to dry their hands.", "• **The basins are ceramic** — impervious, non-corrosive and easily cleaned, which is what 11.3.2.3 means by \"stainless steel or similar non-corrosive material\". Ceramic is also **brittle**, so a ceramic fixture inside a food handling area is controlled as a brittle item: listed on **FRM-907** (Glass & Brittle Plastic Register) and inspected for chips and cracks with the rest of that register under **SOP-11.7.3**. A chipped basin over a hand-washing point is a foreign-material route, not just a maintenance job.", "• **One station serves the production floor**, immediately inside its personnel access point, which is the floor's only entrance from non-production space. 11.3.2.2 asks for further stations throughout food handling and processing areas *as required*; at this floor's size and layout one is sufficient, and that judgement is revisited if the layout changes or the floor grows.", "• Handwashing stations are for handwashing only. They shall not be used to wash equipment, utensils or cloths.", "• **Signage** instructing people to wash their hands before entering food processing areas is displayed in a prominent position in the break room, at the break room exit, in both toilet rooms and at the entrance to production, **in English and Spanish** — the languages understood by site personnel, consistent with FSQM-002.", "• The site operates **no designated high-risk processing area**. Where such an area is established, hands-free taps and hand sanitizers shall be provided at its handwashing stations (11.3.2.4).", "CLOTHING, HAIR AND PROTECTIVE WEAR (SQF 11.3.3.1 to 11.3.3.7)", "• **Basis of this policy — the risk analysis required by 11.3.3.1.** The hazards the clothing and hair policy controls are: hair and beard hair falling into open product; fibres, buttons, drawstrings and other loose components detaching from garments; soil, dust and organic matter carried in from outside the facility on clothing and footwear; microbiological transfer from street clothing and from garments stored against product or packaging; and allergen carry-over on protective clothing worn across a changeover. The controls chosen against those hazards are: full hair and beard containment in every area where product is exposed; site-designated outer garments that are smooth, cleanable and free of external components that can detach; footwear controlled at the point of entry so external soil does not reach the floor; separation of street clothing from clean protective clothing and from all food and packaging; and removal or change of protective clothing at changeovers and whenever it becomes a contamination risk. This analysis is reviewed whenever the process, the product range or the facility layout changes.", "• Wear clean, designated outer garments, and arrive at the facility in clean clothing free of soilage or foul odour. Change lab coats if they become soiled.", "• Wear hairnets so both ears are covered and all hair is contained; wear a beard net covering all facial hair while in production and storage areas.", "• Clothing, including shoes, shall be clean at the start of each shift and maintained in a serviceable condition. Excessively soiled uniforms shall be changed or replaced as soon as they present a contamination risk — not at the end of the shift.", "• Wear pants that fully cover the torso and ankles; wear a belt if pants sag.", "• **Footwear is controlled by sanitizing foot baths, and every person passes through them.** There are two: one at the entrance to the production area from the office, break room and reception, and one at the walkthrough between the production area and the inventory and packaging area. External soilage — dirt, faecal matter, decomposing material or other foreign matter — shall not be carried into production or storage areas.", "• **Foot bath strength — Noble Sani-512 at 1:160**, which is 4.0 fluid ounces of product per 5 gallons of water, or 0.8 fl oz per gallon. **This is deliberately stronger than the 1:512 food-contact dilution** used on equipment and utensils in the SSOPs. A foot bath carries heavy organic soil off the floor, and that soil consumes quat: made up at the weaker food-contact ratio the solution deactivates and leaves footwear unsanitized. **The two strengths are for two different jobs — never make a foot bath at the food-contact dilution, and never sanitize a food-contact surface at the foot-bath dilution.** The foot-bath dilution is not a no-rinse food-contact strength.", "• **The two dilutions are made up into separate, clearly labelled containers**, so the foot-bath solution and the food-contact solution are never drawn from the same vessel. That labelling is the control which keeps two strengths of one product from reaching the wrong job — the solutions look identical, and only the label distinguishes them.", "• **Foot bath maintenance — the check is scheduled, the change is conditional.** Each bath is checked **at the start of every production day**: looked at, and read with a quat test strip. The solution is **changed when the strip reads below target, when the bath is visibly soiled, or when it has been diluted** by water carried in on footwear or by washdown. It is not replaced on a fixed schedule — a bath still at strength and still clean is doing its job, and dumping it regardless spends chemical without adding control. The baths are stripped and thoroughly cleaned **monthly**, and sooner if required.", "• The daily check is what makes the conditional change a control rather than a guess. The soil a bath lifts off the floor is exactly what spends the quat, so an unchecked bath is weaker than its label says however carefully it was mixed — and nobody can tell by looking at it. **The strip must be able to read this solution:** at 1:160 the bath is roughly three times the strength of the 1:512 food-contact solution, so the 0-400 ppm strips used on food-contact surfaces will saturate and read \"high\" whatever the true value. A high-range quat strip is required for the baths. The daily check is recorded on **FRM-903**; the monthly strip-down is scheduled on **FRM-901**.", "• **Disposable gloves and aprons shall be changed after each break, on every re-entry to the processing area, and whenever damaged.** They are not washed and re-used.", "• Non-disposable aprons and gloves shall be cleaned and sanitized as required. When not in use they are stored on the racks provided in the processing area, or in designated sealed containers in personnel lockers. They shall **never** be placed or stored on packaging, ingredients, product or equipment.", "• Protective clothing shall be made from material that poses no food safety threat and is easily cleaned. It shall be cleaned after use, or at a frequency that controls contamination, and stored clean and serviceable so that it cannot pick up microbiological or allergen contamination between uses.", "• **Laundering — aprons and other protective clothing are laundered by employees at home**, with laundry detergent, and hung to dry. Home laundering is permitted, and these conditions apply to it: the garment is laundered after each use, or sooner if it becomes soiled; washed separately from heavily soiled household laundry; dried and kept in a clean, dry place; carried to and from the site in a clean, covered bag; and presented clean at the start of each shift. A garment that cannot be returned to a clean, serviceable condition is replaced rather than worn.", "• Racks are provided for the temporary storage of protective clothing when staff leave the processing area, at the **personnel access doorway into production, beside the handwashing station and the foot bath** — so the garment comes off, the foot bath is crossed and the hands are washed at one point rather than three (11.3.3.7).", "• Protective clothing is removed before entering toilet rooms, the break room, or any outside area, and is not worn outside the facility.", "JEWELLERY AND PERSONAL EFFECTS (SQF 11.3.3.8)", "• Do not wear jewellery, cosmetic items, or other objects that might fall into food, equipment or containers — including visible or exposed piercings, watches, earrings, necklaces, bracelets, fingernail polish or hardener, false fingernails and false eyelashes. **Only plain wedding bands with no stones are allowed.**", "• **Medical alert items** may be permitted on a case-by-case basis with the permission of Quality and Production supervision. **Items accepted for religious or cultural reasons** follow the same route.", "• Every permitted exception shall be covered so it cannot be lost into product, shall meet regulatory and customer requirements, and shall be supported by a **written risk assessment** recorded and retained by the SQF Practitioner with this program. Permitted exceptions are checked at GMP inspection, which is the ongoing risk management 11.3.3.8 requires — a one-time approval is not sufficient.", "• Store clothes, mobile phones, personal belongings and other non-food items in lockers or offices only. Personal items are not taken into food handling, processing or storage areas.", "VISITORS AND CONTRACTORS (SQF 11.3.4.1 to 11.3.4.4)", "• Every visitor — including contractors, maintenance personnel, auditors, suppliers, customers, guests and **management staff** — shall comply with this Part.", "• **Sign in on FRM-905** (Visitor Sign-In Log) before entering any food handling, processing or storage area.", "• **Read and acknowledge the site's food safety and hygiene rules on FRM-906** (Visitor GMP Acknowledgement) on the first visit. The acknowledgement is **renewed every twelve months and whenever FRM-906 is revised**, and a health declaration is made on **FRM-905 at every visit**. A visitor holding a valid FRM-906 acknowledgement satisfies the training requirement of 11.3.4.1; **any visitor who does not shall be escorted at all times** by an authorized employee.", "• **Remove jewellery and loose objects** in accordance with Part 5. This applies to management staff equally.", "• Wear suitable clothing and footwear and the protective wear issued at entry — hairnet, beard cover where applicable, lab coat, and shoe covers or dedicated footwear.", "• **Enter and exit through the proper staff entrance points only**, and comply with the handwashing requirements of Part 3 and the processing practices of Part 8.", "• Remain within approved areas, and not touch ingredients, packaging, product or equipment unless authorized by the SQF Practitioner.", "• **Visitors showing visible signs of illness shall not be permitted to enter** any area where food is handled or processed. The rules of Part 2 apply to visitors as they do to staff.", "• **Contractors** additionally: agree the work area and its segregation with the SQF Practitioner or Supervisor before starting; account for all tools, parts and materials before and after the work; and where the work introduces glass or brittle plastic, comply with SOP-11.7.3 and record it on FRM-907.", "• Completed visitor records are retained by QA for a minimum of **twelve months**. An FRM-906 acknowledgement is retained for twelve months after the last visit that relied on it.", "STAFF AMENITIES AND WELFARE (SQF 11.3.5.1 to 11.3.5.10)", "• Staff amenities — toilet rooms, the break room and changing areas — have documented cleaning procedures, are scheduled on **FRM-901** (Master Sanitation Schedule), and their sanitary condition is confirmed on **FRM-903** at pre-operation. They are lit and ventilated appropriately and are available to every person engaged in handling and processing product.", "• **Changing** — staff and visitors change into and out of protective clothing in the toilet rooms, which are of sufficient size for the purpose and are kept clean (11.3.5.2).", "• **Street clothing and personal items** are stored in the lockers provided in the break room, which is separate from all food-contact zones and from food and packaging storage (11.3.5.4).", "• The site processes no high-risk foods and operates no designated high-risk area, so a high-risk change area (11.3.5.3) is not provided. Showers (11.3.5.5) are not required by the processes performed here. Should either condition change, the provision shall be made before that processing begins.", "• **Toilet rooms** are accessible to staff, separate from processing and food handling operations, sufficient in number for the maximum number of staff on site, constructed so they can be easily cleaned and maintained, and kept clean and tidy. **The employee lavatory is reached through a vented airlock** rather than opening onto the processing area (11.3.5.6 ii). Provision is made for storing protective clothing and outer garments while the facilities are in use. **Cleaning tools and equipment used in toilet rooms shall never be used to clean processing areas** and are stored separately and identified for that use only.", "• **Handwashing basins** are provided immediately inside or outside the toilet room, to the specification in Part 3.", "• **Sanitary drainage** is not connected to any other drain within the premises and discharges to the sewerage system in accordance with regulations.", "• The **break room** is separate from all food contact and handling zones, is lit, and is ventilated by the site's heating and cooling system. It has **a refrigerator**, **a microwave for heating food**, and **a table with seating for all employees at one sitting** (11.3.5.9 i, ii, iv). It holds the personal-item lockers and is kept clean and free from waste materials and pests.", "• The break room has **no utensil sink** (11.3.5.9 iii), and nothing is washed up in it: **the utensils provided are disposable**, and any re-usable personal item a member of staff brings is taken home to be washed rather than washed on site. The handwash basin in the adjacent lavatory is therefore not standing in for a utensil sink — there are no utensils to wash. Used personal items are kept in the owner's locker or bag until they leave, not left out in the room. This is an alternative arrangement rather than the fixture the clause names, so it is recorded in the Module 11 exemption analysis with this justification, as 2.4.2.1 requires.", "• **Staff food is not stored in the production walk-in refrigerator.** Personal food held among ingredients is a contamination and allergen route, which is why the break room carries its own refrigeration rather than borrowing the walk-in.", "• Where an outside eating area is provided it is kept clean and free from waste materials and maintained so it does not attract pests or introduce contamination to the site.", "PROCESSING PRACTICES (SQF 11.4.1.1 to 11.4.1.4)", "• **Entry to processing areas is through the personnel access doors only.**", "• **All doors are kept closed.** Doors are not left open for extended periods during waste removal or when receiving product, ingredients or packaging.", "• Packaging, product and ingredients are kept in appropriate containers as required and **off the floor**.", "• **Waste** is contained in the bins identified for the purpose and removed from the processing area regularly; it is not left to accumulate.", "• **Wash-down and compressed air hoses** are stored on the hose racks after use and are not left on the floor.", "• Staff shall **not eat or taste any product being processed** in a food handling or contact zone, except under the sensory evaluation controls below.", "• **False fingernails, false eyelashes, eyelash extensions, long nails and fingernail polish are not permitted** when handling exposed food.", "• **Hair restraints and beard covers** are worn wherever product is exposed.", "• **Smoking, chewing, eating and spitting are not permitted** in any area where product is produced, stored or otherwise exposed.", "• **Drinking water** is permitted only under conditions that prevent contamination. Containers shall be clear and covered, and kept in designated areas away from raw materials, packaging, tools and equipment storage.", "• **Personnel flow** is managed so the potential for contamination is minimized: staff move from cleaner to less clean areas rather than back, do not move between an allergen-handling task and exposed non-allergen product without changing protective clothing and washing hands, and do not take traffic through an exposed-product area as a shortcut between other parts of the facility.", "• **Sensory evaluation — product tasting is carried out in the office adjacent to the production area**, which is outside the food handling and contact zones. No tasting of in-process product takes place on the floor (11.4.1.2 i). Product is carried to the office on clean utensils by authorized personnel, and nothing tasted is returned to the process.", "• Should it ever become necessary to evaluate within a food handling or contact zone, the site shall ensure that food safety is not compromised; that the evaluation is conducted by authorized personnel only; that a high standard of personal hygiene is practised by those conducting it; that it is carried out in an area equipped for the purpose; and that equipment used for it is sanitized, maintained and stored separately from processing equipment (11.4.1.4).", "VERIFICATION (SQF 2.5.4.3)", "• **Daily** — the pre-operation inspection under **SOP-11.2.12**, recorded on **FRM-903**, confirms that food-contact surfaces, utensils, production areas and staff amenities are sanitary and that GMP requirements are met before production begins.", "• **Periodic** — planned inspections of the site and equipment verify that this program and facility and equipment maintenance comply with the SQF Food Safety Code: Food Manufacturing. Scope, frequency and responsibility are set in **FSQM-022** (Food Safety Monitoring Program).", "• Findings are recorded. The site shall take corrections or corrective and preventive action, and shall **maintain records of inspections and of any corrective action taken**.", "• Non-compliance with this program by a member of staff or a visitor results in immediate removal from production areas. Repeat violations are documented and handled as a corrective action.", "TRAINING (SQF 2.9.2.1 iii and iv, 2.4.2.2)", "• Every employee who handles food or food-contact surfaces completes **TRN-002 Personal Hygiene & GMPs**, **TRN-002A Personnel Hygiene & Visitor Policy** and **TRN-002B Good Manufacturing Practices**. All three are active, assigned to all staff, and complete for every current member of the team. **TRN-002 exists in English and Spanish; TRN-002A and TRN-002B exist in English only.**", "• **Language (2.9.2.2).** Training on tasks critical to food safety shall be provided in languages understood by staff. One member of production staff is trained in Spanish. She completed all three modules in **English** — including TRN-002, whose Spanish version exists — because her assignments were already complete before the language-aware assignment rules applied, and completed records are deliberately never re-languaged. **This program therefore does not yet meet 2.9.2.2 for Spanish-speaking staff**, and says so rather than letting a completion record imply otherwise. The remedy is recorded in the open actions.", "• Training is delivered at induction, **before the employee works unsupervised in a food handling area**, and refreshed at the frequency set in **SOP-2.9**.", "• Competency is verified on **FRM-952**; attendance on **FRM-953**. Assignment, completion and outstanding training are held in the Team Portal and reported on **REP-951** (Training Matrix).", "• Visitors are briefed through **FRM-906**, which is the visitor training required by 11.3.4.1."], "definitions": "Food handling / contact zone — any area where product, ingredients, primary packaging or food-contact surfaces are exposed. Includes the production floor, the depositing and packing areas, and open ingredient storage.\n\nProtective clothing — outer garments, hairnets, beard covers, aprons, gloves and dedicated footwear or shoe covers worn to protect product, as distinct from personal clothing.\n\nVisitor — any person entering a food handling, processing or storage area who is not an employee of the site, including contractors, maintenance personnel, auditors, suppliers, customers and guests.\n\nEscorted — accompanied at all times by an authorized employee who is responsible for the visitor's compliance with this program.", "responsibility": "SQF Practitioner / QA — owns this program, enforces it, approves exceptions, holds the risk assessments for permitted jewellery, and verifies compliance through GMP inspection.\nSupervisors — ensure staff on their shift comply, act on non-compliance immediately, and receive illness and injury reports.\nAll staff — comply with this program, and report illness, injury and any breach they observe.\nReception / designated staff — ensure every visitor completes FRM-905 and FRM-906 before entry and is escorted or trained.\nMaintenance — maintain handwashing stations, amenities and the facility provisions this program depends on, and correct deficiencies raised by GMP inspection.", "form_references": "FRM-905 — Visitor Sign-In Log\nFRM-906 — Visitor GMP Acknowledgement\nFRM-903 — Daily Sanitation, Pre-Operation & Release Record\nFRM-901 — Master Sanitation Schedule (amenity cleaning is scheduled here)\nFRM-907 / FRM-908 — Glass & Brittle Plastic Register / Glass Breakage Incident Report\nFRM-952 / FRM-953 — Training Competency Verification Record / Training Sign-In Sheet\nREP-951 — Training Matrix\nSOP-11.2.12 — GMP / Pre-Operation Inspection\nSOP-11.7.3 — Glass & Brittle Plastic Control\nFSQM-027 — Allergen Management Program\nSOP-2.9 — Training & Recordkeeping\nFSQM-013 — Module 11 Applicability & Exemption Analysis (what this program does not claim)\nFSQM-022 — Food Safety Monitoring Program", "revision_history": "New — 2026-09-01 — Initial issue. Written to close SQF 2.4.2.2, which requires the site's applicable Good Manufacturing Practices to be documented. Covers Module 11.3 and 11.4 in full — thirty-five clauses, of which SOP-11.3 addressed about nine.\n\nSUPERSEDES SOP-11.3 Personnel Hygiene & Visitor Policy. Its dress code, jewellery list, visitor requirements, twelve-month retention and corrective-action clause are carried forward here, extended rather than rewritten. SOP-11.3 remains the active controlled document until this program is approved and issued; it is archived in the same transaction that activates this one, so the site is never without an active personnel hygiene document.\n\nSITE ARRANGEMENTS CONFIRMED 2026-09-01 by Richard Mercer. The facility facts in this program are the site's own answers, not assumptions: three handwashing stations (one in each lavatory, one immediately inside the production access point, which is the floor's only entrance from non-production space) with hot and cold potable water, waste bins, soap from a hands-free dispenser and towels that can be taken without touching the housing; handwash signage in the break room, at its exit, in both toilet rooms and at the production entrance, in English and Spanish; no designated high-risk area; protective clothing laundered by employees at home with detergent and hung to dry; footwear controlled by two sanitizing foot baths, at the production entrance and at the walkthrough to the inventory and packaging area, dosed with Sani-512 at 1:160, made up in separate clearly labelled containers from the 1:512 food-contact solution, and thoroughly cleaned monthly, with the solution changed on condition rather than on a fixed interval; ceramic handwash basins, and the protective clothing rack installed at the production entrance; changing done in the toilet rooms, personal items in break room lockers; the employee lavatory reached through a vented airlock; sanitary drainage separate and compliant; the break room separate from food zones, lit, ventilated, with a refrigerator, a microwave and a table seating all employees at one sitting, and with disposable utensils so nothing is washed up there; no fixed illness exclusion interval — supervisor clearance is the control; product tasting carried out in the office adjacent to production, never on the floor.\n\nOPEN ACTIONS AT ISSUE — two items. The forms now carry every check this program states: the daily foot bath check is a grid in section 3 of FRM-903, the monthly strip-down is on the FRM-901 schedule and in its task picker, and the ceramic basin at the production entrance is on the FRM-907 register (FRM-901 rev B, FRM-903 rev v6, FRM-907 rev v2, all effective 2026-09-01). What is left is one confirmation and one purchase.\n1. CONFIRM — the 1:160 figure against the product label. The 1:512 food-contact dilution was checked against the Sani-512 label on 2026-08-25; this foot-bath ratio has not been. A sanitizer used at a dilution its label does not carry is a label-use problem before it is an SQF problem, so confirm 1:160 appears on the label for this use — and while doing it, add the label and SDS to the Chemical Safety Data Sheets collection, which still holds only a generated summary.\n2. ACTION — high-range quat test strips for the foot baths. At 1:160 the bath runs at roughly three times the food-contact strength, which is off the top of the 0-400 ppm strips used on equipment: those will simply read high and tell the checker nothing. FRM-903's foot bath grid now carries that warning on its own label, so the person holding the strip sees it — but the strip still has to exist. Keep it with the baths, separate from the food-contact strips, for the same reason the two dilutions are made up in separately labelled containers.\n\nCARRIED INTO FSQM-013 (Module 11 Applicability & Exemption Analysis), issued 2026-09-01 under task 13.6. Two arrangements meet what a clause protects without being the fixture it names, and both now carry their written justification there: the absent break room utensil sink (11.3.5.9 iii), where nothing is washed up because utensils are disposable and personal items go home; and the paper towel dispenser (11.3.2.3 iii), which has no no-touch mechanism though a towel is taken without contacting the housing. FSQM-013 also records the high-risk clauses this program states are not engaged, and lists six Module 11 questions still needing a site answer.\n\nISSUED 2026-09-01, approved GJM. SOP-11.3 Personnel Hygiene & Visitor Policy is archived in the same transaction and is superseded by this program in full. Its dress code, jewellery list, visitor requirements, twelve-month retention and corrective-action clause are carried forward here; nothing it stated has been dropped.\n\n\nTRAINING VERIFIED 2026-09-01 under D-13 task 13.8. The training limb of 2.4.2.2, and 2.9.2.1 (iii) personal hygiene and (iv) Good Manufacturing Practices, are met by three active modules — TRN-002, TRN-002A and TRN-002B — assigned to all three members of the team, with all nine assignments complete. Records are held in the Team Portal and reported on REP-951; competency is verified on FRM-952 and attendance on FRM-953.\n\nPART 10 IS CORRECTED IN THE SAME BREATH, because as issued it was wrong. It said the modules are “available in English and Spanish and assigned in the language the employee is trained in”. Neither half held: TRN-002A and TRN-002B exist in English only, and the one Spanish-preferring member of staff completed all three in English. A claim that an auditor could disprove by asking one employee what language they trained in is worse than no claim, so Part 10 now states what is actually true and names the gap.\n\nOPEN ACTIONS AT ISSUE — a third item joins the two already listed.\n3. SPANISH TRAINING FOR 2.9.2.2. Two things are needed and they are different sizes. (a) TRN-002 already has an active Spanish deck, so a Spanish-preferring employee can be assigned it directly — this is an assignment decision, not a build, and it affects a real person's training record, so it is left to the SQF Practitioner rather than done by migration. (b) TRN-002A and TRN-002B have no Spanish version and no generator source in the repository, so producing one means either translating the original decks or authoring the content afresh from the existing English narrations. That is a build, not an afternoon. Until both are done, the position stated in Part 10 stands.\n\n\n\nv3, 2026-10-01 — VISITOR ACKNOWLEDGEMENT SIGNED ONCE, NOT AT EVERY VISIT. Part 6 required every visitor to read and acknowledge the rules on FRM-906 before entry, which in practice meant at every entry. 11.3.4.1 requires that a visitor is trained before entering or is escorted; a briefing given and signed for remains given. The acknowledgement is now completed on the first visit and renewed every twelve months and whenever FRM-906 is revised. The health declaration, which concerns the day of the visit, is made on FRM-905 at every visit, and each FRM-905 entry records the acknowledgement it relied on. Retention is extended so that an acknowledgement is kept for twelve months after the last visit that relied on it. The visitor's signature on both forms is now the visitor's own, drawn on the device, with the host recorded as witness.\n\nv4 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the three references to it now name FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — Module 11.3 (Personnel Hygiene, 11.3.1.1 to 11.3.5.10) and Module 11.4 (Personnel Processing Practices, 11.4.1.1 to 11.4.1.4).\nSQF Food Safety Code: Food Manufacturing, Edition 9 — System Elements 2.4.2.1 (GMPs applied or exempted by written risk analysis), 2.4.2.2 (GMPs documented and implemented), 2.5.4.3 (planned site and equipment inspections with corrective action and records), and 2.9.2.1 iii and iv (personal hygiene and Good Manufacturing Practices training).\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice, in particular §117.10 (Personnel) and §117.20 (Plant and grounds)."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '79e050a4-e186-405f-a0d1-1c356d4a3dc6' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "The mixer, its bowl, and its agitators (paddle, whip, dough arm). Cleaning is done at the end of every production day the mixer is used, and again between products when the allergens differ.\n\nOperating the mixer is SOP-501. Lubrication and repairs are Maintenance, not sanitation.", "purpose": "To clean and sanitize the Hobart V-1401 mixer after production so it is safe and ready for the next day's batch.", "records": "The clean and its pre-use release are recorded on FRM-909, retained per the record retention policy.", "procedure": ["Before you start: unplug the mixer before wiping it, and never hose or pressure-wash it — damp cloth only. Water driven into the electrics or the transmission will destroy the machine (the manufacturer's own instruction).", "The machine: lower the bowl and unplug the power.", "Remove the bowl and the agitator.", "Dry wipe the whole machine — top, levers and controls, column, bowl yoke and support, down to the footers. Get loose flour and dried batter off before any water.", "Wet wipe with a damp cloth and detergent, same coverage, top down; wipe off the detergent with a second cloth and clean water, and let it air dry.", "Check the drip cup under the planetary is clean and dry. If there is oil in it, do not run the machine — tell the Supervisor and Maintenance (it sits directly over the bowl, so oil there can get into product).", "Plug the mixer back in once everything is dry and reassembled.", "The bowl: break it down and remove all residual ingredients; rinse with warm water; scrub with detergent; empty out.", "Run the bowl through the pan washer on the high-temperature cycle — the hot final rinse is what sanitizes it, so the cycle temperature matters. Store clean, dry and inverted. If the washer is down, wash and sanitize the bowl by hand in the sink the same way as the agitators.", "The paddle, whip and dough arm: wash in the sink — detergent, rinse, Noble Sani-512 at the food-contact dilution of 1:512 (1 fl oz per 4 gallons of water, or 0.25 oz per gallon; about 200 ppm quat on a test strip), then onto the drying rack to air dry. Sani-512 is a no-rinse sanitizer at this dilution — do not rinse it off, and do not towel them dry; either one undoes the sanitizing.", "Check the sanitizer strength with a test strip before you wash — the target is about 200 ppm quat — and record the reading on FRM-909. If the strip reads below target, remake the solution; do not wash in weak sanitizer. Wear gloves and eye protection while you measure and pour the concentrate — undiluted Sani-512 is rated DANGER and causes severe skin burns and serious eye damage. Once it is mixed at 1:512 the working solution is not corrosive, so this is about making the solution up, not about using it.", "Allergen changeover (a different allergen next): follow the changeover rule in FSQM-027 Allergen Management Program. On top of the clean above, check every food contact surface under good light before the next product — bowl inside and under the rim, the agitator including the wire crossings and the shank, and the agitator shaft. Re-clean anything you can see.", "Before the next run: the Supervisor checks and signs the release on FRM-909 — bowl, agitator and machine clean and dry; drip cup clear of oil; nothing left on the machine; sanitizer strength recorded. The mixer is not ready for production until FRM-909 is signed."], "attachments": [{"name": "Hobart_V1401_Manual.pdf", "path": "39829bcd-18b8-4f18-b693-f6ad48ea8cf2/files/Hobart_V1401_Manual.pdf"}], "responsibility": "Sanitation / Production staff — perform the cleaning and record it on FRM-909.\nSupervisor — checks the machine before the next run and signs the release on FRM-909.\n\nThe clean and its pre-use release are recorded on FRM-909 because the plant sanitation forms cannot hold them: FRM-901 Master Sanitation Schedule and FRM-902 Sanitation Verification Log are Word-document attachments (not fillable), and FRM-903 GMP Pre-Operation Inspection is scoped to the glass dial cover / MIG thermometer check. The mixer should still be listed on the FRM-901 Master Sanitation Schedule for its cleaning frequency.", "form_references": "FRM-909 — Mixer Cleaning & Pre-Use Check Log (the clean and its pre-use release)\nFRM-901 — Master Sanitation Schedule (list the mixer as a line to set its cleaning frequency)\nFSQM-027 — Allergen Management Program (allergen changeover)\nSOP-501 — Operating the Hobart V-1401 Mixer", "revision_history": "New — 2026-07-24 — Initial issue. Written to the cleaning process actually performed on the floor; records on FRM-909.\r\nv2 — 2026-08-22 — Named the sanitizer. The sink wash now specifies Noble Sani-512 at the food-contact dilution 1:512 (1 fl oz per 4 gallons, about 200 ppm quat), states that it is no-rinse, and gives the test-strip target and what to do when it reads low. Cleaning process itself unchanged.\n\nv4 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.5.1 (documented cleaning method), 11.2.5.3 (mixed sanitizer concentration correct and recorded), 11.2.5.7 (inspection before production).\nHobart Corporation Form 13966A Rev. 6-82 — Instruction Manual, Model V-1401 Series Mixers (clean daily; no hose; damp cloth only).\nNoble Chemical Sani-512 (quaternary sanitizer) — food-contact use at 1:512 (1 fl oz per 4 gallons), about 200 ppm quat; no-rinse: wet the surface at least 1 minute and let it air dry. The SDS for the concentrate (Clark Core Services, revised 2021-07-15; EPA reg. 6836-266-65239) classifies it DANGER — H302 harmful if swallowed, H314 causes severe skin burns and eye damage, H318 causes serious eye damage — and requires gloves and eye/face protection when it is handled.\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '39829bcd-18b8-4f18-b693-f6ad48ea8cf2' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "The depositor and its food-contact parts. Hopper, the two feed rollers, the die and the scrapers come off and are washed in the sink. The cut-off wire and its support fingers stay on the machine — it isn't practical to take the wire off, so they are wiped clean in place. Cleaning is done at the end of every production day the machine is used, and a full clean again between products when the allergens differ.\n\nOperating the depositor is SOP-502. Lubrication and repairs are Maintenance, not sanitation.", "purpose": "To clean and sanitize the Kook-E-King cookie depositor after production so it is safe and ready for the next day's run.", "records": "The clean and its pre-use release are recorded on FRM-910, retained per the record retention policy.", "procedure": ["Before you start: stop with the wire clear of the die (furthest-back position), then unplug the machine. Never hose or pressure-wash the machine — damp cloth only on the cabinet and depositing head. Water in the control panel or the motors will destroy it (the manufacturer's own warning).", "Break it down: swing the side guard open and remove the gear guard; loosen the hopper knobs, release the hopper hooks and lift the hopper straight up off the head; remove the feed rollers and scrape the dough out of the roller grooves with the roller scraper (don't remove the gears); support the die, loosen the six thumbscrews and let it drop out below; remove the scrapers; save reusable dough from between the rollers and die for the next run. The hopper, feed rollers, die and scrapers go to the sink; the cut-off wire and support fingers stay on.", "The machine (wipe only): clear dough fragments from the die slot and the inside of the depositing head where the rollers sit; dry wipe the head interior, top of the cabinet and the table belts to get loose dough off; damp wipe the same surfaces with detergent, wipe clean with a second damp cloth and let air dry. No excessive water; nothing on the control panel.", "Wash the removable parts in the sink: the hopper, feed rollers, die and scrapers are washed detergent, rinse, Noble Sani-512 at the food-contact dilution of 1:512 (1 fl oz per 4 gallons of water, or 0.25 oz per gallon; about 200 ppm quat on a test strip), then onto the drying rack to air dry. Sani-512 is a no-rinse sanitizer at this dilution — don't rinse it off, and don't towel them dry; either one undoes the sanitizing. Store clean, dry and protected.", "Check the sanitizer strength with a test strip before you wash — the target is about 200 ppm quat — and record the reading on FRM-910. If the strip reads below target, remake the solution; do not wash in weak sanitizer. Wear gloves and eye protection while you measure and pour the concentrate — undiluted Sani-512 is rated DANGER and causes severe skin burns and serious eye damage. Once it is mixed at 1:512 the working solution is not corrosive, so this is about making the solution up, not about using it.", "The cut-off wire and fingers — wipe in place + foreign-matter check: the wire and its support fingers stay on the machine; wipe them clean in place, don't run them through the sink. While wiping, check the wire is whole (not frayed, kinked or missing a section) and that there is still one support finger seated in each die slot. If any piece of wire is missing, find it before the machine runs again and hold any product that could be affected (a broken wire is metal in the product). If the wire is frayed or damaged, fit a fresh assembly (Maintenance) before the next run.", "Allergen changeover (a different allergen next): follow the changeover rule in FSQM-027 Allergen Management Program. On top of the clean above, check every food-contact surface under good light before the next product — the die holes, the roller grooves, the hopper, the wire and fingers, and the scrapers. Re-clean anything you can see.", "Reassemble: reinstall the die (finger-tight only) in a clean slot and the feed rollers (food-safe oil on the bushings — see SOP-502), refit the hopper, confirm a support finger is seated in each die slot, and return both guards to their locked positions.", "Before the next run: the Supervisor checks and signs the release on FRM-910 — hopper, rollers, die and scrapers clean and dry; wire and fingers wiped clean and the wire accounted for; machine wiped down with nothing left on it and guards locked; sanitizer strength recorded. The depositor is not ready for production until FRM-910 is signed."], "responsibility": "Sanitation / Production staff — perform the cleaning and record it on FRM-910.\nSupervisor — checks the machine before the next run and signs the release on FRM-910.\n\nThe clean and its pre-use release are recorded on FRM-910 because the plant sanitation forms cannot hold them: FRM-901 Master Sanitation Schedule and FRM-902 Sanitation Verification Log are Word-document attachments (not fillable), and FRM-903 GMP Pre-Operation Inspection is scoped to the glass dial cover / MIG thermometer check. The depositor should still be listed on the FRM-901 Master Sanitation Schedule for its cleaning frequency.", "form_references": "FRM-910 — Depositor Cleaning & Pre-Use Check Log (the clean and its pre-use release)\nFRM-901 — Master Sanitation Schedule (list the depositor as a line to set its cleaning frequency)\nFSQM-027 — Allergen Management Program (allergen changeover)\nSOP-502 — Operating the Rhodes Kook-E-King Cookie Depositor", "revision_history": "New — 2026-07-24 — Initial issue. Written to the process actually performed on the floor: hopper, rollers, die and scrapers washed in the sink; cut-off wire and fingers wiped in place; cabinet/head/belts wiped; food-safe oil on the bushings. Records on FRM-910.\r\nv2 — 2026-08-22 — Named the sanitizer. The sink wash now specifies Noble Sani-512 at the food-contact dilution 1:512 (1 fl oz per 4 gallons, about 200 ppm quat), states that it is no-rinse, and gives the test-strip target and what to do when it reads low. Cleaning process itself unchanged.\n\nv4 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.5.1 (documented cleaning method), 11.2.5.3 (sanitizer concentration verified and recorded), 11.2.5.7 (inspection before production).\nPractical Baker — Rhodes Kook-E-King Super Automatic Instruction Manual, V.3B Jan 2013 (clean the head/cabinet with a damp cloth; no excessive water; nothing on electrical components).\nNoble Chemical Sani-512 (quaternary sanitizer) — food-contact use at 1:512 (1 fl oz per 4 gallons), about 200 ppm quat; no-rinse: wet the surface at least 1 minute and let it air dry. The SDS for the concentrate (Clark Core Services, revised 2021-07-15; EPA reg. 6836-266-65239) classifies it DANGER — H302 harmful if swallowed, H314 causes severe skin burns and eye damage, H318 causes serious eye damage — and requires gloves and eye/face protection when it is handled.\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'a48f7a01-3847-4be8-9df8-ef44fa51d20a' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "The depositor and its product-contact parts — nozzle, hopper, rotation cylinder, hopper block, product cylinder, piston, and all seals / O-rings — washed in the sink. The air cylinders and the machine body are wiped only, never submerged. Cleaning is done at the end of every production day the machine is used, and a full clean again between products (always when the allergens differ).\n\nOperating the depositor is SOP-503. The seal-replacement schedule, air system and repairs are Maintenance, not sanitation.", "purpose": "To clean and sanitize the Beldos 275 depositor after production so it is safe and ready for the next run.", "records": "The clean and its pre-use release are recorded on FRM-911, retained per the record retention policy.", "procedure": ["Two rules before you start: (1) turn the machine OFF, then disconnect the air line and bleed off the pressure before you touch anything — nothing comes apart until the air is off; (2) never submerge the air cylinders or the machine body in water — wipe them only; water in the air cylinders will damage the machine (the manufacturer's own warning).", "Disassemble: take the depositor fully apart — nozzle, then hopper (and its seal), then rotation cylinder (release the hook), then hopper block and pin, then product cylinder, then piston. Then remove every seal / O-ring from the pistons, cylinders and spouts — they all come off for a proper clean. Scrape/empty any product left in the parts before washing.", "Wash the parts in the sink: the product-contact parts and all the seals are washed in the sink — lukewarm water + soft detergent, rinse, Noble Sani-512 at the food-contact dilution of 1:512 (1 fl oz per 4 gallons of water, or 0.25 oz per gallon; about 200 ppm quat on a test strip), then onto the drying rack to air dry. Sani-512 is a no-rinse sanitizer at this dilution — don't rinse it off, and don't towel them dry; either one undoes the sanitizing. Store clean, dry and protected. Check the sanitizer strength with a test strip before you wash — the target is about 200 ppm quat — and record the reading on FRM-911. If the strip reads below target, remake the solution; do not wash in weak sanitizer. Wear gloves and eye protection while you measure and pour the concentrate — undiluted Sani-512 is rated DANGER and causes severe skin burns and serious eye damage. Once it is mixed at 1:512 the working solution is not corrosive, so this is about making the solution up, not about using it.", "The machine body (wipe only): wipe the base, the air cylinders and the outside of the machine with a damp cloth. Never submerge them. Nothing wet goes near the air fittings.", "Inspect the seals — wear and foreign matter: every seal/O-ring is rubber that wears, and a worn seal both spoils the deposits and can shed rubber into product. So at each clean, inspect every seal for wear, splits, flattening or missing pieces; replace any worn or damaged seal before reassembly (and keep to Maintenance's replacement schedule — the weekly O-ring check / O-ring board). If a seal is torn or a piece is missing, find the piece and hold any product that could be affected (see SOP-503) before the machine runs again.", "Changing between products with different allergens: follow FSQM-027 Allergen Management Program — it governs allergen changeover on all shared equipment, including this depositor. On top of the clean above, check every food-contact surface under good light before the next product: inside the cylinders and hopper block, the piston, the nozzle bore, and the rotation cylinder. Anything you can see, re-clean.", "Reassemble and release: reassemble with every seal in place and greased (Beldos food-approved grease), all clamps tight, and the correct nozzle fitted; refit the safety connector. The Supervisor checks and signs the release on FRM-911 — all parts clean and dry and the machine body wiped; seals inspected, worn ones replaced, none torn or missing a piece; clamps tight, correct nozzle fitted, nothing left on the machine; sanitizer strength recorded. The depositor is not ready for production until FRM-911 is signed."], "responsibility": "Sanitation / Production staff — perform the cleaning, inspect the seals, and record it on FRM-911.\nSupervisor — checks the machine before the next run and signs the release on FRM-911.\n\nThe clean and its pre-use release are recorded on FRM-911 because the plant sanitation forms cannot hold them: FRM-901 Master Sanitation Schedule and FRM-902 Sanitation Verification Log are Word-document attachments (not fillable), and FRM-903 GMP Pre-Operation Inspection is scoped to the glass dial cover / MIG thermometer check. The depositor should still be listed on the FRM-901 Master Sanitation Schedule for its cleaning frequency.", "form_references": "FRM-911 — Depositor Cleaning & Pre-Use Check Log (the clean and its pre-use release)\nFRM-901 — Master Sanitation Schedule (list the depositor as a line to set its cleaning frequency)\nFSQM-027 — Allergen Management Program (allergen changeover)\nSOP-503 — Operating the Beldos 275 Depositor", "revision_history": "New — 2026-07-25 — Initial issue. Written to the daily disassembly the machine requires: all product-contact parts and seals washed in the sink; air cylinders/body wiped only; seals inspected and greased with food-approved grease. Records on FRM-911.\r\nv2 — 2026-08-22 — Named the sanitizer. The sink wash now specifies Noble Sani-512 at the food-contact dilution 1:512 (1 fl oz per 4 gallons, about 200 ppm quat), states that it is no-rinse, and gives the test-strip target and what to do when it reads low. Cleaning process itself unchanged.\n\nv4 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.5.1 (documented cleaning method), 11.2.5.3 (sanitizer concentration verified and recorded), 11.2.5.7 (inspection before production).\nBeldos N.V. — Manual for end user, Depositor 275 series, © 2020 (disassemble and wash daily; remove all seals for cleaning; do not submerge the air cylinders).\nNoble Chemical Sani-512 (quaternary sanitizer) — food-contact use at 1:512 (1 fl oz per 4 gallons), about 200 ppm quat; no-rinse: wet the surface at least 1 minute and let it air dry. The SDS for the concentrate (Clark Core Services, revised 2021-07-15; EPA reg. 6836-266-65239) classifies it DANGER — H302 harmful if swallowed, H314 causes severe skin burns and eye damage, H318 causes serious eye damage — and requires gloves and eye/face protection when it is handled.\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '4bb5140d-5577-4482-86b7-0d41986b4728' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "The kettle's food-contact surfaces — the interior, the rim and pouring lip, the cover, and any baskets/strainers used — plus the outside, controls and housing. The kettle is cleaned in place (it isn't taken apart or put in a sink). Cleaning is done at the end of every production day the kettle is used — as soon as possible after use, while the kettle is still warm — and a full clean again between products when the allergens differ.\n\nOperating the kettle is SOP-504. Jacket water, greasing and repairs are Maintenance, not sanitation.", "purpose": "To clean and sanitize the Groen kettle so it is safe and ready for the next batch.", "records": "The clean and its pre-use release are recorded on FRM-912, retained per the record retention policy.", "procedure": ["Two rules before you start: (1) turn the thermostat to OFF and unplug it before cleaning; let the kettle cool enough to work safely — but clean while still warm, not cold, so residue lifts easily. (2) Keep water and cleaning solutions out of the controls and electrical parts, and never use a high-pressure hose on the kettle; the outside is washed with warm water only.", "Scrape and wash: scrape and flush out large food residues using the kettle brushes / plastic or rubber scrapers — no metal tools, no steel wool, no abrasive pads (scratches harbor bacteria and steel wool leaves particles that corrode the stainless). Wash the inside and outside with detergent solution at label strength; for burned-on residue, let the detergent soak a few minutes, then brush — don't gouge it off. Don't forget the rim and pouring lip, the underside of the cover, baskets/strainers, and wipe the controls and housing with a cloth moistened with cleaning solution.", "Rinse and drain: rinse thoroughly with hot water and drain the kettle completely. If a hard-water film or mineral deposit is left, use a de-liming agent per its label.", "Sanitize (Noble Sani-512, no-rinse): after cleaning and draining, sanitize the food-contact surfaces with Noble Chemical Sani-512 mixed for food-contact use at 1:512 — 1 fl oz per 4 gallons of water (0.25 oz per gallon). Wet every food-contact surface and leave it for at least 1 minute, then let it air dry; Sani-512 is a no-rinse sanitizer at this dilution — do not rinse it off. Record the sanitizer strength on FRM-912. Wear gloves and eye protection while you measure and pour the concentrate — undiluted Sani-512 is rated DANGER and causes severe skin burns and serious eye damage. Once it is mixed at 1:512 the working solution is not corrosive, so this is about making the solution up, not about using it. Sanitize again just before the next use (the release step).", "Changing between products with different allergens: follow FSQM-027 Allergen Management Program — it governs allergen changeover on all shared equipment, including this kettle. On top of the clean above, check every food-contact surface under good light before the next product: the kettle interior and bottom, the rim and pouring lip, under the cover, and any baskets or strainers. Anything you can see, re-clean.", "Before the next run — release: the Supervisor checks and signs the release on FRM-912 — kettle clean inside and out (rim, pouring lip, cover and any baskets clean); no detergent residue, food-contact surfaces sanitized with Sani-512 and air-dried, sanitizer strength recorded; sanitized just before use; jacket water level at the sight-glass midpoint (from SOP-504's daily check). The kettle is not ready for production until FRM-912 is signed."], "responsibility": "Sanitation / Production staff — perform the cleaning and record it on FRM-912.\nSupervisor — checks the kettle before the next run and signs the release on FRM-912.\n\nThe clean and its pre-use release are recorded on FRM-912 because the plant sanitation forms cannot hold them: FRM-901 Master Sanitation Schedule and FRM-902 Sanitation Verification Log are Word-document attachments (not fillable), and FRM-903 GMP Pre-Operation Inspection is scoped to the glass dial cover / MIG thermometer check. The kettle should still be listed on the FRM-901 Master Sanitation Schedule for its cleaning frequency.", "form_references": "FRM-912 — Kettle Cleaning & Pre-Use Check Log (the clean and its pre-use release)\nFRM-901 — Master Sanitation Schedule (list the kettle as a line to set its cleaning frequency)\nFSQM-027 — Allergen Management Program (allergen changeover)\nSOP-504 — Operating the Groen TDB Steam-Jacketed Kettle", "revision_history": "New — 2026-07-25 — Initial issue, written as a clean-in-place process from the Groen/Unified Brands operator manual: scrape (no metal/steel wool) → detergent wash inside & out → hot-water rinse & drain → sanitize with Noble Sani-512 quat (1:512, no-rinse — wet ≥1 min, air dry) → sanitize just before use. End-of-production-day frequency; hand-tilt (TDB). Records on FRM-912.\n\nv3 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.5.1 (documented cleaning method), 11.2.5.3 (sanitizer concentration verified and recorded), 11.2.5.7 (inspection before production).\nUnified Brands / Groen — TDB/TDBC Steam Jacketed Kettle Operator Manual (P/N 148733) — clean food contact surfaces after use while warm; no metal tools / steel wool; keep water out of the controls; sanitize just before use.\nNoble Chemical Sani-512 (quaternary sanitizer) — food-contact use at 1:512 (1 fl oz per 4 gallons); no-rinse: wet the surface at least 1 minute and let it air dry. The SDS for the concentrate (Clark Core Services, revised 2021-07-15; EPA reg. 6836-266-65239) classifies it DANGER — H302 harmful if swallowed, H314 causes severe skin burns and eye damage, H318 causes serious eye damage — and requires gloves and eye/face protection when it is handled.\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '18c0a2c5-2ba7-4708-bbfb-d49c53ab6984' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Two different items are called \"pans\" on the floor. This SOP covers the first:\n\nMolds — the vessels the cake is baked in and depanned from. Direct food contact. Cared for between uses and washed by hand in the three-compartment sink. This SOP.\n\nCarrier pans — the trays the molds sit on in the oven. No direct food contact. Run through the pot & pan washer, SOP-905.\n\nAlso covered here: utensils, scoops and small parts washed by hand in the same sink.\n\nFrequency: molds are scraped, wiped and re-greased every use, and given a full wash weekly. They are NOT washed between every bake by design — repeated detergent washing strips the release surface, and a stripped mold sticks and leaves more residue, not less. The weekly interval yields immediately to the triggers in step 5.\n\nNot covered: machine parts, which are cleaned under their own SSOPs — SOP-901 (mixer), SOP-902 and SOP-903 (depositors), SOP-904 (kettle).", "purpose": "To keep the baking molds clean and fit for use — the scrape, wipe and re-grease done between every use, and the full wash in the three-compartment sink on schedule.", "records": "The before-use check, the wash, the sanitizer strength and the release are recorded on FRM-903, retained per the record retention policy. The weekly wash is scheduled on FRM-901. Molds do not have a separate cleaning log: unlike the machines, they are batch-washed on a schedule rather than released per machine per run.", "procedure": ["BETWEEN EVERY USE — scrape and wipe. As soon as the cakes are depanned, scrape out the loose crumb and wipe the mold down. Use a clean cloth kept for this job; a cloth carried over from another surface brings that surface's soil into the mold.", "BETWEEN EVERY USE — fresh release every time. Apply fresh grease or release spray to every mold before it is filled, whatever its position in the wash cycle. This is what keeps the surface working and is the reason the full wash can be weekly rather than daily.", "BETWEEN PRODUCTION DAYS — cover and refrigerate. Molds held over to the next production day are covered and kept in the refrigerator. Covered so nothing can fall into them; refrigerated so any residue left on them does not develop. Keep them in their designated place, not among ingredients or finished product.", "BEFORE EVERY USE — check the mold. It must be dry, free of visible residue or sticky build-up, and undamaged, with the release coat freshly applied. Record the check on FRM-903. Anything that fails goes for a full wash before it is used, whatever the schedule says.", "WASH SCHEDULE — weekly, and sooner whenever any of these happen: an allergen changeover (follow FSQM-027); a change of product; visible residue or sticky build-up the wipe does not remove; a release surface that has gone patchy or is sticking; or any incident where a mold has been contaminated. The trigger always beats the schedule.", "WASH — pre-soak first. Heavy baked-on cake does not come off in a wash sink; it has to be softened. Fill the soak with hot water deep enough to cover the soiled surfaces and leave the molds until the residue lifts. Do not let molds dry out with cake baked on — once it hardens, the only way back is scrubbing hard enough to scratch the surface, and a scratched mold holds soil and stops releasing.", "WASH — scrape and empty. Lift out the softened residue and empty it to waste before the wash sink; soil carried into sink 1 spends the detergent.", "WASH — sink 1, wash. Dawn Professional at 1-2 oz per 10 gallons of hot water. Make up a fresh sink when the water is soiled or has gone cold.", "WASH — sink 2, rinse. Clean potable water. Rinse the detergent off completely; detergent carried into sink 3 weakens the sanitizer.", "WASH — sink 3, sanitize. Noble Sani-512 at the food-contact dilution of 1:512 (1 fl oz per 4 gallons of water, or 0.25 oz per gallon; about 200 ppm quat on a test strip). Immerse for at least 1 minute, then air dry on the rack. Sani-512 is a no-rinse sanitizer at this dilution — do not rinse it off, and do not towel the molds dry; either one undoes the sanitizing.", "WASH — check the sanitizer strength with a test strip before you wash, target about 200 ppm quat, and record the reading on FRM-903. If the strip reads below target, remake the solution; do not wash in weak sanitizer. Wear gloves and eye protection while you measure and pour the concentrate — undiluted Sani-512 is rated DANGER and causes severe skin burns and serious eye damage. Once it is mixed at 1:512 the working solution is not corrosive, so this is about making the solution up, not about using it.", "WASH — inspect every mold before it goes back into service. Look for chips, cracks, splits, flaking coating or deformation. A damaged mold is a foreign-body route into product — take it out of service and tell the Supervisor. Do not return it to the rack \"for now\". Re-grease before the next fill.", "Store molds clean, dry, covered and protected. Do not stack them wet.", "Before the molds go back into service after a wash, the Supervisor checks and signs the release on FRM-903 — molds clean, dry and undamaged; sanitizer strength recorded."], "responsibility": "Sanitation / Production staff — perform the between-use care and the weekly wash, and record the wash and the sanitizer strength on FRM-903.\nSupervisor — verifies the molds before they go back into service and signs the release on FRM-903.", "form_references": "FRM-903 — Daily Sanitation, Pre-Operation & Release Record (the before-use check, the wash, the sanitizer strength and the release)\nFRM-901 — Master Sanitation Schedule (carries the weekly mold wash as a scheduled line)\nFSQM-027 — Allergen Management Program (allergen changeover)\nSOP-905 — Operating the Pot & Pan Washer (the carrier pans the molds sit on)", "revision_history": "New — 2026-08-26 — Initial issue, approved GJM. Closes the gap found when the pot & pan washer turned out to cover only the non-food-contact carrier pans, leaving the molds — a direct food-contact surface — with no documented cleaning method. Written as between-use care (scrape, wipe, fresh release) plus a weekly wash with out-of-schedule triggers, which is the process actually performed; the wash steps follow the sink process already described in SOP-901/902/903.\n\nCommitted at issue, to be closed and recorded as revisions to this SOP:\n1. Pre-soak — confirm whether a chemical is used, at what strength, and a typical soak time. Step 6 currently says hot water only; a soak product would be named there and its SDS added to the Chemical Safety Data Sheets collection.\n2. Validate the weekly wash interval — swab or test at the END of the interval rather than the start, or adopt the parent facility's validation if it holds data for the same cycle. The interval is set by practice today; validation is what makes it a control.\n3. Designate the storage location for covered molds in the refrigerator, away from ingredients and finished product.\n\nv2 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.5.1 (documented cleaning method at a frequency that keeps food-contact surfaces clean), 11.2.5.3 (detergent and sanitizer concentration verified and recorded), 11.2.5.7 (inspection before production).\nDawn Professional Dish Detergent Concentrate — 1-2 oz per 10 gallons; wash, rinse with potable water, sanitize and air dry as a three-step process (manufacturer's use instructions).\nNoble Chemical Sani-512 (quaternary sanitizer) — food-contact use at 1:512 (1 fl oz per 4 gallons), about 200 ppm quat; no-rinse: wet the surface at least 1 minute and let it air dry. The SDS for the concentrate (Clark Core Services, revised 2021-07-15; EPA reg. 6836-266-65239) classifies it DANGER — H302 harmful if swallowed, H314 causes severe skin burns and eye damage, H318 causes serious eye damage — and requires gloves and eye/face protection when it is handled.\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'db25397d-d4a3-49ee-9222-eca3ba47131d' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"scope": "Production staff setting up, running, or unloading the depositor for any product it deposits (batter, filling, cream).\n\nCleaning is SOP-903. The seal-replacement schedule, air system, and repairs are Maintenance — operators change a seal only as trained.", "purpose": "To set up and run the Beldos 275 depositor safely and get accurate, consistent deposits.\n\nTwo things about this machine drive the rules below. It is air-powered — always bled and disconnected from the air before it's opened. And it runs on rubber seals / O-rings: a worn seal gives bad deposits and can shed rubber into the product, so seals are watched, inspected, and changed on a schedule.", "records": "Deposit settings (nozzle, cylinder size, speed, volume %) go on the batch sheet / settings chart. The clean and the pre-use release are recorded on FRM-911. Operator training sign-off is held in the training record. All retained per the record retention policy.", "procedure": ["Before you start — training: do not operate this depositor unless the Supervisor has trained and signed you off.", "Pre-start checks (machine OFF): FRM-911 is signed for this shift (if not, the machine hasn't been released for production); the depositor is fully assembled with all seals in place and greased (Beldos food-approved grease), all clamps tight, and the correct nozzle fitted — before the hopper is filled; air is fed through the air dryer and set to max 7 Bar / 102 PSI (never higher); the frame wheel brakes are engaged; any part new or just back from cleaning that touches product has been washed in hot water and detergent first (stainless parts carry a factory protective coating). Anything fails → don't run it; tag it and tell the Supervisor.", "Get yourself ready: sleeves down and secured, no dangling ties or lanyards, no rings, watches or bracelets, hair fully in a hairnet. Keep fingers and hands away from moving parts and the deposit outlet.", "Set the deposit — Speed: set the Speed Control OUT knob (clockwise slows, counter-clockwise speeds up); for heavy or aerated products (mousse, meringue) Maintenance can raise the internal speed regulator. Volume / weight: with the machine off, turn the handwheel (clockwise = less, counter-clockwise = more); run 2–3 cycles, weigh the last deposit, adjust, and note the % setting for next time. Changing the speed can change the volume — re-check the weight after any speed change.", "Run: keep the hopper more than half full — a near-empty hopper sucks air and gives inconsistent deposits; scrape high-viscosity product down the sides periodically. If the product splashes, lower the deposit speed. Temperature limits: product or water through the machine at most 60 °C with the Normal rotation cylinder, at most 110 °C with the Hot cylinder — never exceed them.", "Watch the deposits and the seals: irregular or inconsistent deposits usually mean a worn or damaged seal (an air leak at a piston) or an empty hopper sucking air. If it's the seal, stop and have the seal replaced before running again. If a seal is torn or missing a piece, treat it as possible rubber in the product — hold the product back to the last good check and tell the Supervisor and Quality.", "New batch / changing product: same or compatible product — fill the hopper, discharge 3–4 deposits into a bowl and add them back, then check the weight. Different product — scrape the hopper down and deposit until nothing more comes out, pour in a bucket of warm water, wipe clean, and cycle the water out. A different allergen next means a full changeover clean under SOP-903 and FSQM-027 first.", "Shut down: turn the machine OFF, disconnect the air line and bleed off the pressure, and hand over to sanitation (SOP-903).", "If something goes wrong — Won't cycle: check air pressure/supply and the dryer; check the speed regulator is tight; check for an obstruction in the product cylinder. Cylinder goes forward but not back, or machine-gun strokes: speed regulator loose/broken or air hoses blocked — get Maintenance. Irregular deposits: worn/damaged seal (air leak) → replace it, or hopper near empty → refill/scrape (hold product if a seal is torn — see above). Product dripping from the nozzle: use the suck-back regulator under the base. Any part hot beyond the limits, or air over 7 Bar: stop — you're outside the machine's limits.", "Seals and grease: the seals/O-rings are food-contact rubber and the grease on them touches product, so both are controlled — only Beldos food-approved (food-grade) grease is used, and worn seals are replaced on a set schedule (the manual's weekly O-ring check / O-ring board). This satisfies SQF 11.2.1.7 and 11.7.3.9. The replacement schedule is Maintenance's; sanitation inspects every seal at each clean (SOP-903)."], "attachments": [{"name": "275_manual_ENG_2020(1).pdf", "path": "281fcce4-5b09-435e-b6d2-72ab815863be/files/275_manual_ENG_2020_1_.pdf"}], "responsibility": "Operators — set up, run, and unload as written; stop and report bad deposits or worn seals.\nSupervisor — trains and signs off operators; takes the machine out of service on a fault; signs the pre-use release on FRM-911.\nMaintenance — air system, seal-replacement schedule (the O-ring board), and repair, with the air disconnected.", "form_references": "Batch sheet / settings chart for the product (nozzle, cylinder size, speed, volume %)\nFRM-911 — Depositor Cleaning & Pre-Use Check Log (the clean and its release before a run)\nSOP-903 — Beldos 275 Depositor Sanitation", "revision_history": "New — 2026-07-25 — Initial issue. Written from the Beldos 275 end-user manual (2020); one page for floor use, air-system and seal-replacement-schedule detail left to Maintenance's remit.\n\nv2 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.1.7 (food-grade lubricant on food contact), 11.7.3.1 (equipment free of potential contaminants; parts not deteriorated), 11.7.3.9 (gaskets/rubber that wear inspected on a regular frequency).\nBeldos N.V. — Manual for end user, Depositor 275 series, © 2020.\nOSHA 29 CFR 1910.147 — Control of Hazardous Energy (bleed and disconnect the air before opening)."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '281fcce4-5b09-435e-b6d2-72ab815863be' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"scope": "Production staff cooking, holding, stirring, or transferring product in the kettle.\n\nCleaning is SOP-904. Jacket refilling, water treatment, greasing, pressure-relief-valve service, and electrical/repair work are Maintenance / an authorized service agent — not operators.", "purpose": "To cook, reheat, or hold product in the Groen kettle safely and consistently.\n\nEverything about this machine is hot. The body, the product, the cover and the steam that vents from the pressure-relief valve all burn. It is also a sealed steam jacket — it must never be run dry, and its water level and pressure are checked every day.", "records": "Cooking parameters go on the batch sheet. The clean and the pre-use release are recorded on FRM-912. Daily jacket/pressure checks and the pressure-relief-valve test are noted per the plant maintenance log. Operator training sign-off is held in the training record. All retained per the record retention policy.", "procedure": ["Before you start — training: do not operate this kettle unless the Supervisor has trained and signed you off.", "Daily checks (kettle cold): jacket water level at or just above the midpoint of the sight glass (if low, it goes to Maintenance for refilling — don't run it low); pressure/vacuum gauge reads 20–30 inches of vacuum when cold (if not, there's air in the jacket — Maintenance); never heat an empty kettle (excessive steam pressure can build — put water or product in first); the pressure-relief-valve elbow points down and the floor around the kettle is clean and dry. Anything fails → don't run it; tag it and tell the Supervisor.", "PPE / get ready: protective oven mitt and apron for anything hot; sleeves managed; hair in a hairnet. Keep clear of the hot body, pouring lip, and the relief-valve outlet.", "Start and cook: turn on the power and set the thermostat to the temperature on the batch sheet (the heating light cycles on/off as it holds temperature — normal). Don't overfill — keep product 2–3 inches (5–8 cm) below the rim for stirring, boiling and safe transfer. Stir and scrape with the kettle paddle / non-metal utensils — no metal tools that scratch the stainless. Check the batch sheet's allergens against the last product cooked; if they differ, the kettle needs an allergen changeover clean under SOP-904 and FSQM-027 first. If using the cover, place/remove it only by its plastic handle and lift the rear edge first to vent steam — never tilt the kettle with the cover on (it can slide off).", "Transfer / empty (tilting): wear the oven mitt and apron; put a deep container on a stable flat surface as close as possible; stand to the side, not in the pour path. Grip the insulated tilt handle firmly and keep hold of it the whole time — don't let go while partly tilted (it slams into the upright or fully-tilted stop and can splash hot product). Pour slowly and return the kettle upright once the transfer is complete. Don't overfill the receiving container.", "Shut down: turn the thermostat to OFF and switch off the power. Hand over to sanitation — SOP-904 (clean food-contact surfaces as soon as possible after use, while still warm).", "If something goes wrong — Won't heat, no indicator light: check the power / circuit breaker and the jacket water level; if still dead, Maintenance. Heats slowly or the relief valve pops: air in the jacket — Maintenance removes it; don't keep running it hard. Steam venting from the relief valve: stand clear (burn hazard); if it keeps popping, stop and get Maintenance. Tilt feels stiff or binds: stop — authorized service (trunnion bearing / lubrication); don't force it. Any leak or the water level dropping: stop, tag it, tell Maintenance — never run the jacket dry.", "Maintenance checks — who does what: Operator, daily/periodic — jacket water level (sight-glass midpoint) and vacuum gauge (20–30 inches cold) before each day; test the pressure-relief valve at least twice a month (hold the ring about 5 seconds at operating pressure — if it doesn't discharge or it leaks, stop using the kettle and call service). Maintenance / service — jacket refilling with distilled water and water treatment (pH 10.5–11.5), greasing the trunnion bearings, and all electrical work. Keep water and solutions out of the controls and electrical — never use a high-pressure hose on the kettle."], "responsibility": "Operators — run the daily checks and operate as written; stop and report faults or leaks.\nSupervisor — trains and signs off operators; takes the kettle out of service on a fault.\nMaintenance / service agent — jacket fill and water treatment, greasing, pressure-relief-valve and electrical service, with the power disconnected.", "form_references": "Batch sheet for the product (temperature, time, batch size)\nFRM-912 — Kettle Cleaning & Pre-Use Check Log (the clean and its release before a run)\nSOP-904 — Groen TDB Kettle Sanitation", "revision_history": "New — 2026-07-25 — Initial issue from the Groen/Unified Brands TDB/TDBC operator manual (P/N 148733); one page for floor use, jacket-fill / water-treatment / greasing left to Maintenance. Written for the hand-tilt (TDB) unit.\n\nv2 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the reference to it now names FSQM-027. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.2.1.2 (equipment maintained and checked on a schedule — the daily jacket water-level / vacuum checks and the pressure-relief-valve test). Cooking temperatures and process control for a given product live on the batch sheet / food safety plan, not this equipment SOP.\nUnified Brands / Groen — TDB/TDBC Steam Jacketed Kettle Operator Manual (P/N 148733).\nOSHA 29 CFR 1910.147 — Control of Hazardous Energy (disconnect power before service)."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'cc10d49f-e228-4f35-a267-4e28af7e1836' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"scope": "The rum cake, all flavours, from the receipt of ingredients and packaging to dispatch to the customer's carrier, across the three-day production rotation. Other products made on the site are not covered by this plan.", "purpose": "This is the food safety plan for the rum cake. It states, to the twelve steps of the Codex Alimentarius HACCP guidelines, how Adventure Bakery identifies the hazards in making it, decides which are significant, and controls them, and how that control is monitored, corrected and verified.", "records": "• Attachment A, with its confirmation block dated and signed\n• FRM-507 and FRM-606 CCP monitoring records, with their weekly review signatures\n• FRM-702 holds and FRM-007 corrective actions arising from a CCP deviation\n• Food safety team review records - the revisions of this plan, and the annual review on FRM-001\nSuperseded revisions of this plan are retained by the sop_document_history trigger.", "procedure": ["Scope", "> The plan starts at the receipt of ingredients and packaging and ends when finished product is collected by the customer's carrier. Every input and output in between - raw materials, packaging, service inputs, the two overnight delays, waste and rework - is shown on the flow diagram in Attachment A (SQF 2.4.3.3).", "> COUNTRY OF PRODUCTION AND DESTINATION (SQF 2.4.3.17). The product is made in the United States and is sold today only in the United States. This plan follows the Codex HACCP guidelines. United States law prescribes its own method, the FDA's Preventive Controls for Human Food rule (21 CFR 117, Subpart C). The site is a qualified facility under that rule - a very small business, with less than $1 million a year in sales of human food, averaged over the previous three years (21 CFR 117.3) - so Subpart C does not apply to it and the modified requirements of 21 CFR 117.201 do. This plan, with the current good manufacturing practices of 21 CFR 117 Subpart B that the site's programs carry, is how the site meets both.", "• THE MODIFIED REQUIREMENTS. Senior Site Management submits the qualified facility attestation to the FDA (Form FDA 3942a), attesting that the site has identified the hazards in its food and implements and monitors preventive controls - this plan is the basis for it. It is submitted every two years, with the facility registration renewal between 1 October and 31 December of each even-numbered year, and the yearly sales figures that support the status are kept. Because the attestation is to these food safety practices and not to compliance with state or local law, the consumer notice of 21 CFR 117.201(e) - this facility's own name and address on the label - does not apply. The label names the manufacturer, packer or distributor as 21 CFR 101.5 requires (\"Manufactured by\", \"Manufactured for\" or \"Distributed by\"), which is checked when the label is approved on FRM-601.", "• IF THE STATUS CHANGES. If sales reach $1 million a year, averaged over three years, the site is no longer a qualified facility and must meet Subpart C in full, including a Preventive Controls Qualified Individual. Senior Site Management checks the figure each year at the management review (FRM-001), and this plan is revised before the status is lost.", "• A NEW DESTINATION. Before the first shipment to any other country - the United Kingdom is the one planned - the food safety team identifies that country's food safety requirements, records here how this plan meets them, and revises this plan.", "Product description", "• Product: rum cake, in several flavours, made for Bahamas Rum Cake Factory. A shelf-stable baked product, stored and distributed at ambient temperature.", "• Composition: cake mix (containing wheat flour, sugar and nonfat dry milk), liquid whole eggs, soybean oil, water and flavour emulsion; the molds are sprayed with a pan release of soybean oil and soy lecithin before depositing; after baking, dipped in a syrup of water and sugar, with rum added in the dunk tank. Some flavours also contain pecans, supplied by the customer.", "• Allergens: wheat, milk, egg and soy in every flavour, and pecans in the flavours that contain them, as declared on each flavour's approved label. Walnuts and almonds are also on site, in another customer's products, and the rum cake box states that the facility processes nuts (FSQM-027).", "• Packaging: vacuum-sealed pouch in a baking cup, in an individual product box; boxes packed in coded master cases, palletized and stretch wrapped.", "• Shelf life: 12 months, printed on the pack as a Best By month and year.", "• Water activity and pH: not yet measured.", "> Each flavour's finished product specification is its entry on FRM-704, which this description refers to (SQF 2.4.3.4). The product is called shelf stable because of reduced water activity, but that figure has not been measured, and the syrup added after baking returns water and sugar to the product. Part 7 has therefore been written with growth in the sealed product scored as significant. The water activity of the finished, sealed product is recorded here when it has been measured, and that line of Part 7 is then scored again.", "Intended use", "• Ready to eat; no further cooking by the consumer.", "• General public. The product contains rum. The caution carried from the June 2026 plan stands: not for immunocompromised individuals, infants or pregnant women without a physician's guidance (SQF 2.4.3.5). The food safety team confirms the caution and the groups it names at its first review after HACCP training (Part 9).", "Food safety team", "• SQF Practitioner - leads the team. Brings the production process, the equipment and the CCP monitoring as they are performed on the floor.", "• Senior Site Manager - substitute SQF Practitioner. Brings the product, its formulation, raw materials and packaging, and approves this plan.", "• Engineering knowledge is not held on the team. It is taken from the equipment manufacturers' manuals and their service technicians, and the source is named wherever this plan relies on it (SQF 2.4.3.2).", "• Who holds each position is recorded on FRM-005 and in FSQM-004, not here, so that this plan does not have to be reissued when a person changes.", "• The team meets at least annually for the full review and whenever a change requires one (Part 10). Its decisions are recorded by revising this plan, and the annual review is also recorded on FRM-001.", "> HACCP TRAINING - NOT YET HELD. No member of the team holds a HACCP training certificate. SQF 2.1.1.5 requires the SQF Practitioner to have completed HACCP training, and 2.4.3.2 asks for a team with the competence to develop the plan. The SQF Practitioner and the Senior Site Manager are each to complete a HACCP course by the dates in Part 9; each certificate is filed on FRM-952 and this Part revised to say so. Until then the team meets 2.4.3.2 in its membership but not yet in its training, and this plan is issued as a limited plan on that basis.", "Process flow diagram", "• The flow diagram is Attachment A. It shows every step from receipt to dispatch across the three days, every raw material, packaging item and service input, the two scheduled overnight delays, and every output including waste and the one rework loop.", "• The food safety team confirmed it by walking the floor on all three days of the rotation, so that every step was seen as it is performed, and corrected it on 2026-09-28. The confirmation block on the diagram is dated and signed once, and the signed sheet is attached to this plan (Part 9). That signed block is the confirmation SQF 2.4.3.6 requires. It is not signed daily.", "• The diagram is re-confirmed whenever the process, equipment or rotation changes, and at the annual review of this plan.", "> FSQM-039 Facility Layout and Product Flow shows where equipment stands and where product goes on the floor. It is not this flow diagram and is not offered as one.", "Hazard significance methodology", "• Name every hazard specifically and type it as biological, chemical (allergens included) or physical: Salmonella, not \"pathogens\"; hard or sharp foreign material from a named source, not \"foreign material\".", "• LIKELIHOOD, judged as if the step's own control measure were absent:", "◦ 1 = Unlikely: no record of it for this material or process, in the industry or at the site.", "◦ 2 = Possible: known to occur in the industry for this kind of material or process.", "◦ 3 = Likely: has occurred at this site, or is expected without control.", "• SEVERITY, the worst harm a consumer could reasonably suffer:", "◦ 1 = Low: brief discomfort, no lasting effect.", "◦ 2 = Moderate: illness or injury needing treatment, without lasting harm.", "◦ 3 = High: serious illness or injury, hospitalisation or death.", "• ALWAYS SEVERITY 3: an undeclared allergen; a pathogen such as Salmonella or Listeria monocytogenes; hard or sharp foreign material 7 mm to 25 mm long.", "• SCORE = likelihood × severity. 6 or 9 = SIGNIFICANT. 1 to 4 = not significant, and the analysis records why.", "• EVIDENCE FOR \"UNLIKELY\": a severity 3 hazard scored as unlikely (a score of 3) records the evidence that makes it unlikely. \"Unlikely\" cannot be asserted without it.", "> WHY THE STEP'S OWN CONTROL IS SET ASIDE. A hazard is judged as if the control at that step were not there. Otherwise every hazard the site already controls would score as unlikely and not significant, and the analysis would conclude that nothing needs controlling. A prerequisite program that is documented, implemented and verified - supplier approval, GMP, sanitation, pest control - may be counted when judging likelihood, and the analysis names the program it relies on.", "> Evidence for a likelihood or severity score comes from the FDA's Hazard Analysis and Risk-Based Preventive Controls for Human Food guidance (its appendix of hazards by ingredient and process), product recalls and outbreaks involving similar products, supplier information, and this site's own records of complaints, holds and deviations.", "• Every significant hazard is given a control measure in Part 7 and is taken through the CCP decision in Part 8. Every hazard that is not significant is recorded with the reason and the prerequisite program that keeps it so.", "• Each row of the analysis records the step, the hazard, its type and source, the likelihood, severity and score, whether it is significant, the justification, and the control measure.", "> This method is applied in exactly the same way to every hazard at every step (SQF 2.4.3.8). It is changed only by revising this Part, and a change to it means every hazard in Part 7 is scored again.", "Hazard analysis and control measures", "> This Part applies the method in Part 6 to every step on Attachment A. Each line under a step is one hazard: its type (B biological, C chemical including allergens, P physical), what it is and where it comes from, likelihood × severity = score, whether it is significant, why, and the control measure. Likelihood is judged as if the step's own control were absent (SQF 2.4.3.7 to 2.4.3.9).", "> THE SCORES BELOW WERE ADOPTED BY THE FOOD SAFETY TEAM WHEN THIS PLAN WAS ISSUED. Because no member of the team yet holds HACCP training, the trained team reviews every line again, against the floor, within 30 days of the first certificate (Part 9).", "• STEP 1 - Receive ingredients and packaging.", "◦ B - Salmonella and Shiga toxin-producing E. coli in the cake mix (wheat flour, nonfat dry milk): L2 × S3 = 6, SIGNIFICANT. Flour is milled from raw grain and is not treated to kill pathogens; flour and dry mixes have caused outbreaks and recalls, and milk powder is a known Salmonella vehicle. Control: the bake at step 7.", "◦ B - Salmonella in the liquid whole egg: L2 × S3 = 6, SIGNIFICANT. Liquid egg is normally sold pasteurised, but Salmonella survives a failed pasteurisation and grows if the cold chain fails. Control: supplier approval (SOP-2.3.4, FRM-202), receipt at 41°F or below recorded on FRM-301 (FSQM-035), and the bake at step 7.", "◦ C - An allergen that is not on the finished product's label, arriving in an ingredient: a supplier changes a recipe, or a different brand is bought in place of the usual one. L2 × S3 = 6, SIGNIFICANT. The ingredients are bought from cash-and-carry suppliers, where the brand on the shelf can change. Control: each material's declaration is recorded word for word from its pack on FRM-207, and the brand received is recorded on FRM-301.", "◦ C - Pecans, supplied by the customer for the flavours that contain them: a tree nut present by design and declared on those flavours' labels, so not scored here. The hazard they bring is cross-contact into a product that does not declare them, at steps 2, 4 and 6, controlled by the allergen changeover and segregation of FSQM-027.", "◦ C - Mycotoxins and pesticide residues in the wheat flour and sugar: L1 × S2 = 2, not significant. Regulated at the mill and the refinery; no history at the site. Kept so by supplier approval (SOP-2.3.4).", "◦ P - Hard or sharp foreign material (metal, glass, stone, hard plastic) in an ingredient as received: L2 × S3 = 6, SIGNIFICANT. It is known to occur in bagged dry ingredients, and the site holds no supplier evidence that would make it unlikely. Control: NONE AT THIS SITE TODAY - there is no sieve, magnet or metal detector (FSQM-013). See the findings below.", "◦ C - Food-contact packaging (vacuum pouches, baking cups) that is not suitable for food: L1 × S2 = 2, not significant. Kept so by the packaging specifications on FRM-207; the suppliers' letters of guarantee are still to be obtained.", "• STEP 2 - Store: dry goods at ambient temperature, liquid eggs refrigerated.", "◦ B - Salmonella growing in liquid egg held above 41°F: L2 × S3 = 6, SIGNIFICANT. Control: the walk-in is monitored continuously, with alerts (SOP-401, FRM-401); the bake at step 7.", "◦ C - An allergen that is not on this product's label, from another product's ingredients stored on site: L2 × S3 = 6, SIGNIFICANT. Control: allergen ingredients are kept sealed on their own labelled rack and never above other ingredients (FSQM-035).", "◦ C - Cleaning chemicals contaminating stored ingredients or packaging: L1 × S2 = 2, not significant. Chemicals are kept in the locked locker, away from ingredients and packaging (FSQM-032, FSQM-035).", "◦ B, P - Contamination by pests: L2 × S2 = 4, not significant. Kept so by FSQM-031 and by sealed containers.", "• STEP 3 - Weigh and measure ingredients, including water.", "◦ B - Pathogens from hands, utensils or the bench into the ingredients: L2 × S3 = 6, SIGNIFICANT. Control: the bake at step 7; handwashing and illness rules (FSQM-012); the pre-operation check (FRM-903).", "◦ B, C - Contaminated water used as an ingredient: L1 × S3 = 3, not significant. Evidence: the City of Sanford's treated supply and its annual water quality report (FRM-915), and the water is then baked. FSQM-033 is still a draft and the site's own yearly test has not yet been done.", "◦ P - Pieces of ingredient packaging (paper, film, thread) falling in when a bag is opened: L2 × S2 = 4, not significant. Soft, not hard or sharp. Kept so by GMP (FSQM-012).", "• STEP 4 - Mix batter.", "◦ P - Metal from the mixer bowl, the agitator or a loose part: L2 × S3 = 6, SIGNIFICANT. Control: the mixer is checked clean, complete and with nothing left on it before use (FRM-909) and is on the monthly maintenance check (FSQM-029, FRM-508). There is no detection step after it - see the findings below.", "◦ C - An allergen that is not on this product's label, left on the mixer by a different product: L2 × S3 = 6, SIGNIFICANT. Control: the allergen changeover clean and inspection (SOP-901), recorded on FRM-909.", "◦ C - Detergent, sanitizer or lubricant left on the mixer: L1 × S2 = 2, not significant. The sanitizer is made up to its no-rinse food-contact strength and read with a test strip (SOP-901, FSQM-032).", "◦ B - Staphylococcus aureus growing and forming toxin in batter left standing: L1 × S2 = 2, not significant. All batter is deposited and baked on the day it is mixed.", "• STEP 5 - Spray molds with pan release.", "◦ C - Soy, from the soy lecithin in the pan spray: present by design and declared on the label, so it is not scored here. A change of pan spray is the ingredient hazard at step 1.", "◦ P - Fragments from a chipped, cracked or flaking mold: L1 × S3 = 3, not significant. Evidence: every mold is checked before each use and inspected at each wash, and a damaged mold is taken out of service (SOP-906, FRM-903).", "• STEP 6 - Deposit batter into the sprayed molds.", "◦ P - Metal, hard plastic, a seal or an O-ring from the depositor: L2 × S3 = 6, SIGNIFICANT. Control: the depositor is checked at reassembly and before use (FRM-910, FRM-911) and is on the monthly maintenance check (FSQM-029). There is no detection step after it - see the findings below.", "◦ C - An allergen left on the depositor by a different product: as for the mixer at step 4, SIGNIFICANT. Control: the allergen changeover clean (SOP-902, SOP-903), recorded on FRM-910 or FRM-911.", "• STEP 7 - Bake.", "◦ B - Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder surviving the bake: L3 × S3 = 9, SIGNIFICANT. They are expected in raw batter and this is the only step that kills them. Control: oven at 350°F or above for at least 27 minutes, recorded for every load on FRM-507. These limits are carried from the June 2026 plan and have not been validated for this product in this oven, and the product's internal temperature is not measured - see the findings below.", "◦ B - Spores of Bacillus cereus and Clostridium species from the flour, sugar and milk powder surviving the bake: L3 × S2 = 6, SIGNIFICANT. Baking does not kill spores; they are a hazard only if they can grow afterwards. Control: none at this step. Growth is prevented by the water activity of the finished product, which has not been measured - see step 13.", "◦ C - Acrylamide formed in baking: L2 × S1 = 2, not significant. A long-term dietary concern, not an acute one, at a normal bake colour.", "• STEP 8 - Remove from the oven and cool in the pans, covered, at room temperature.", "◦ B - Salmonella or Listeria monocytogenes reaching the baked product from racks, covers, hands or the room: L2 × S3 = 6, SIGNIFICANT. The product is ready to eat from here on, and nothing later kills what lands on it. Control: sanitation and the pre-operation release (FRM-903, FRM-902), GMP (FSQM-012) and the hygiene zoning of the cooling area (FSQM-039). Environmental monitoring (FSQM-015) verifies it; its first round is due by 2027-01-31.", "◦ B - Spores that survived the bake growing while the product cools: L2 × S2 = 4, not significant, PROVISIONAL. The cooling time is not limited - depanning may follow later the same day or the next day - and whether spores can grow in the baked product depends on its water activity, which has not been measured.", "• STEP 9 - Depan.", "◦ B - Staphylococcus aureus, norovirus or Salmonella from hands onto ready-to-eat product: L2 × S3 = 6, SIGNIFICANT. Control: handwashing, gloves and the illness and wound rules (FSQM-012), checked on the GMP inspection (FRM-913).", "• STEP 10 - Prepare dipping syrup, only when none is in stock.", "◦ B - Pathogens in the sugar, water or rum: L1 × S3 = 3, not significant. Evidence: refined sugar and treated city water are not known vehicles for Salmonella, and they are heated in the kettle. The rum, a distilled spirit, is added in the dunk tank and is not in the syrup. The temperature reached is not recorded.", "◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water; the rum is added in the dunk tank and is not in syrup kept for a later run (corrected 2026-10-14 - this score was first written for a syrup with alcohol in it, and is for the food safety team to confirm). A concentrated sugar syrup, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured. Kept so by the hold rule below.", "◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded. Each batch made is recorded on FRM-530, with the supplier lots of the sugar used.", "◦ P - Fragments from the kettle or utensils: L1 × S3 = 3, not significant. Evidence: the kettle is cleaned and checked before use (SOP-904, FRM-912).", "• STEP 11 - Dip the baked product in syrup at room temperature. The rum is added to the syrup in the dunk tank. The lots of the syrup and the rum are written on the lot record (FRM-520).", "◦ B - Pathogens carried onto ready-to-eat product by the syrup, the dip container, utensils or hands: L2 × S3 = 6, SIGNIFICANT. This is a wet step after the only kill step. Control: the changeover clean of the dunk bay before Day 2 and its pre-operation release (FRM-903); GMP (FSQM-012); the syrup hold rule at step 10.", "◦ B - The syrup adds water back to the baked product. Its effect on growth in the finished product is scored at step 13.", "• STEP 12 - Place in baking cups.", "◦ B - Hand contact with ready-to-eat product: as step 9, SIGNIFICANT, with the same control.", "• STEP 13 - Vacuum seal.", "◦ B - Clostridium botulinum or Staphylococcus aureus growing in the sealed product during up to twelve months at room temperature: L2 × S3 = 6, SIGNIFICANT UNTIL THE WATER ACTIVITY IS MEASURED. A vacuum pouch removes air, which favours C. botulinum, and the product is kept unrefrigerated. Below a water activity of 0.85 no food-poisoning bacteria grow, and the product is believed to be below it; but Part 6 does not allow a severity 3 hazard to be called unlikely without evidence, and there is none. Control: the product's formulation - its sugar and rum - which becomes a stated control with a limit once the water activity of the finished, sealed product has been measured.", "◦ B - Contamination or mold growth through a leaking, channelled or partial seal: L2 × S2 = 4, not significant by this method. Every pouch is looked at as it comes off the sealer, for a leak, channel, wrinkle or partial seal and for air in the pouch, and is looked at again at boxing. Recorded on FRM-606.", "◦ REWORK - a pouch that fails is opened and the product re-pouched. The hand-contact hazard of step 9 applies, with the same control.", "• STEPS 14 TO 17 - Box; label, lot code and best-by date; pack and code master cases; palletize and stretch wrap.", "◦ C - The wrong label or box, or a label that does not declare wheat, milk, egg and soy, and pecans where the flavour contains them: L2 × S3 = 6, SIGNIFICANT. Control: labels are approved on FRM-601 (SOP-2.3.2.3), and the label applied is checked against the approved label at release on FRM-701 (FSQM-020).", "◦ CCP 2 CHECK AT BOXING - before a pouch goes in its box it is looked at again, and a pouch that has lost its vacuum is rejected. One cooled pouch from each lot is pull tested before boxing starts. The pull test is not done at sealing: the film is still warm then, and a good seal can be pulled open. Recorded on FRM-606.", "◦ C - Coder ink: L1 × S1 = 1, not significant. It is applied to the outside of the box and the case only, never to a food-contact surface.", "• STEP 18 - Release check.", "◦ No hazard is introduced. The check on FRM-701 is itself a control: no batch leaves under an open hold, without its pre-operation release recorded, or with a label that is not the approved one (FSQM-020).", "• STEPS 19 AND 20 - Warehouse storage at ambient temperature, and dispatch.", "◦ B - Growth in the sealed product over its shelf life: scored at step 13.", "◦ B, P - Pests or handling damaging packs: L1 × S2 = 2, not significant. Kept so by FSQM-031, FSQM-035 and the loading check on FRM-801 (FSQM-036).", "• AT EVERY STEP.", "◦ P - Glass or brittle plastic from lights, gauges or fittings: L1 × S3 = 3, not significant. Evidence: every item is on the register and checked (SOP-11.7.3, FRM-907), and a breakage is handled on FRM-908.", "◦ P - Jewellery, pens, dressings and other personal items: L1 × S2 = 2, not significant. Kept so by FSQM-012.", "◦ C - Sanitizer or detergent on a food-contact surface at the wrong strength: L2 × S2 = 4, not significant. The strength is read with a test strip and recorded (FRM-903, FSQM-032).", "◦ Compressed air, ice and steam do not contact the product (FSQM-013), so no hazard arises from them.", "> WHAT THIS ANALYSIS FINDS. Four of the significant hazards above do not yet have a control that is in place and proven. This plan is issued with each of them stated as a limitation, with the action and date that closes it, in Part 9.", "• WATER ACTIVITY. Whether pathogens can grow in the finished product is not known, because its water activity has never been measured. The measurement that decides it is of the product as sold - after the dip, sealed, and left a day or more to settle - and not of the cake before it is dipped: the syrup puts water back, and the sealed pack is what sits at room temperature for a year. Water activity is not wetness; sugar and alcohol hold water so that microbes cannot use it, which is why a syrup-soaked cake can still measure low.", "• FOREIGN MATERIAL. Hard or sharp foreign material is a significant hazard at steps 1, 4 and 6, and nothing in the process would find it. The metal detector named in FSQM-013 Part 5 is the planned control; until it is installed and its limits are set, the pre-use equipment checks are the only measure.", "• THE BAKE. The limits of 350°F and 27 minutes have not been validated against this product in this oven, and the internal temperature is not measured. Validation is workbook tasks 14.7 to 14.9.", "• AFTER THE BAKE. Recontamination of ready-to-eat product at steps 8 to 12 is controlled by cleaning and hygiene alone. Environmental monitoring (FSQM-015) is what shows that this control works; it is issued, and its first round is due by 2027-01-31.", "> Part 8 takes each significant hazard through the CCP decision. Two results of this analysis bear on it. The failed-seal hazard at step 13 scores as not significant, so the team must decide whether vacuum sealing remains a critical control point. And if water activity proves to be the control for growth, its limit belongs in Part 8.", "Critical control points", "> Every significant hazard in Part 7 is taken through the four questions of the Codex decision tree, in the same way each time (SQF 2.4.3.10). The decisions below were adopted by the food safety team when this plan was issued, and are reviewed again by the trained team, as Part 7 is.", "• THE FOUR QUESTIONS, asked of each significant hazard at the step where it arises:", "◦ Question 1 - Do the prerequisite programs control it at this step? If yes, it is not a CCP. A program counts only when it is issued, in use and verified (Part 6).", "◦ Question 2 - Is there a control measure for it at this step? If there is none and control is needed for safety, the step, the process or the product has to change.", "◦ Question 3 - Will a later step remove it or bring it down to a safe level? If yes, that later step is where it is controlled.", "◦ Question 4 - Does this step remove it or bring it down to a safe level? If yes, this step is a CCP.", "• THE DECISIONS:", "◦ Pathogens in the cake mix and the liquid egg, their growth in egg held too warm, and pathogens from hands into the ingredients (steps 1, 2 and 3): Question 1 no - supplier approval, cold storage and GMP lower them but do not remove them. Question 3 yes - the bake. NOT A CCP at these steps; controlled at CCP 1.", "◦ Pathogens surviving the bake (step 7): Question 1 no. Question 2 yes. Question 3 no - nothing after the oven kills. Question 4 yes. CCP 1.", "◦ Spores surviving the bake (step 7), and Clostridium botulinum or Staphylococcus aureus growing in the sealed product (step 13): baking does not kill spores, so the only control is that the finished product cannot support growth. Question 2 cannot be answered until the water activity of the finished, sealed product is measured. NOT YET DECIDED. If it is 0.85 or below, the recipe and the dip that give that figure become a control with a limit, written here. If it is above, the product or the process has to change.", "◦ An undeclared allergen arriving in an ingredient, or from another product's ingredients in storage (steps 1 and 2): Question 1 yes - the material declarations on FRM-207, the brand check at receipt on FRM-301 and segregated storage (FSQM-027, FSQM-035). NOT A CCP.", "◦ An allergen left on the mixer or a depositor by a different product (steps 4 and 6): Question 1 yes - the changeover clean, checked and swabbed (FSQM-027, SOP-901 to SOP-903, FRM-916). NOT A CCP.", "◦ Hard or sharp foreign material in an ingredient, or metal from the mixer or a depositor (steps 1, 4 and 6): Question 1 no - the checks before use lower it but would not find it. Question 2 no - there is no control measure. THE PROCESS HAS TO CHANGE. Management's decision, 2026-10-07: a metal detector, not yet bought. When it is installed it becomes a CCP, with its limits and test pieces set when it is commissioned. A metal detector finds metal only: the team decides, with evidence from the suppliers, whether stone, glass and hard plastic in the dry ingredients are unlikely, or whether those ingredients are also sieved.", "◦ Recontamination of the baked product from surfaces, the room, the syrup or hands (steps 8, 9, 11 and 12): Question 1 yes - cleaning and the pre-operation release (FRM-903), GMP (FSQM-012) and the zoning (FSQM-039), with environmental monitoring (FSQM-015) to show they work. NOT A CCP: there is no later kill step, and nothing at these steps can be measured against a limit for each batch.", "◦ The wrong label, or a label that does not declare the allergens (steps 14 to 17): Question 1 yes - label approval on FRM-601 and the label check at release on FRM-701 (FSQM-020). NOT A CCP.", "• THE CRITICAL CONTROL POINTS:", "◦ CCP 1 - Baking (step 7): oven at least 350°F for at least 27 minutes, recorded on FRM-507 CCP 1 Baking Monitoring Record. The June 2026 plan also sets an internal temperature of at least 180°F at the end of the bake; the product is not probed today, and FRM-507 records that.", "◦ CCP 2 - Vacuum sealing (step 13): every pouch sealed intact with no leak, channel, wrinkle or partial seal and no air in the pouch. Every pouch is looked at as it comes off the sealer and again at boxing, where one cooled pouch from each lot is pull tested. Recorded on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The vacuum level and seal width for the site's machine are not yet confirmed.", "• CCP 2 IS KEPT, ALTHOUGH THE METHOD DOES NOT REQUIRE IT. A failed seal scores as not significant in Part 7, so the questions above would not make sealing a CCP. Management's decision, 2026-10-07: it stays a CCP, monitored and recorded as now, until the water activity is known and the team has HACCP training. It is decided again then.", "• CCP 1 is checked and recorded for every oven load. For CCP 2 every pouch is looked at, and a row is recorded at the first sealing, after any adjustment, at the end of the run and at boxing (SQF 2.4.3.12).", "• A failed limit stops the step. The affected product is held on FRM-702 and dispositioned under FSQM-018, and the cause is corrected under FSQM-009 on FRM-007 (SQF 2.4.3.13).", "• NOT YET IN PLACE. This plan is issued with the following open, each stated as a limitation in Part 9 with the action and date that closes it:", "◦ The critical limits of CCP 1 are not validated for this product in this oven (SQF 2.4.3.11).", "◦ The water activity is not measured, so growth in the sealed product has no decided control.", "◦ There is no metal detector.", "◦ FSQM-027 and FSQM-015 are issued, but the allergen validation swabs and the first environmental round are not yet done. The decisions above that rest on them hold once each is in use.", "◦ No member of the team holds HACCP training (Part 4), so these decisions have not yet been made by a trained team.", "Stated limitations at issue", "> THIS PLAN IS ISSUED AS A LIMITED PLAN. On 2026-10-29 management decided to issue it rather than wait, so that the rum cake is made under a controlled food safety plan that says plainly what is not yet proven, in place of the June 2026 plan, which did not. Each limitation below names the action that closes it, who owns it and the date it is due. When one closes, this Part and the Part it affects are revised, and the limitation is removed.", "• HACCP TRAINING (Part 4; SQF 2.1.1.5, 2.4.3.2). No member of the team holds a certificate. Action: the SQF Practitioner completes a HACCP course by 2027-01-31, the Senior Site Manager by 2027-03-31, each certificate filed on FRM-952. Owner: Senior Site Management.", "• TEAM REVIEW BY A TRAINED TEAM (Parts 7 and 8). The hazard analysis and the CCP decisions were adopted by a team not yet trained. Action: within 30 days of the first HACCP certificate, the team reviews every line of Parts 7 and 8 against the floor, confirms the intended-use caution in Part 3, and revises this plan. Owner: SQF Practitioner.", "• WATER ACTIVITY AND pH (Parts 2, 7 and 8; SQF 2.4.3.4). Not measured, so growth in the sealed product (step 13) has no decided control and CCP 2 is kept by management's decision. Action: finished, sealed product - after the dip, left a day or more to settle - sent to a laboratory for water activity and pH by 2026-11-30; the result recorded in Part 2, step 13 scored again, and the decision in Part 8 made. Owner: SQF Practitioner.", "• VALIDATION OF THE BAKE (Part 8, CCP 1; SQF 2.4.3.11, 2.5.1.1). The limits of 350°F for 27 minutes are carried from the June 2026 plan and the internal temperature of the product is not measured. Action: the bake validated for this product in this oven, including probing the internal temperature at the end of the bake, by 2027-02-28. Until then CCP 1 is monitored against the limits as stated. Owner: SQF Practitioner.", "• CCP 2 SPECIFICATION (Part 8; SQF 2.4.3.11). The vacuum level and seal width for the site's sealer are not confirmed. Action: obtained from the manufacturer and written into Part 8 and FRM-606 by 2026-12-31. Owner: SQF Practitioner.", "• FOREIGN MATERIAL (Parts 7 and 8). Hard or sharp foreign material has no control that would find it. Action: management's decision of 2026-10-07 is a metal detector; it is bought and installed by 2027-03-31, and on commissioning becomes a CCP with its limits and test pieces written into Part 8. The team decides, with supplier evidence, whether stone, glass and hard plastic in the dry ingredients are unlikely or the ingredients are also sieved. Until then the checks before use (FRM-909, FRM-910, FRM-911) are the only measure. Owner: Senior Site Management.", "• PROGRAMS THIS PLAN RELIES ON THAT ARE NOT YET FULLY IN USE (Part 8). Allergen management (FSQM-027) was issued on 2026-10-29; its test kit is chosen by 2026-11-30 and its validation swabs done by 2027-01-31. Environmental monitoring (FSQM-015) was issued on 2026-10-29; its laboratory is chosen by 2026-11-30 and its first round taken by 2027-01-31. The decisions that rest on them hold once each is in use; each document carries its own open items. Owner: SQF Practitioner.", "• THE SIGNED FLOW DIAGRAM CONFIRMATION (Part 5; SQF 2.4.3.6). The confirmation sheet signed on the floor is attached to this plan by 2026-11-30. Owner: SQF Practitioner.", "• 21 CFR 117 ATTESTATION (Part 1). The qualified facility attestation, to the site's food safety practices, is confirmed as submitted with the 2026 facility registration renewal by 2026-12-31. Owner: Senior Site Management.", "> These limitations are reviewed at each monthly SQF update (FRM-009) until all are closed.", "Verification and review", "• The CCP records are reviewed and signed weekly under FSQM-017 (SQF 2.4.3.15 and 2.4.3.16).", "• The food safety team reviews this plan in full at least annually, and whenever the product, ingredients, process, equipment or packaging changes in a way that could affect food safety (SQF 2.4.3.14 and 2.3.1.3)."], "attachments": [{"name": "FSQM-016 Att A - HACCP Process Flow Diagram - Rum Cake.pdf", "path": "f0ad5f61-a2b2-4e07-a363-9da74f96133f/files/FSQM-016_Att_A_-_HACCP_Process_Flow_Diagram_-_Rum_Cake.pdf"}, {"name": "FSQM-016 Att A - HACCP Process Flow Diagram - Rum Cake.drawio", "path": "f0ad5f61-a2b2-4e07-a363-9da74f96133f/files/FSQM-016_Att_A_-_HACCP_Process_Flow_Diagram_-_Rum_Cake.drawio"}], "definitions": "Critical control point (CCP): a step at which control is applied and is essential to prevent or eliminate a food safety hazard or reduce it to an acceptable level.\nCritical limit: the value that separates safe from unsafe product at a CCP.\nFood safety team: the people named in Part 4 who develop, maintain and review this plan.\nAttachment A: the process flow diagram, held with this plan as an editable master and a PDF.", "responsibility": "SQF Practitioner - leads the food safety team, maintains this plan, and reviews the CCP records.\nFood safety team - develops and reviews this plan, confirms the flow diagram on the floor, and conducts the hazard analysis.\nManagement team - approves this plan and provides what it requires.\nProduction staff - monitor the CCPs and record them on FRM-507 and FRM-606, and stop and hold product when a limit is not met.", "form_references": "FRM-507 - CCP 1 Baking Monitoring Record\nFRM-606 - CCP 2 Vacuum Sealing Monitoring Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective and Preventive Action record (FSQM-009)\nFRM-704 - Finished Product Specification\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-701 - Finished Product Release Record", "revision_history": "New - 2026-09-21 - DRAFT, under D-14. Created so the rebuilt plan has a controlled home while it is written, and so the flow diagram (task 14.2) can be attached to it as Attachment A.\n\nWHAT IS WRITTEN: scope, product description, intended use, the flow diagram Part, the CCPs as they are monitored today, and verification.\n\nWHAT IS NOT: Parts 4, 6 and 7 are marked NOT YET WRITTEN and name the workbook task that writes each. A plan that read as complete before its hazard analysis existed would be the defect the gap assessment found, repeated.\n\nThe number FSQM-016 was reserved for this plan in the remediation workbook on 2026-09-04, after FSQM-013 went to the Module 11 exemption analysis.\n\nNew (draft) - 2026-09-21 - Part 4 written (workbook task 14.1). The team is two positions, SQF Practitioner and Senior Site Manager, with engineering advice taken from equipment manufacturers. Positions are named, not people. Neither member holds a HACCP certificate yet, and Part 4 says so rather than implying a qualified team.\n\nNew (draft) - 2026-09-21 - Part 6 written (workbook task 14.4): a three-by-three likelihood and severity method, significant at a score of 6 or more, with fixed severity-3 hazards, evidence required for any severity-3 hazard called unlikely, and the step's own control set aside when judging likelihood. It is written before the hazard analysis because the gap assessment's finding against 2.4.3.8 was inconsistency, not absence.\n\nNew (draft) - 2026-09-21 - Part 6 re-laid out, wording unchanged in substance: each scale on one line with its levels numbered inline, and the fixed severity-3 hazards, the score rule and the evidence rule each on their own line. The body renders one list level only, so the scale levels had appeared as bullets alongside the rules they belong to.\n\nNew (draft) - 2026-09-21 - Part 6's likelihood and severity levels each on their own indented line, using the new sub-item line form (a line opening with the white bullet sits one level in under the bullet above it). Wording unchanged.\n\nNew (draft) - 2026-09-28 - ATTACHMENT A CORRECTED IN FIVE PLACES, found while the owner and the Senior Site Manager read the flow against the process.\n\n1. THE PAN RELEASE IS ITS OWN STEP. The molds are sprayed with Chef's Quality Pan Spray (soybean oil and soy lecithin) before the batter is deposited; the drawing had shown it only as an unnamed input to depositing. It is now step 5, 'Spray molds with pan release - done before, after or alongside mixing', which is how it is performed, and step 6 deposits into sprayed molds. The composition above names it.\n\n2. COOLING COMES BEFORE DEPANNING. The drawing had the product depanned as it left the oven. In fact the pans go straight onto the cooling racks and the product is turned out once it is cool. Day 1 now ends at 'Remove from oven, place the pans on the cooling racks', and Day 2 opens with step 9, 'Depan - turn the cooled product out of the pans'.\n\n3. THE COOL IS NOT NECESSARILY OVERNIGHT. Gabriela, 2026-09-28: what is required is cooling before depanning, and some batches are depanned later on Day 1 and some on Day 2. The delay now reads 'cool in the pans, covered, at room temperature on the racks, until cool enough to depan', with a note that depanning follows later on Day 1 or on Day 2. Writing it as a fixed overnight delay would have stated a control the site does not work to.\n\n4. MAKING THE SYRUP IS A CONDITIONAL STEP. Syrup is not made every run: step 10 runs only when no prepared syrup is in stock. Syrup kept for a later run is held ambient in a sealed container, and the dip step takes prepared syrup from stock as an input.\n\n5. THE SYRUP IS DIPPED AT ROOM TEMPERATURE. Syrup made on the day is cooled to room temperature before use, which the drawing carries as a delay off step 10; syrup taken from stock is already at room temperature. Step 11 reads 'Dip baked product in syrup at room temperature'. This matters to the hazard analysis in both directions: hot syrup on baked product is a different step from what the site performs, and a syrup cooling on the bench is itself a delay to be assessed.\n\nOPEN, AND ON THE DRAWING AS A GAP: stored syrup has NO HOLD LIMIT and NO LABEL today. How long it may be held, and what the container says, are decided in the hazard analysis (Part 7). A held food component with neither a limit nor a date is both a food safety question and a traceability one - a dipped batch cannot be tied to the syrup it was dipped in.\n\nThe diagram is now 20 steps. CCP 1 baking stays step 7; CCP 2 vacuum sealing moves from step 11 to step 13, and the scope box's rework sentence moved with it.\n\nALLERGEN: the spray's label declares CONTAINS: SOY, from the soy lecithin. Soy was already declared as an allergen of this product, and the owner confirmed on 2026-09-28 that the finished product label declares it, so nothing about the declaration changes. The pan spray and the bulk soybean oil are separate FRM-207 entries and are separate materials.\n\nTHIS IS WHAT CONFIRMING A FLOW DIAGRAM IS FOR (SQF 2.4.3.6): two things the drawing showed differently from how the floor works. The confirmation block on Attachment A is signed against this version, not the one before it.\n\nNew (draft) - 2026-10-01 - PART 7 WRITTEN (workbook tasks 14.5 and 14.6): the hazard analysis, step by step against the confirmed 20-step flow diagram, scored by the method in Part 6. With it every Part of this plan has text; none is marked NOT YET WRITTEN.\n\nIT IS A DRAFT FOR THE FOOD SAFETY TEAM, NOT THE TEAM'S ANALYSIS. The hazards, scores and controls were drafted from the flow diagram, the site's issued programs and what the site has said about its process. The team checks each line against the floor and adopts or changes it. No member of the team yet holds HACCP training (Part 4).\n\nWRITTEN BEFORE THE WATER ACTIVITY IS KNOWN. The product description had said the water activity was to be recorded before Part 7 was written. It has not been measured, so growth in the sealed product is scored as significant, as Part 6 requires of a severity 3 hazard with no evidence. The measurement needed is of the finished, sealed product - not of the cake before it is dipped.\n\nSYRUP (site, 2026-10-01): made two parts sugar to one part water, with rum added after heating; normally used within a few days; a hold limit of 30 days is set, sealed at room temperature; the container carries the date made and a lot code in the product's form. This closes the gap carried on the drawing since 2026-09-28. A supplier's specification for an invert syrup, giving six months in its original sealed packaging, was offered as the basis for a longer hold and was not used: it describes a different product in a different pack.\n\nWHAT THE ANALYSIS FOUND: four significant hazards without a control that is in place and proven - growth in the sealed product (water activity unmeasured), hard or sharp foreign material (no detection; a metal detector is planned), the bake (limits not validated, internal temperature not measured), and recontamination after the bake (environmental monitoring not in force). It also scores a failed seal as not significant, which puts CCP 2 in question for Part 8.\n\nOPEN BEFORE ISSUE: (1) the water activity, and pH, of the finished sealed product; (2) the team's review of every line; (3) which allergens other than wheat, milk, egg and soy are on the site; (4) that the liquid egg is pasteurised, from its pack - FRM-207 holds four materials so far; (5) whether a delivery of a brand that is not the one on FRM-207 is held until it has been checked - nothing requires it today; (6) the syrup: how much rum goes in, whether syrup already used for dipping may be kept, and writing the syrup's lot code on the lot record (FRM-520) of each batch dipped in it; the 30 days is the site's limit, not a measured one; (7) the metal detector; (8) validation of the bake; (9) FSQM-015; (10) the CCP decision in Part 8.\n\nNew (draft) - 2026-10-07 - PART 8 WRITTEN AS A DRAFT (workbook task 14.7): each significant hazard taken through the four questions of the Codex decision tree. CCP 1 baking stands. By the method sealing would not be a CCP; management keeps it as CCP 2 until the water activity is known and the team is trained. Foreign material has no control, so the process has to change: management's decision is a metal detector, not yet bought, which becomes a CCP when it is installed. Growth in the sealed product is not decided until the water activity is measured. Allergens, recontamination after the bake and labelling are controlled by programs and are not CCPs; two of those programs, FSQM-027 and FSQM-015, are still drafts. No member of the team holds HACCP training, so this is a draft for a trained team to confirm.\n\nNew (draft) - 2026-10-07 - CCP 2 wording corrected to what is done (site, 2026-10-07): every pouch is looked at as it comes off the sealer and again at boxing; the pull test is on one cooled pouch per lot at boxing, never on a warm seal; the gauge is read at set-up. The earlier text said every pouch was pull tested.\n\nNew - 2026-10-29 - ISSUED AS A LIMITED PLAN under D-14. Approved GJM, effective 2026-10-29. Replaces the HACCP plan of 23 June 2026, which is archived.\n\nWHY ISSUE NOW. Management decided (owner, 2026-10-29) to issue the plan rather than wait for every open item, because the June plan it replaces overstated what was proven, and this one states it. The open items are not hidden: they are a Part of the plan, Part 9 'Stated limitations at issue', each with its action, owner and date.\n\nWHAT CHANGED FROM THE DRAFT: Parts 7 and 8 no longer say they are a draft for the team - the team adopted them at issue, and they are reviewed again by the trained team within 30 days of the first HACCP certificate. The 'cannot be issued until' wording in Parts 7 and 8 now points to Part 9. The intended-use caution from the June plan is stated as standing. The flow diagram confirmation is described as done, with the signed sheet to attach. Part 9 is new; verification and review is now Part 10.\n\nOPEN AT ISSUE (Part 9): HACCP training for both team members; the trained team's review of Parts 7 and 8; water activity and pH of the finished, sealed product; validation of the bake and the internal temperature; the CCP 2 vacuum level and seal width; the metal detector; FSQM-027 and FSQM-015 still drafts; the signed flow diagram confirmation sheet; the 21 CFR 117 decision.\n\nSETTLED SINCE THE DRAFT'S OPEN LIST OF 2026-10-01: the brand-substitution hold (SOP-2.3.4 v4); the syrup - made on site on FRM-530 with a 30-day use-by, the rum added in the dunk tank and not kept in the syrup, and the syrup and rum lots written on the lot record FRM-520 (FSQM-021 v3).\n\nv2 - 2026-10-29 - SQF 2.4.3.17 ADDRESSED: the country of production and destination. Owner, 2026-10-29: the product is sold only in the United States today, the United Kingdom is planned, and yearly food sales are under $1 million. So the site is a qualified facility under the FDA Preventive Controls rule and follows its modified requirements (21 CFR 117.201): the biennial attestation, with this plan as its basis, and the facility's name and address on the label. Part 1 now says so, with what happens if the status is lost and before a first shipment to a new country. The Part 9 limitation 'decide 21 CFR 117 by 2027-03-31' is replaced by two checks due 2026-12-31: the label carries the facility's name and address, and the 2026 attestation was submitted with the registration renewal. 2.4.3.17 added to the clause references.\n\nv3 - 2026-10-29 - Label requirement corrected (Senior Site Manager, 2026-10-29). v2 said the label must show this facility's name and address under 21 CFR 117.201(e). That notice is required only of a qualified facility that attests to compliance with state or local law; this site attests to its food safety practices, so it does not apply. The label names the manufacturer, packer or distributor under 21 CFR 101.5 ('Manufactured by', 'Manufactured for' or 'Distributed by'). The Part 9 label check is removed; the attestation check stays, due 2026-12-31.\n\nv4 - 2026-10-29 - FSQM-015 Environmental Monitoring issued. The four lines that called it a draft now say it is issued, with its laboratory due by 2026-11-30 and its first round by 2027-01-31. FSQM-027 is still a draft.\n\nv5 - 2026-10-29 - FSQM-027 Allergen Management issued. The two lines that called it a draft now say it is issued, with its test kit due by 2026-11-30 and its validation swabs by 2027-01-31.\n\nv6 - 2026-10-29 - Pecans added. Part 2 named only wheat, milk, egg and soy; some rum cake flavours contain pecans (FSQM-027), so Part 2's composition and allergens, step 1 and the label hazard at steps 14 to 17 now name them, and the walnuts and almonds on site for another customer are noted. Step 10's hazard line no longer says the rum is added in the kettle: it is added in the dunk tank (corrected elsewhere on 2026-10-14). Found in the readiness review of 2026-10-29. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.4.3 Food Safety Plan, and 2.3.1.3. Codex Alimentarius, General Principles of Food Hygiene (CXC 1-1969), HACCP system and guidelines for its application.\n\nTHIS PLAN REPLACES THE HACCP PLAN OF 23 JUNE 2026, version 1.0, which was held as an unnumbered reference document with an unsigned approval page. It was archived, not deleted, when this plan was issued on 2026-10-29.\n\nFSQM-017 Validation and Verification Program - the verification schedule the CCP record reviews sit on.\nFSQM-039 Facility Layout and Product Flow - the floor layout and hygiene zoning; not the flow diagram.\nFSQM-015 Environmental Monitoring Program - depends on the water activity this plan records.\nFSQM-018 Non-Conforming Product and Equipment, and FSQM-009 Corrective and Preventive Action Program - deviation handling.\n\nThe product is subject to 21 CFR 117 (Preventive Controls for Human Food). The site is a qualified facility under it (21 CFR 117.3 and 117.201); how this plan meets it is in Part 1."}$jx$::jsonb,
       revision = 'v6', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'f0ad5f61-a2b2-4e07-a363-9da74f96133f' and status = 'active' and revision = 'v5';
update public.sop_documents set content = $jx${"scope": "Covers both reviews, for the whole SQF System and every site activity within its scope.\n\nThe annual management review is recorded on FRM-001 Management Review Record. The monthly update is recorded on FRM-009 Monthly SQF Update.\n\nThis programme does not itself set the site's food safety objectives; it reviews performance against whatever objectives senior site management has set.", "purpose": "To define how the SQF System is reviewed by senior site management, so that its continued suitability and effectiveness are established and recorded: the annual management review required by SQF 2.1.2.1, and the monthly update to senior site management required by SQF 2.1.2.2.", "records": "Completed FRM-001 entries, one per annual management review, retained per the record retention policy.\nCompleted FRM-009 entries, one per month, carrying the update, management's response and any actions arising.\nActions arising from either, tracked to closure.", "procedure": ["PART 1 - TWO OBLIGATIONS, KEPT SEPARATE", "• **2.1.2.1 requires an annual review** of the whole SQF System by senior site management, against six named agenda items, with the records maintained.", "• **2.1.2.2 requires a monthly update** from the SQF Practitioner to senior site management on matters affecting the SQF System, with the update and management's response documented.", "> These are kept as two things rather than collapsed into one. Collapsing them was considered and rejected: it would require every monthly meeting to cover all six agenda items in full and to be recorded as a management review - twelve complete records a year, where a quiet month becomes a gap in the evidence rather than simply a quiet month. The clause asks for one thorough annual review and twelve lighter updates, and that is what the site does.", "PART 2 - THE ANNUAL MANAGEMENT REVIEW", "Held at least once every twelve months, and again whenever a change to the process, the product range, the facility or the organisation is significant enough to affect the SQF System. It is recorded on **FRM-001**, whose agenda carries the six items 2.1.2.1 names:", "• **(i) Changes to food safety management system documentation** - policies, procedures, specifications and the food safety plan. FRM-001 Section I.", "• **(ii) Food safety culture performance.** FRM-001 Section I, answered from the measures in **FSQM-006 Food Safety Culture Plan**: the results against the food safety objectives, who read the notices posted to the team, and the food safety problems staff raised during the year.", "• **(iii) Food safety objectives and performance measures.** FRM-001 Section II carries the targets senior site management has set, against the input each measures.", "• **(iv) Corrective and preventive actions, and trends** in internal and external audit findings, customer complaints, and verification and validation activities. FRM-001 Section II.", "• **(v) The hazard and risk management system.** FRM-001 Section I - changes to the HACCP plan, its hazard analysis and its critical limits.", "• **(vi) Follow-up action items from previous management reviews.** FRM-001 Section II, with the actions themselves tracked in Section IV.", "> Every agenda row is answered, including where the answer is \"no change\" or \"not performed\". A blank row cannot be told apart from one nobody considered, and the clause asks for the review rather than only for what it turns up.", "PART 3 - THE MONTHLY UPDATE", "The SQF Practitioner updates senior site management at least monthly on matters affecting the implementation and maintenance of the SQF System: verification activities that have fallen due, open corrective actions, complaints, incidents, audit findings, changes affecting the system, and anything requiring a decision or a resource.", "The update and **management's response to it** are recorded on **FRM-009 Monthly SQF Update Record**, one entry per month. The SQF Practitioner signs that the update was given and senior site management signs its response; where one person holds both posts they sign both. Actions arising are recorded on the same entry with an owner and a due date.", "> **This is a new record, and it starts from the effective date of this programme.** No retained record of the monthly update existed before it: the previous draft pointed at a \"Flash Report\" that exists nowhere in this system, so 2.1.2.2's requirement that the update and the response be documented was met on paper and not in fact. FRM-009 is deliberately short - twelve records a year are only kept if each takes minutes - and it is on the master verification schedule as a monthly activity, so it prompts itself rather than relying on somebody remembering.", "PART 4 - ACTIONS, RECORDS AND FOLLOW-UP", "Every action arising from either review is recorded with a responsible person and a target date - on FRM-001 Section IV for the annual review, on FRM-009 for a monthly update - and is reviewed for closure at the next meeting of either kind.", "An action that reveals a non-conformity in the SQF System is raised as a corrective action under **FSQM-009** on **FRM-007**, and is not tracked only on these records.", "Records are retained per the record retention policy. Both reviews are activities on the master verification schedule - the annual review evidenced by FRM-001 and the monthly update by FRM-009 - so each is prompted when it falls due, and the reminder closes when the entry is submitted.", "PART 5 - WHAT THIS PROGRAMME DOES NOT CLAIM", "• It does not set the site's food safety objectives. It reviews performance against those senior site management has set, and records where none are set yet.", "• It does not create data. Where an activity has not yet produced results - for example environmental monitoring (FSQM-015) before its first round - the review records that, rather than trending results that do not exist.", "• It does not replace the SQF Practitioner's day-to-day escalation of a food safety issue, which does not wait for a meeting."], "attachments": [{"name": "SOP_FSQM-0005_0001.docx", "path": "2d9682eb-ff5b-4e74-ab9a-c5fe1a2423d9/files/SOP_FSQM-0005_0001.docx"}], "definitions": "Management review (2.1.2.1) - the annual review of the whole SQF System by senior site management, against the six required agenda items. Recorded on FRM-001.\n\nMonthly update (2.1.2.2) - the SQF Practitioner's update to senior site management on matters affecting the implementation and maintenance of the SQF System, and management's response to it. A lighter, more frequent obligation, and a different one.\n\nSenior site management - the person or people accountable for the site, who own the SQF System. Where one person holds both this post and the SQF Practitioner's, they act in both and the record shows it as it is.", "responsibility": "Senior site management - convenes and chairs the annual management review, decides the outcomes and the resources, signs FRM-001, and responds to the monthly update.\nSQF Practitioner - prepares the inputs for the annual review, gives the monthly update, records both, and tracks the follow-up actions to closure.\nQuality and production staff - supply the data behind each input when asked for it.", "form_references": "FRM-001 - Management Review Record (the annual review)\nFRM-009 - Monthly SQF Update Record (the monthly update and management's response)\nFRM-007 - Corrective & Preventive Action Report (where a review finds a non-conformity)", "revision_history": "New - 2026-09-16 - First issue, under D-06 Management Review Upgrade.\n\nREPLACES A DRAFT THAT COULD NOT BE ISSUED. The document carried by this number had six of its ten sections empty - no purpose, definitions, records, form references, governing reference or revision history - and twelve generic procedure lines that did not map to 2.1.2.1's six agenda items. It referred to a \"Flash Report\" that exists nowhere in this system, and stated that \"besides the annual management review, the Quality Leader shall review the entire SQF System at least annually\", which is circular. It was rewritten rather than patched.\n\nTHE ANNUAL REVIEW AND THE MONTHLY UPDATE ARE KEPT SEPARATE. The gap assessment suggested that if every agenda item is reviewed monthly the separate annual review could be dropped. That is true on its face and was declined deliberately: it would commit the site to twelve full management review records a year, each covering all six items, where a quiet month becomes a hole in the evidence. 2.1.2.1 and 2.1.2.2 ask for different things at different depths, and the site now does both.\n\nTHE MONTHLY UPDATE HAS NO RECORD YET, and this document says so rather than implying otherwise. 2.1.2.2 was assessed Compliant on the strength of the previous draft's sentence about a Flash Report; that report does not exist. Part 3 states what the minutes must contain so the record can start being kept.\n\nFRM-001 GOES TO v4 IN THE SAME CHANGE. Three agenda items 2.1.2.1 requires were missing (documentation changes, food safety culture performance, and the hazard and risk management system stated as such); a verification and validation input was added for 2.1.2.1 (iv); the organisational chart row cited FSQM-002, the policy, instead of FSQM-004; two further references pointed at FSQM-026 and FSQM-033, numbers reserved for Food Fraud and Water & Utilities and not yet written; and three targets asserted work the site does not do - microbiological criteria, Listeria and Salmonella swabbing, and \"First Time Right in blending\". Those are removed, because an agenda claiming a control that does not exist is worse at an audit than one that is merely incomplete.\n\nTHE MONTHLY UPDATE GAINED A RECORD BEFORE ISSUE. On review it was pointed out that this programme named FRM-001 as the annual record but left the monthly update documented \"in minutes\" with no form, no location and nothing to prompt it - which is the same weakness as the Flash Report it replaced, one level less obvious. FRM-009 Monthly SQF Update Record was written for it and put on the verification schedule as a monthly activity, so 2.1.2.2 is evidenced by a record rather than asserted by a sentence.\n\nISSUED active 2026-09-16, approved GJM, with FRM-009 and with FRM-001 at v4. The monthly activity goes live on the master verification schedule in the same change, so the update is prompted rather than remembered. 2.1.2.2 is evidenced when the first FRM-009 entry is submitted, not by this issue.\n\nv2 — 2026-10-05 — Part 2 item (ii) revised under D-03. FSQM-006 Food Safety Culture Plan is issued, so the culture row of the annual review is no longer answered with \"no measures are in force\": it is answered from that plan's measures. Nothing else changes.\n\nv3 - 2026-10-29 - Two stale lines corrected: the monthly update is recorded on FRM-009 (as Part 3 already said), and environmental monitoring now exists (FSQM-015, issued 2026-10-29). Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.1.2.1 (management review at least annually, covering the six named items, with records maintained) and 2.1.2.2 (the SQF Practitioner updates senior site management at least monthly; the updates and management responses are documented)."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '2d9682eb-ff5b-4e74-ab9a-c5fe1a2423d9' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Applies to every non-conformance and every deviation from food safety requirements arising anywhere in the SQF System, whatever raised it: customer and consumer complaints, supplier non-conformances, non-conforming raw material, packaging, work-in-progress, finished product or equipment, non-compliance with a critical food safety limit, findings from internal and external audits and from regulatory inspections, findings from GMP and pre-operational inspections, environmental monitoring results, glass and brittle plastic breakage, and withdrawals and recalls including recall tests.\n\nThis program is the single route every one of those sources leads into. The record is FRM-007 (Corrective & Preventive Action Report) and the register is REP-007 (CAPA Log). The source form that raised the issue keeps its own detail; the CAPA number written back onto it is what ties the two together in both directions.\n\nWHAT THIS PROGRAM DOES NOT COVER. It governs the investigation and the action, not the fate of the product. Physical hold, tagging and disposition of non-conforming material are recorded on FRM-702 (Non-Conforming Material Hold & Tagging Record); the program governing that disposition is FSQM-018, which also authorises any rework. Executing a withdrawal or recall is FSQM-023 Product Withdrawal and Recall Program; this program covers the root cause investigation and the actions that follow one. The internal audit schedule itself is FSQM-038; this program covers what happens to the findings.", "purpose": "To document the responsibility and methods by which Adventure Bakery, LLC determines, implements and verifies corrective and preventive action — including the identification of the root cause and the resolution of non-compliance with critical food safety limits and deviations from food safety requirements — and to ensure that records of every investigation, root cause analysis, resolution, correction and preventive action are maintained.", "records": "Completed FRM-007 Corrective & Preventive Action Reports, with their investigation, root cause, actions, verification of effectiveness and closure, together with the evidence attached to each entry. Retained a minimum of two years, or the shelf life of the affected product plus twelve months, whichever is longer; permanently where the CAPA relates to a withdrawal or recall.\n\nThe REP-007 CAPA Log, held live in the Team Portal and exported at management review.\n\nThe monthly review of open and overdue CAPAs, recorded on FRM-009 Monthly SQF Update Record under \"Open corrective actions\".\n\nCAPA performance minuted at the annual management review on FRM-001.\n\nThe source records that raised each CAPA — FRM-002, FRM-205, FRM-702, FRM-908, FRM-913, FRM-903 — retained per their own retention periods, each carrying the CAPA number.", "procedure": ["PART 1 — WHAT RAISES A CORRECTIVE ACTION (SQF 2.5.3.1)", "> 2.5.3.1 names the sources a corrective and preventive action process shall serve: customer complaints, nonconformances raised at internal or external audits and inspections, non-conforming product and equipment, and withdrawals and recalls. This program serves all of them and the site's own additions, through one record.", "• **Customer and consumer complaints** — handled under SOP-2.1.3 and recorded on FRM-002. A complaint meeting Part 3 also opens a CAPA.", "• **Supplier non-conformances** — raised on FRM-205 (SCAR). The SCAR is the supplier's response; the CAPA is this site's own investigation of how the material reached the floor.", "• **Non-conforming raw material, packaging, work-in-progress or finished product** — held and tagged on FRM-702.", "• **Non-conforming equipment** — identified, tagged or segregated for repair or disposal, with the handling, corrective action and disposal recorded (11.1.7.9).", "• **Non-compliance with a critical food safety limit**, and any deviation at a CCP.", "• **Findings from internal audits**, and from external audits, certification body audits and regulatory inspections (2.5.4.1 iii, 2.5.4.4).", "• **Findings from GMP and pre-operational inspections** — the monthly site inspection on FRM-913 under FSQM-022, and the daily pre-operational check on FRM-903 (2.5.4.3 i).", "• **Environmental monitoring results** — a presumptive positive, an unsatisfactory result, or an adverse trend (2.4.8.3).", "• **Glass or brittle plastic breakage** — reported on FRM-908 under SOP-11.7.3.", "• **Withdrawals and recalls**, actual or from a recall test, and the root cause investigation into them (2.6.3.3).", "PART 2 — CORRECTION, CORRECTIVE ACTION AND PREVENTIVE ACTION ARE THREE DIFFERENT THINGS (SQF 2.5.3.1)", "• **Correction** is what is done to fix the thing observed — the pallet is removed, the surface is re-cleaned, the batch is held.", "• **Corrective action** is what is done so it does not happen again. It is written against the root cause of this non-conformance, not against the symptom.", "• **Preventive action** is what is done so the same cause cannot produce a non-conformance somewhere it has not yet occurred.", "> **The three are recorded separately on FRM-007.** A single “action taken” box conflates them, and that conflation is why findings repeat: the instance gets fixed and the cause does not.", "> A finding that recurs is telling you the correction was never followed by a corrective action. Repeats are flagged as repeats on FRM-007 and reviewed under Part 9.", "PART 3 — WHEN A CAPA IS OPENED (SQF 2.1.3.3, 2.5.3.1)", "> 2.1.3.3 requires corrective and preventive action to be implemented **based on the seriousness of the incident and the root cause analysis**. Escalation is therefore risk-based. Not every non-conformance becomes a CAPA; the ones below always do.", "> **A CAPA shall be opened for any of the following:**", "• Any non-conformance affecting product that has already been released, or that requires product to be held, reworked, downgraded or destroyed.", "• Any non-compliance with a critical food safety limit, or any deviation at a CCP.", "• Any complaint classified critical, and any complaint alleging illness, injury, foreign material or an undeclared allergen.", "• Any **repeat** — the same or substantially the same non-conformance within twelve months.", "• Any finding from an internal or external audit, a certification body audit, or a regulatory inspection.", "• Any finding at a GMP or pre-operational inspection that is not corrected on the spot, or that the person who found it cannot correct.", "• Any withdrawal or recall, actual or from a test.", "• Any presumptive-positive or adverse trend in environmental monitoring.", "• Any glass or brittle plastic breakage where product or a food-contact surface was exposed.", "• Anything the SQF Practitioner judges to warrant one.", "> **A routine non-conformance corrected on the spot, and not caught by the list above, is recorded on the form that found it and does not open a CAPA.** That record still states what was seen and what was done — a same-day fix is still a finding, and an inspection record showing only unresolved items misrepresents how the site runs.", "> **When in doubt, open one.** An unnecessary CAPA costs an hour. A missed one costs a repeat finding, discovered by an auditor rather than by this site.", "PART 4 — RAISING A CAPA, AND CONTAINMENT FIRST (SQF 2.5.3.1)", "> Any employee may raise a non-conformance and shall report it immediately to a supervisor or to the SQF Practitioner.", "> **Containment comes before investigation.** Before anything is analysed: make the product safe. Hold and tag affected material on FRM-702, stop the process where it is still running, isolate the area or the equipment, and determine whether product already released is affected. **If released product may be affected, FSQM-023 is invoked immediately — it does not wait for the investigation to finish.**", "> The SQF Practitioner opens FRM-007 and assigns the number **CAPA-YYYY-NNN** — the calendar year and the next sequential number within that year, beginning at CAPA-2026-001. Numbers are never reused, and a CAPA that is later found to be unnecessary is closed with that reason rather than deleted.", "> **The number is written back onto the record that raised it** — the CAPA Ref field on FRM-002, the CAR Ref field on FRM-908, the CAPA No. column on FRM-913, and the equivalent reference on FRM-205 and FRM-702. That cross-reference is what lets an auditor trace in either direction: from a complaint to its investigation, or from the register back to what raised it.", "> What was contained, by whom and when is recorded on FRM-007 before the investigation begins.", "PART 5 — INVESTIGATION AND ROOT CAUSE (SQF 2.5.3.1, 2.1.3.2)", "> **Every CAPA has a documented root cause.** “Operator error” and “training issue” are not root causes. If an operator made an error, the question is why the process allowed that error to reach product undetected.", "> **The default method is Five Whys**, recorded on FRM-007 so the reasoning is visible and not just the conclusion. Where five whys is not adequate — a recurring failure, or one with several contributing causes — a cause-and-effect (fishbone) analysis is used and attached to the entry.", "> The investigation is carried out by a person **knowledgeable about the incident** (2.1.3.2) and, where practical, not the person whose work is under examination.", "> The investigation establishes: what happened; when it started; how much product and which lots are affected; why the control failed; and **why it was not detected sooner**. The last is a separate question from the first, and it is usually where the real corrective action lies — a control that failed and was caught is a different problem from one that failed and was not.", "PART 6 — CORRECTIVE AND PREVENTIVE ACTION (SQF 2.5.3.1, 2.5.4.4)", "> Actions are written against the root cause established in Part 5.", "> **Every action carries a named owner and a due date. An action without an owner and a date is not an action.** Both are recorded on FRM-007 when the action is agreed, not afterwards.", "> **Preventive action asks where else the same cause could bite** — another line, another product, another shift, another supplier, another piece of equipment with the same failure mode. Where the answer is nowhere, that is recorded as the answer.", "• Where an action changes a procedure, program, specification or form, the change is made under document control and the CAPA records the document and the revision it moved to.", "• Where an action requires training, the module is assigned in the Team Portal and the CAPA records the module and the people trained.", "• **Where a change arising from an internal audit affects the site's ability to deliver safe food, the applicable aspects of the SQF System are reviewed** (2.5.4.4, referring to 2.3.1.3), and that review is recorded on the CAPA.", "PART 7 — VERIFICATION OF EFFECTIVENESS (SQF 2.5.3.1)", "> 2.5.3.1 requires corrective and preventive actions to be determined, implemented **and verified**. Completing an action is not verification. **A CAPA is not closed because the work was done; it is closed because someone checked that it worked.**", "> **The verification method and date are set when the action is agreed, not after it is finished.** An action agreed without a verification plan will be closed on the day it is completed, which is the failure this Part exists to prevent.", "> The method is chosen to actually test the cause. Re-inspect the item at the next GMP inspection; review the next stated number of records or batches; re-test; re-audit the clause; watch the complaint category over the next quarter. **The verification date is at least one full cycle of whatever failed** — verifying a monthly check after one week proves nothing.", "> Verification is performed and signed by the SQF Practitioner or by a person independent of the action owner.", "> **If verification shows the action was not effective, the CAPA is not closed.** It is reopened: either the root cause was wrong or the action was insufficient, and the investigation resumes from Part 5. The failed verification stays on the record.", "PART 8 — CLOSURE (SQF 2.5.3.1)", "> A CAPA closes only when **all** of the following are true:", "• The correction is done and recorded.", "• The root cause is documented.", "• Every corrective and preventive action is complete.", "• Effectiveness has been verified and signed.", "• Any affected document, program or record has been updated.", "• The disposition of any affected product is resolved.", "> Closure is signed and dated by the SQF Practitioner on FRM-007.", "> **Open and overdue CAPAs are reviewed at least monthly** against REP-007, at the monthly SQF update, and **the review is recorded on FRM-009 Monthly SQF Update Record** under \"Open corrective actions\". An overdue action is followed up with its owner and a revised date is recorded with the reason on its FRM-007 — a due date that silently moves is not a controlled record.", "PART 9 — TRENDING AND MANAGEMENT REVIEW (SQF 2.1.2.1 iv, 2.1.3.2, 2.4.8.3)", "> **REP-007 (CAPA Log) is the register** — every CAPA with its source, severity, root cause, owner, due date and status, projected live from the FRM-007 entries. It is the answer to “show me your open corrective actions”.", "> The SQF Practitioner reviews the register at least monthly for overdue actions, repeats, and sources that keep recurring, in the same review, recorded on FRM-009. It covers the corrective actions opened and closed since the last monthly update - every one on record at the first - with the result of each effectiveness check, and every corrective action still open, whenever it was raised.", "> **CAPA performance is a standing item at management review** (2.1.2.1 iv) and is minuted on FRM-001: the number opened and closed in the period, the breakdown by source, what is overdue, and what has repeated.", "> **Adverse trends in complaint data are investigated and their root cause established by personnel knowledgeable about the incidents** (2.1.3.2), even where no single complaint met the Part 3 threshold. Where the trend itself is the non-conformance, a CAPA is opened against the trend.", "> Where environmental monitoring results or trends are unsatisfactory, preventive action is implemented through this program (2.4.8.3).", "PART 10 — RECORDS AND RETENTION (SQF 2.5.3.2, 2.5.4.4, 2.6.3.3)", "• **Records of all investigation, root cause analysis and resolution of non-conformities, their corrections, and the implementation of preventive actions are maintained** on FRM-007 and in the REP-007 register (2.5.3.2).", "• Records of internal audits and inspections, and of any corrective and preventive action taken as a result of them, are recorded through this program (2.5.4.4).", "• Records of withdrawal and recall tests, of the root cause investigation into any actual withdrawal or recall, and of the corrective and preventive actions applied, are recorded through this program (2.6.3.3).", "> Supporting evidence — photographs, laboratory reports, supplier correspondence, updated documents, training records — is attached to the FRM-007 entry, so the investigation and its evidence are one record rather than two.", "> **Retention: a minimum of two years, or the shelf life of the affected product plus twelve months, whichever is longer.** A CAPA relating to a withdrawal or recall is retained permanently."], "definitions": "Non-conformance — any departure from the SQF Food Safety Code, from this site's own documented programs, from a customer requirement or from a regulatory requirement, whether or not it was corrected on the spot.\n\nCorrection — what is done to fix the thing observed. Corrective action — what is done so it does not happen again. A repeat finding is usually a correction that was never followed by a corrective action.\n\nPreventive action — what is done so that the same cause cannot produce a non-conformance somewhere it has not yet occurred — another line, another product, another shift, another supplier.\n\nRoot cause — the reason the control failed, established by investigation rather than assumed. “Operator error” and “training issue” are not root causes; they are the point at which an investigation stopped.\n\nVerification of effectiveness — the check, made at a stated date after the action is complete, that the non-conformance has actually gone. Completing an action is not verification.\n\nRepeat — the same or substantially the same non-conformance recurring within twelve months, whether or not the earlier one was closed.\n\nCAPA — a Corrective and Preventive Action, opened under Part 3, numbered under Part 4 and recorded on FRM-007.", "responsibility": "SQF Practitioner — owns this program. Opens and numbers each CAPA, agrees the root cause, agrees every action with its owner and due date, sets the verification method and date, verifies effectiveness, and closes the CAPA. Reviews REP-007 at least monthly for overdue and repeat items, and reports CAPA performance to management review.\nAll staff — may raise a non-conformance, and shall report one immediately to a supervisor or to the SQF Practitioner. No employee is disadvantaged for raising one.\nAction owners — complete the action they accepted by the date they accepted, and tell the SQF Practitioner before the due date if they cannot.\nSupervisors — ensure containment happens immediately, and that a finding on their shift reaches the SQF Practitioner the same day.\nSenior management — reviews CAPA trends, overdue actions and repeat findings at management review, and provides the resources actions require.", "form_references": "FRM-007 — Corrective & Preventive Action (CAPA) Report — the record for every CAPA\nREP-007 — CAPA Log — the register, projected from FRM-007\nFRM-002 — Customer Complaint Report (raises a CAPA; carries the CAPA Ref)\nFRM-205 — Supplier Non-Conformance & Corrective Action Report (SCAR)\nFRM-702 — Non-Conforming Material Hold & Tagging Record (containment and disposition)\nFRM-908 — Glass Breakage Incident Report (carries the CAR Ref)\nFRM-913 — GMP / Food Safety Inspection Record (carries the CAPA No. column)\nFRM-903 — Daily Sanitation, Pre-Operation & Release Record\nFRM-001 — Management Review Record (CAPA trends)\nSOP-2.1.3 — Product Complaints\nSOP-11.7.3 — Glass & Brittle Plastic Control\nFSQM-022 — Food Safety Monitoring Program (the inspections that raise findings)\nFSQM-018 — Non-Conforming Product and Equipment (product disposition and rework)\nFRM-009 — Monthly SQF Update Record (the monthly review of open and overdue CAPAs)", "revision_history": "v2 — 2026-10-16 — Where the monthly CAPA review is recorded.\n\nPart 8 required open and overdue CAPAs to be reviewed at least monthly, and Part 9 the register to be reviewed for overdue actions, repeats and recurring sources, but neither said where the review is recorded. The verification schedule named FRM-007, the report of one corrective action, which cannot show a month's review, so its reminder could never be discharged. The review is done at the monthly SQF update and recorded on FRM-009 Monthly SQF Update Record under \"Open corrective actions\"; Parts 8 and 9 now say so, and Part 9 states what the review covers. FRM-009 is added to the forms referenced. Records corrected: CAPA performance is minuted at the ANNUAL management review on FRM-001 - the earlier text called it monthly - and the monthly review on FRM-009 is listed. No step of the program changes (owner's decision, 2026-10-16; FSQM-017 v16 changes the schedule line).\n\nNew — 2026-09-02 — Created under D-07 (CAPA Program + Investigation Form).\n\nWHY THIS DOCUMENT EXISTS. 2.5.3 Corrective and Preventative Action is a **Mandatory** element of the Code, and the site had no document against it. The gap assessment raised five Minor findings that this program and FRM-007 answer: 2.1.3.3 (no documented process for investigating and resolving complaints aligned to 2.5.3), 2.5.3.1 (no procedure stating the methods and responsibilities for corrective and preventive action), 2.5.3.2 (no records of investigation, root cause analysis and resolution), 2.5.4.4 (audit and inspection findings and their CAPAs not recorded per 2.5.3), and 2.6.3.3 (recall and withdrawal root cause investigations and their CAPAs not recorded).\n\nWHAT IT CLOSES, AND WHAT IT DOES NOT. The consultant's evidence against 2.5.4.4 reads that the site has not developed an Internal Audit Program, and against 2.6.3.3 that it has not developed a Product Recall and Withdrawal Program. **Those two programs are separate deliverables and this one does not claim them.** What this program closes is the records limb of each: that a finding from an audit or an inspection, and the root cause investigation into a withdrawal or recall, are raised, investigated, actioned, verified and retained through a documented CAPA process. When those two programs are written they will reference this one rather than restate it.\n\nIT ALSO CLOSES AN OPEN ITEM ON FSQM-022. That program was issued on 2026-09-01 stating: “the corrective-action half of this program has nowhere to live beyond FRM-913's own columns. D-07 (CAPA) is the object findings from any source should be raised into”. It now has one. FRM-913 gains a CAPA No. column in the same change, so an escalated inspection finding carries its number.\n\nTHE SITE WAS NOT STARTING FROM NOTHING, AND THIS PROGRAM SAYS SO. Four active fillable forms already capture root cause and corrective action for their own source: FRM-002 (complaints), FRM-205 (supplier SCAR), FRM-702 (non-conforming material hold) and FRM-908 (glass breakage, which has carried an unused CAR Ref field since it was written). What was missing was a governing procedure and a single register. Those forms are therefore kept and referenced, not replaced — a complaint needs the customer and the lot, a SCAR needs the supplier and the purchase order, and folding all of that into one universal form would have lost detail the sources need.\n\nESCALATION IS RISK-BASED BY DESIGN. Part 3 lists ten triggers that always open a CAPA and states that a routine on-the-spot correction stays on the form that found it. The alternative — a CAPA for every non-conformance — is simpler to audit but fills the register with trivia and hides the findings that matter, which for a site of this size would make the register useless within a quarter. 2.1.3.3 explicitly supports the risk-based reading: action is taken “based on the seriousness of the incident and the root cause analysis”.\n\nSETTLED AT ISSUE. The five points below were listed as open before activation. The program was reviewed and ISSUED AS WRITTEN by GJM on 2026-09-02, which adopts the position each of items 1 to 4 states in the body — the retention period in Part 10, closure by the SQF Practitioner in Part 8, the ten triggers in Part 3, and the verification arrangement in Part 7. Those are now the site's stated position and not open questions; they are kept here because the reasoning behind each is what an auditor will ask about. Item 5 is a dependency on another document and remains genuinely open.\n1. RETENTION PERIOD. Part 10 and Records state a minimum of two years, or shelf life plus twelve months where that is longer, and permanent retention for a recall-related CAPA. This is written to sit alongside FRM-908's two-year retention and FRM-903's twelve months. Confirm it, or state the period the site intends.\n2. WHO MAY CLOSE A CAPA. Part 8 gives closure to the SQF Practitioner alone. On a team this size that is a single point of failure, and a CAPA the practitioner owns as an action is one the practitioner then verifies and closes. Name a second person authorised to close, or confirm the single-signature arrangement deliberately.\n3. THE TEN TRIGGERS IN PART 3. They were written to catch what an auditor will look for, not from watching this floor. Read them against how the site actually runs: too low and the register fills with trivia, too high and a repeat finding reaches the auditor before it reaches the register.\n4. VERIFICATION INDEPENDENCE. Part 7 asks for verification by the SQF Practitioner or someone independent of the action owner. Where the practitioner is the action owner there is no independent verifier on site. Confirm the fallback — a second employee, or an accepted and stated limitation.\n5. FSQM-018 IS A DRAFT. The Scope points at it for the disposition of non-conforming product and says so plainly rather than implying an approved document exists. FRM-702 is active and is the operative record today. FSQM-018 should be issued or withdrawn.\n\nDELIVERED WITH THIS PROGRAM: FRM-007 (the report), REP-007 (the register), a CAPA Ref field on FRM-002 with the matching column on REP-003 — a gap the codebase had already documented and left open — and a CAPA No. column on each of FRM-913's eight Module 11 grids.\n\nEvery form, procedure and program named in this document was checked against the live register on 2026-09-02 and exists. FSQM-018 is named explicitly as a draft. Nothing here repeats the FSQM-022 mistake of requiring a record that was never built.\n\nISSUED 2026-09-02, approved GJM. Status active, revision New. FRM-007 (the record) and REP-007 (the register) are activated in the SAME TRANSACTION, so this program is never active without the form it requires or the register it reports from — the same sequencing that kept the site from ever being without a personnel hygiene document when FSQM-012 superseded SOP-11.3.\n\nSTILL OPEN AFTER ISSUE: FSQM-018 Non-Conforming Product and Equipment remains an unapproved draft. The Scope names it as a draft rather than implying otherwise. FRM-702 is active and is the operative record for holding and tagging non-conforming material until FSQM-018 is issued or withdrawn.\n\nv3 - 2026-10-29 - Stale references corrected: FSQM-018 is issued (it was described as a draft); rework is authorised under FSQM-018, not the draft FSQM-019; the recall procedure and the internal audit program are named as FSQM-023 and FSQM-038. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.5.3 Corrective and Preventative Action (Mandatory). 2.5.3.1: the responsibility and methods outlining how corrective and preventative actions are determined, implemented and verified, including the identification of the root cause and resolution of non-compliance of critical food safety limits and deviations from food safety requirements, shall be documented and implemented. 2.5.3.2: records of all investigation, root cause analysis and resolution of non-conformities, their corrections, and the implementation of preventative actions shall be maintained.\n\n2.1.3.3 — corrective and preventative action implemented based on the seriousness of the incident and the root cause analysis as outlined in 2.5.3; records of customer complaints, their investigation and resolution maintained.\n\n2.5.4.4 — records of internal audits and inspections and any corrective and preventative actions taken as a result shall be recorded as per 2.5.3, and changes affecting the site's ability to deliver safe food require a review of applicable aspects of the SQF System.\n\n2.6.3.3 — records of withdrawal and recall tests, root cause investigations into actual withdrawals and recalls, and corrective and preventative actions applied.\n\nAlso served: 2.1.2.1 (iv) management review of corrective and preventative actions and trends; 2.1.3.2 adverse complaint trends investigated and root cause established; 2.4.8.3 preventative action on unsatisfactory environmental results; 2.5.4.1 (iii) and 2.5.4.3 (i) corrective and preventative action on internal audit and inspection findings; 11.1.7.9 records of the handling, corrective action and disposal of non-conforming equipment."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '6d069d17-c19f-4ef2-bbfd-1a9968046d81' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Every delivery of raw material and packaging received at the site, every production batch while it is being made, and every batch of finished product before it is released.\n\nIt does not cover the release decision itself, which is FSQM-020 Product Release Program; the disposition of anything that fails an inspection, which is FSQM-018 Non-Conforming Product and Equipment; the pre-operation inspection of a line, which is a sanitation control recorded on FRM-903; or the development and approval of specifications, which is SOP-2.3.1 New Product and Specification Process.", "purpose": "This program states the methods, the responsibility and the criteria for sampling and inspecting raw materials, packaging, work-in-progress and finished product at Adventure Bakery, the intervals at which those inspections are carried out, and where each one is recorded. It satisfies the Product Sampling, Inspection and Analysis element of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.4.4).", "records": "FRM-301 Incoming Material Receiving & Inspection Log — the incoming inspection of every delivery of raw material and packaging, kept in the Team Portal.\nBatch sheets — the in-process inspection of every batch, recorded as the batch is made.\nFRM-701 Finished Product Release Record — the finished product inspection, recorded as part of the release decision under FSQM-020.\nFRM-703 Retention Sample Log — every retention sample taken, where it is stored, and its disposal.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where an inspection failure results in a hold.\nTogether these are the records of all inspections that SQF 2.4.4.6 requires. Product is not analysed for acceptance — see Part 2. Environmental results are on FRM-706 (FSQM-015), and the reports of the validation tests of the food safety plan are kept with FSQM-016.\nRetention: two years, or the shelf life of the product plus twelve months, whichever is longer. This is the period set by FSQM-009 Part 10, so an inspection, a hold arising from it and any investigation that follows are retained on the same basis.", "procedure": ["Every delivery of raw material and packaging, every production batch while it runs, and every batch of finished product before release shall be inspected against stated criteria, and the result recorded.", "> SQF 2.4.4.1 asks for three things — the method, the responsibility and the criteria — documented and implemented, at regular intervals, to agreed specifications and legal requirements. Parts 3, 4 and 5 supply them. An inspection that happens but is not recorded satisfies none of it, which is why 2.4.4.6 was scored: at the gap assessment no inspection records were available to review.", "Adventure Bakery inspects. It does not analyse product as a test of acceptance. There is no on-site laboratory, and no chemical, microbiological or nutritional analysis is performed on or commissioned for any raw material, packaging, work-in-progress or finished product in order to accept or release it. No supplier Certificate of Analysis is relied upon as an acceptance test at receiving. Two kinds of sample do go to an outside laboratory, and neither is an acceptance test: swabs from the room under the environmental monitoring program (FSQM-015), and the validation tests of the finished product named in the food safety plan, water activity and pH (FSQM-016). That laboratory meets the rule below.", "> This is stated rather than left silent, for the reason FSQM-020 Part 5 states that positive release is not used: a document that implies a testing regime the site does not operate is worse than one that says plainly there is none, because the first thing an auditor does is ask to see the results.", "> Three things follow from it. SQF 2.4.4.2 governs how analyses are conducted, by what methods and by what laboratory; where none are conducted, its requirements do not arise. SQF 2.4.4.3 and 2.4.4.4 govern the siting, access control and waste handling of an on-site laboratory; there is none, so both are recorded as Not Applicable, and the GMP inspection under FSQM-012 records that there is no laboratory to inspect.", "> What must happen before this changes: if any analysis is ever introduced, the method shall be named in this program, and any external laboratory shall be accredited to ISO/IEC 17025 or an equivalent international standard and listed on the contract services register before the first sample is sent to it. The method comes first, then the laboratory, then the sample.", "The site performs three inspections. Each already has its own record, and this program names them rather than creating a second place to write the same thing down.", "• Incoming raw material and packaging — inspected at receipt, before the delivery is accepted into stock, and recorded on FRM-301 Incoming Material Receiving & Inspection Log. Criteria: the material and quantity match the purchase order; the packaging is intact, clean and undamaged; the lot code and date are present, legible and within date; there is no sign of pest activity, water damage or foreign matter; and the vehicle it arrived in was fit to carry food.", "• Work-in-progress — inspected during the run against the batch sheet, and recorded on it. Criteria: the formula was followed; the process steps and process controls stayed within their stated limits; and the pack, seal, date and lot code are correct as the run proceeds.", "• Finished product — inspected before release against the checks listed in FSQM-020 Part 4, and recorded on FRM-701 Finished Product Release Record.", "> FRM-301 is an active controlled document and a fillable record in the Team Portal. Its Receiving Log carries a package-label scan on every row: the receiver photographs the material's own label and the supplier, the material description and the lot code are read from it into the row. That is the control worth having here — a lot code transcribed by hand at a loading dock is the entry most likely to be wrong, and it is the one every trace exercise afterwards depends on.", "Inspection is of every batch and every delivery, not of a sample of them. Where a unit or a portion is taken to be examined, it shall be taken from the batch it represents and be typical of it.", "> SQF 2.4.4.1 requires sampling and testing to be representative of the process batch. At this site's volumes every batch is inspected, which is the strongest form of that requirement and the simplest to evidence. The rule about how a unit is taken matters because the failure it guards against is real: a unit taken from the same corner of every pallet is not representative of anything.", "The criteria for finished product inspection are those listed in FSQM-020 Part 4, together with the product's approved label and its agreed pack and quantity configuration.", "> This states the criteria here, in terms, so that the inspection can be carried out without opening another document. Each flavour's finished product specification is its FRM-704 entry (SOP-2.3.1, SQF 2.4.4.1); where FRM-704 states a criterion more tightly than this Part, FRM-704 governs.", "> When the specification library exists, the criteria in this Part move to the specification and this Part points at it instead. That work is a separate deliverable and is not done here.", "Retention samples are not required of Adventure Bakery by any customer or by any regulation applying to this site. The site retains them regardless, so the basis on which a sample is taken, the condition it is held in, the period it is kept and the manner of its disposal are stated here.", "> SQF 2.4.4.5 imposes its rule only where retention samples are required by a customer or by a regulation, and here neither requires them. The practice therefore needs a basis of its own. A sample an auditor finds in the building without one is not a retention sample; it is old product held for no stated reason, and the auditor is entitled to ask which of the two it is.", "• A sealed unit of each finished product shall be retained, in the pack and configuration in which it shipped.", "• Each retained sample shall be identified with the product, the batch or lot code, and the date code printed on the pack, so that it can be matched to the batch it speaks for and to that batch's release record on FRM-701.", "• Retained samples shall be held on the reserved retention shelf in the ambient warehouse, which is the product's normal storage condition, identified as retention samples and kept separate from saleable stock so that one cannot be picked and shipped.", "• A retained sample shall be kept until thirty days after the best-by or expiration date printed on its pack, and then discarded. Where a customer agreement requires a longer period for that customer's product, the longer period applies.", "• Where the pack is coded with a month and year only, the thirty days shall run from the last day of that month.", "• Each retained sample shall be logged on FRM-703 Retention Sample Log when it is taken, and its disposal recorded there when it leaves the shelf — whether it is discarded at the end of its period or used earlier for a complaint or an investigation.", "> A retained sample speaks for the lot it was taken from and for no other. Retention here is organised by product rather than by batch, so where a product runs more than once inside the retention period the shelf will not hold a unit of every lot that is in the market. That limit is stated here rather than discovered during a complaint: the sample shows what a product was as made, packed, coded and labelled, and it is the batch sheet and FRM-701 that answer what happened on a particular run.", "> The period is anchored to the date printed on the pack rather than to a specification, and that is deliberate. SQF 2.4.4.5 measures retention against the stated shelf life of the product, which ordinarily means the finished product specification — FRM-704, which states the same twelve months. The date coded onto every pack is the shelf life the site has in fact stated for that unit. It exists today, and it is legible on the retained sample itself, so the date a sample may be discarded can be read off the sample without opening another document.", "> The thirty days is this site's own margin and not a requirement of the Code, which measures to the stated shelf life and stops there. It is here because a complaint about a unit eaten near its date arrives after that date, and a sample discarded on the date itself would be gone exactly when it was wanted.", "> A retained sample at this site cannot be tested. No analysis of any kind is performed or commissioned — see Part 2 — so what a sample can show is what was made, how it was packed, coded and labelled, and how it presents when compared against a complaint. That is worth keeping, and it is also why the period is measured in weeks past the printed date rather than in years: a baked product long past its date no longer shows how it left the site.", "> The sample and the record are on different clocks and are not to be confused. The sample is discarded thirty days after the printed date. FRM-703, the record that the sample was taken and disposed of, is retained on the same basis as every other record in this program — see the Records section.", "Anything that fails an inspection shall not be accepted, processed further or released.", "• A delivery that fails incoming inspection is rejected or placed on Hold under FSQM-018 Non-Conforming Product and Equipment and recorded on FRM-702.", "• A batch that fails an in-process or finished-product inspection is placed on Hold under FSQM-018 and dispositioned there; the release record ends at \"not released\".", "• A CAPA is raised under FSQM-009 Corrective and Preventive Action Program wherever its Part 3 requires one.", "The SQF Practitioner shall confirm at least annually that the inspections described in Part 3 are the inspections actually being performed, and shall revise this program where they are not.", "> This program's risk is not that it is wrong today but that the floor moves and it does not. The annual confirmation is the verification activity for 2.4.4, and is recorded as a revision of this program.", "Records are retained as set out in the Records section of this program."], "definitions": "Inspection: examination against stated criteria by a person, using the senses together with simple measurement such as count, weight, temperature, date code, seal integrity and appearance. Every check this program requires is an inspection.\n\nAnalysis: a chemical, microbiological, nutritional or physical test carried out to a recognised method, whether in a laboratory on site or by an external laboratory. Adventure Bakery does not analyse product to accept or release it; the analyses it commissions are listed in Part 2.\n\nRetention sample: a unit of finished product kept after the batch has been released, so that a later question about that batch can be answered against the product itself.\n\nRepresentative: taken from the batch it is meant to speak for, and taken so that what is examined is typical of that batch rather than of one convenient corner of it.", "not_applicable": [{"clause": "2.4.4.3", "reason": "The site has no on-site laboratory."}, {"clause": "2.4.4.4", "reason": "The site has no on-site laboratory, so holds no laboratory waste."}], "responsibility": "SQF Practitioner — owns this program. Sets the inspection criteria, reviews the inspection records, and decides release under FSQM-020. Confirms at least annually that the inspections described here are the inspections actually being performed.\nProduction staff — carry out the in-process inspections during the run and record them on the batch sheet. At packing, take the retention sample, place it on the reserved retention shelf and log it on FRM-703, signing as the person who took it.\nQuality Team — carries out the incoming inspection at receipt and records it on FRM-301; checks the retention shelf against FRM-703 and records each sample's disposal there; places on Hold anything that fails.\nAdmin — does not accept a delivery into stock without a completed incoming inspection.\nManagement team — provides the resources inspection requires, and is notified where an inspection failure stops production or shipment.", "form_references": "FRM-301 Incoming Material Receiving & Inspection Log; FRM-701 Finished Product Release Record; FRM-703 Retention Sample Log; FRM-702 Non-Conforming Material Hold & Tagging Record; batch sheets", "revision_history": "Rev New — written 2026-09-09 against SQF Food Safety Code: Food Manufacturing, Edition 9, 2.4.4 Product Sampling, Inspection and Analysis. ISSUED 2026-09-09, approved GJM. Status active, revision New — a first issue, not a revision, so nothing is superseded and nothing archived. FRM-703 Retention Sample Log is activated in the same transaction, because Part 6 requires every retained sample to be logged on it and that form prints Part 6 rule on its own face; an active programme requiring a draft record is the finding this wave exists to close.\n\nWHY IT EXISTS. The gap assessment scored four Minors across 2.4.4: no documented method for sampling, inspecting or analysing raw materials, work-in-progress or finished product (2.4.4.1); no analysis methods named (2.4.4.2); no retention-sample position (2.4.4.5); and no inspection or analysis records available to review (2.4.4.6). Underneath them sat a live inconsistency — FSQM-020 Product Release Program is active, and its release check reads \"the customer's agreed specification\" and \"the product's appearance and sensory standard\", neither of which the register holds. FSQM-020 carries that as its own open item 1. This program closes the pointer as well as the clause.\n\nTHE SITE INSPECTS; IT DOES NOT ANALYSE, confirmed by the owner 2026-09-09. There is no on-site laboratory, no external laboratory is used, and no chemical, microbiological or nutritional analysis is performed on or commissioned for anything — not even a supplier Certificate of Analysis relied on at receiving. Part 2 states this plainly, in the form FSQM-020 Part 5 uses for positive release, and names what must happen before it changes: the method first, then an ISO/IEC 17025-accredited laboratory listed on the contract services register, then the sample. Three consequences are recorded rather than left for a reader to work out — 2.4.4.2's limbs do not arise where no analysis is conducted, 2.4.4.3 and 2.4.4.4 are Not Applicable for want of a laboratory, and the remediation plan's instruction for this deliverable (\"appoint an ISO/IEC 17025-accredited external laboratory\") does not fit this site and was not followed.\n\nIT NAMES EXISTING RECORDS RATHER THAN CREATING NEW ONES. The three inspections the site performs already have records: FRM-301 at receiving, the batch sheet in process, FRM-701 at release. A fourth general inspection log would be a second place to record what is already recorded, which is how FSQM-018 and FSQM-019 came to name different authorities for rework. The one genuinely unrecorded thing is the retention sample, so FRM-703 is the only new record this deliverable adds.\n\nPART 5 IS A WORKAROUND AND SAYS SO. 2.4.4.1 requires inspection to agreed specifications, and the site holds no finished product specification. Part 5 therefore states the finished-product criteria explicitly — FSQM-020's release checks, the approved label, and the agreed pack and quantity — so that the inspection is performable today, and records that those criteria move to the specification once the library exists. Building that library is a separate deliverable. This program does not claim to close 2.4.4.1 outright while the specification it inspects against does not exist.\n\nNO GLUTEN FREE CLAIM — SETTLED 2026-09-09, AND ITS PREMISE WAS FALSE. This document was drafted carrying an open item that read \"the Gluten Free claim is not verified by any test\", on the understanding that the site was GFCO certified and sold product bearing that claim. The Managing Partner confirmed the same day that Adventure Bakery makes no product carrying a Gluten Free claim, has never made one, and holds no current GFCO certification. The item therefore does not close on evidence; it dissolves, because the thing it was about does not exist. Part 2's rule for introducing analysis stands unchanged — name the method, then an ISO/IEC 17025-accredited laboratory, then send the sample — and only its gluten example is gone, since repeating it would carry the same false premise into an issued document.\n\nThat assumption came from somewhere, and it is not confined to this document: FSQM-018 and FSQM-020 were both issued describing certified Gluten Free product and a current GFCO certification agreement, and are corrected by 20260909000008 and 20260909000007. The likeliest source is the Compass Blending hardcopies these documents were scanned from — the import rebrands the company name across every parsed string, but cannot know that the content itself belongs to a different business.\n\nRETENTION PERIOD — SETTLED 2026-09-09. The practice was to keep samples for about a year, with no rule enforced, and the owner asked whether that much is needed beyond the product's expiration date. It is not. SQF 2.4.4.5 imposes its rule only where retention samples are required by a customer or a regulation, and neither requires them here; where the rule does apply it measures retention against the stated shelf life and stops there. No federal rule reaches a bakery on this point either — reserve-sample requirements sit in infant formula and in dietary supplements, not in baked goods. Part 6 now sets the period at thirty days past the best-by or expiration date printed on the pack, with a customer agreement governing where it requires longer.\n\nANCHORING THE PERIOD TO THE PRINTED DATE RESOLVES A DEPENDENCY. 2.4.4.5's own wording is \"the stated shelf life of the product\", which ordinarily means the finished product specification — and the site holds none, which is the same gap Part 5 works around. The date coded onto every pack is the shelf life this site has in fact stated for that unit; it exists today, and it is legible on the retained sample itself. Part 6 is therefore performable now, does not wait on the specification library, and will not need to change when that library is built.\n\nTHE PACKS ARE CODED TO THE MONTH, NOT TO THE DAY. A finished pack examined on 2026-09-09 reads \"Best By: July 2027\" — a month and a year, with no day in it. Thirty days after that is ambiguous by up to a month, so Part 6 states the convention: the period runs from the LAST day of the coded month. That is the reading that keeps the sample longer, which is the right direction to be wrong in on a safety record. It also decides how FRM-703 records the date — as text, exactly as printed, rather than as a calendar date for which the filler would have to invent a day and then record the invention as a printed fact. A record of the pack should say what the pack says.\n\nTHE THIRTY DAYS IS THE SITE'S OWN MARGIN and is recorded as such rather than dressed as a requirement. A complaint about a unit eaten near its date arrives after that date, and a sample discarded on the date would be gone exactly when it was wanted. Little is lost by shortening from a year: the sample cannot be tested, since no analysis of any kind is performed (Part 2), so what it can show is what was made, packed, coded and labelled — and a baked product long past its date no longer shows that reliably. BEFORE THIS IS ISSUED, CHECK THE TOLLING AGREEMENTS: a contractual retention term is the likeliest reason a year became the habit, and Part 6 defers to a customer agreement where one requires longer.\n\nPart 6 also now states that retained samples are separated from saleable stock. That was not asked for. A retained unit is finished product in its own shipping pack sitting in the building, and if it is not identified and separated it can be picked and shipped.\n\nRETENTION UNIT AND LOCATION — SETTLED 2026-09-09, and the unit is NOT what this document first assumed. Part 6 was drafted stating one sealed unit per PRODUCTION BATCH, inferred rather than confirmed because that is the unit the rest of the system uses — FRM-701 releases a batch. The owner confirmed the actual practice: a sample is retained PER PRODUCT, and samples are stored on a reserved shelving spot in the room-temperature warehouse. Part 6 now says both, and names the shelf rather than referring to \"a designated location\".\n\nTHE DIFFERENCE IS NOT COSMETIC AND IS RECORDED IN PART 6 ITSELF. A retention sample can only answer a question about the lot it came from. Organised by product, the shelf will not hold a unit of every lot in the market whenever a product runs more than once inside the retention period, so a complaint about an older lot may find no matching sample. The site is not required to hold retention samples at all, so this is not a deficiency against 2.4.4.5 — but a document that implied every lot was covered would be claiming a control the site does not operate, which is the defect this whole programme keeps removing. Part 6 states the limit and points at the records that do cover every lot.\n\nAmbient storage is the product's normal storage condition — everything this site ships is ambient — so 2.4.4.5's \"stored according to the typical storage conditions for the product\" is met by the shelf as it stands, and is now evidenced rather than asserted.\n\nSETTLED AT ISSUE — the two items this programme carried are decided. They are recorded here rather than deleted, because a reader is better served by knowing what was decided and on what basis than by a history that shows only the conclusion.\n\n1. THE SPECIFICATION LIMB OF 2.4.4.1 IS NOT CLOSED BY THIS DOCUMENT, and issuing does not pretend otherwise. The clause requires inspection to agreed specifications; the site holds no finished product specification. This programme is issued on the basis of Part 5, which states the finished-product criteria explicitly — the release checks of FSQM-020 Part 4, the approved label, and the agreed pack and quantity configuration — so that the inspection is performable today. That limb is owned by D-09, the specification library, and when it exists Part 5 criteria move to the specification and this programme points at it instead. Issuing on this basis was preferred to holding: the alternative was operating with no documented inspection programme at all while a deliverable that has not started is built, and Part 5 discloses the workaround rather than concealing it. An auditor who reads Part 5 is told exactly what is being inspected against and why.\n\n2. THE 2.4.4.5 MINOR STANDS AS A QUERY, NOT A CONDITION. The consultant scored it with no evidence recorded in the assessment, and no customer and no regulation requires this site to hold retention samples at all. That question is still worth putting to RDR Global Partners, but it was never a reason to withhold this programme: whether or not the finding was well founded, the retention practice now has a stated basis, a storage condition, a period and a record in FRM-703, and the site is better placed at the next audit for having them in force.\n\nWHAT THIS PROGRAMME DOES NOT CLAIM, stated once more at issue because each is a limit an auditor is entitled to test. The site inspects; it does not analyse — no analysis of any kind is performed or commissioned, and 2.4.4.3 and 2.4.4.4 are recorded justified Not Applicable for want of a laboratory. Retention samples are not required of this site by anyone and are kept anyway. A retained sample answers for the lot it came from and no other, and because retention is organised by product rather than by batch the shelf will not hold a unit of every lot in the market. Each of those is stated in the body rather than left for a reader to infer.\n\nv2 — 2026-10-12 — The retention sample is taken and logged at packing by production staff. Approved GJM.\n\nResponsibilities only. The sample is taken where the lot is packed - the Production Lot Record already counts it among the units not packed (FSQM-021) - so the person packing takes it, puts it on the retention shelf and logs it on FRM-703, signing \"Sample taken by\". Until now the Quality Team was named for taking and logging it. The Quality Team keeps the check of the shelf against FRM-703 and the record of each sample's disposal (owner's decision, 2026-10-12). What is retained, where, for how long and how it is disposed of are unchanged.\n\nv3 - 2026-10-29 - Issued with FSQM-015. The statement that no outside laboratory is used is narrowed to acceptance testing of product: environmental swabs (FSQM-015) and the validation tests of the food safety plan (FSQM-016: water activity and pH) go to an outside laboratory accredited to ISO/IEC 17025 and listed on FRM-206 before the first sample, as Part 1's rule already requires. Nothing about how product is accepted or released changes.\n\nv4 - 2026-10-29 - Stale statements corrected: the site holds finished product specifications (FRM-704), and since v3 it commissions analyses (environmental swabs under FSQM-015, and the validation tests of FSQM-016), though it still analyses no product for acceptance. Parts 5 and 6, Records, Definitions and the governing reference now say so. No inspection changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.4.4 Product Sampling, Inspection and Analysis. 2.4.4.1 methods, responsibility and criteria; 2.4.4.2 analysis methods and laboratory accreditation; 2.4.4.5 retention samples; 2.4.4.6 records.\n2.4.4.3 and 2.4.4.4 concern an on-site laboratory. Adventure Bakery has none, and both are recorded as Not Applicable on that basis.\nFSQM-020 Product Release Program — the release decision this program's finished-product inspection feeds, and whose release checks Part 5 adopts as the finished-product criteria.\nFSQM-018 Non-Conforming Product and Equipment — where anything that fails an inspection is held and dispositioned.\nFSQM-009 Corrective and Preventive Action (CAPA) Program — where an inspection failure meets one of its Part 3 triggers.\nSOP-2.3.2 Raw and Packaging Materials — the receipt and acceptance of incoming material, which this program's Part 3 inspection serves.\nSOP-2.3.1 New Product and Specification Process — how a specification is produced. Each flavour's finished product specification is its FRM-704 entry."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'ceccac3f-b5b7-4267-b38a-c72cb36f3d0b' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "Every element of the SQF System operated at this site, and every activity by which the effectiveness of those elements is established or confirmed.\n\nIt does not restate the controls it schedules, and it does not duplicate their records. Good Manufacturing Practices are FSQM-012 and FSQM-022; sanitation is FRM-901, FRM-902 and FRM-903 with the machine SSOPs beneath them; temperature monitoring is SOP-401 and FRM-401; retention sampling is FSQM-014; product release is FSQM-020; dispatch is FSQM-036; corrective action is FSQM-009. This program supplies the method, the responsibility, the criteria and the schedule.", "purpose": "To state the methods, responsibility and criteria by which the site validates that its food safety controls achieve the results required of them, and verifies that those controls are being operated; and to hold the master verification schedule listing every verification activity, its frequency, the position responsible for it and the record that evidences it. It satisfies the Validation and Effectiveness and Verification Activities elements of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.5.1 and 2.5.2), both of which are Mandatory.", "records": "This program creates no record of its own. The record of each verification activity is the form named against it in Part 6, held and retained by the program that defines that form.\nThe schedule itself is a record, and it is Part 6 of this document. It is amended by revising this document.\nThe annual review of this program is evidenced by its revision, as it is for every program in this document set.\nRetention of the activity records: as set by each owning program; none is shorter than two years, or the shelf life of the product plus twelve months, whichever is longer, on the basis FSQM-009 Part 10 states.", "procedure": ["This program states how the site validates that its food safety controls achieve what they are meant to achieve, and how it verifies that those controls are being operated. It holds the master verification schedule required by 2.5.2.2, which is set out in Part 6.", "> Validation and verification are different questions and this program keeps them apart. Validation asks whether a control WOULD work: is the method capable of the result claimed for it. Verification asks whether it DID: was it carried out, by whom, and does the record show it. Monitoring is neither - it is the doing itself, and it lives in the programs below rather than here.", "This program schedules and verifies the controls that other programs define. It does not restate them, and it does not create a record of its own where one already exists.", "• Good Manufacturing Practices are defined by FSQM-012 and monitored under FSQM-022, whose monthly full-site inspection is recorded on FRM-913.", "• Sanitation is scheduled by FRM-901, confirmed daily on FRM-903 and verified on FRM-902, with the machine SSOP logs FRM-909 to FRM-912 beneath them.", "• Temperature monitoring is SOP-401, and its monthly review on FRM-401 is already written as the verification that the automatic monitoring worked.", "• Retention sampling is FSQM-014 and FRM-703; product release is FSQM-020 and FRM-701; dispatch is FSQM-036 and FRM-801; glass and brittle plastic is FRM-907.", "• Corrective and preventive action is FSQM-009, recorded on FRM-007.", "> Naming them rather than absorbing them is the point. An umbrella program that restates the controls beneath it creates two versions of every rule, and the day they disagree is the day the document set stops being evidence of anything. What this program adds is the method, the responsibility, the criteria and the schedule.", "> The same reasoning governs the records. Every activity on the schedule in Part 6 is recorded on the form named against it, and this program issues no general-purpose verification form of its own. A catch-all record beside a purpose-built one produces two accounts of a single activity, and is weaker evidence than either.", "Good Manufacturing Practices shall be confirmed to achieve the results required of them, and the confirmation shall be recorded.", "• The monthly site inspection on FRM-913 examines each Module 11 subsection against the Code and records what was found, not merely that a look was taken.", "• Sanitation verification on FRM-902 confirms that cleaning achieved its result rather than that cleaning was performed, which is what FRM-903 already confirms.", "• Where an inspection or a verification finds a practice that is not achieving its result, the finding is raised under FSQM-009 and the practice is changed. A finding closed without a change is a finding that was not believed.", "> HOW HYGIENE IS CONFIRMED BY MEASUREMENT. The environmental monitoring program, FSQM-015, issued 2026-10-29, swabs the production room on a four-monthly schedule for Enterobacteriaceae and Listeria species and records the results on FRM-706. Until its laboratory is chosen and its first round taken (FSQM-015, due by 2027-01-31), confirmation rests on inspection and on record review.", "> When that first round has been taken, the analytical limb of 2.5.1.1 i is met by FSQM-015. Until then this program does not claim more than inspection can support.", "Critical food safety limits shall be reviewed at least annually, and re-validated or justified against a regulatory standard whenever they change or whenever the process they control changes.", "• A limit that is re-validated shall record the evidence relied on. A limit justified by reference to a regulatory standard shall record the standard.", "• Where a limit changes, the change shall be assessed under Part 4 before it takes effect.", "> WRITTEN CONDITIONALLY, AND ON PURPOSE. The limits this Part governs are those established by the food safety plan, FSQM-016 Food Safety Plan (HACCP) - Rum Cake, issued 2026-10-29 as a limited plan. It replaces the unnumbered HACCP plan of 23 June 2026, which is archived, and identifies two critical control points:", "• CCP 1 — Baking. Hazard: survival of Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder. Critical limits: oven at least 350°F for at least 27 minutes. The June 2026 plan also set an internal product temperature of at least 180°F at the end of the bake; the product is not probed today. Monitoring: every oven load.", "• CCP 2 — Vacuum sealing in pouches. Hazard: loss of package integrity, which admits microbial contamination and ends shelf stability. Critical limits: vacuum level to the equipment specification; no visible leak, channel, wrinkle across the seal, or partial seal, and no air in the pouch; and seal width to the equipment specification. Monitoring: a visual check of every pouch as it comes off the sealer, for seal defects and for air in the pouch. At boxing, once the seal is cool, every pouch is looked at again for lost vacuum and one pouch from each lot is pull tested. A pull test is not done on a warm seal.", "> Both points are monitored and recorded by the production operator: CCP 1 on FRM-507 CCP 1 Baking Monitoring Record, and CCP 2 on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The internal product temperature at CCP 1 is not monitored, and FRM-507 records that each production day rather than leaving the column blank. The limits are now established by a controlled document, but they are not yet validated: FSQM-016 Part 9 states, with dates, the validation of the bake (including the internal temperature) and the vacuum level and seal width for this site's sealer, which are not yet confirmed.", "> The annual review and re-validation of critical limits is therefore carried on the schedule as not yet implemented rather than as a review somebody is failing to do: until the limits are validated there is nothing to re-validate. It is activated when the bake is validated and the CCP 2 specification is confirmed (FSQM-016 Part 9). The cooling steps after the bake are not critical control points (FSQM-016 Parts 7 and 8).", "> Two limits are in force today and are governed by the programs that state them, because they are real whether or not a HACCP plan names them: the refrigerator and freezer limits in SOP-401, reviewed monthly on FRM-401, and the sanitizer concentration stated in FRM-903 and the SSOPs. NEITHER IS A CRITICAL CONTROL POINT. Recording them as though they were would be the opposite error to ignoring them, and would put a CCP in the document set that no hazard analysis ever identified.", "A change to a process or a procedure shall be assessed for its effect on food safety controls BEFORE it takes effect, and the assessment shall be recorded.", "• The triggers are: a new or reformulated product; a change of process step, equipment, ingredient, supplier, packaging or label; a change to the layout of the site; and a change to who performs a monitoring or verification role.", "• The assessment records what control the change touches, whether that control remains effective, and what was altered to keep it so.", "• Where a dedicated record governs the change it is used: label changes are FRM-601 and REP-603, a new supplier is FRM-202, a new material is FRM-207, and a change arising out of a corrective action is recorded on its FRM-007.", "> Every other change that can alter whether the product is safe - a new product or recipe, a changed process step or limit, new or modified equipment that touches the product - is assessed and approved on FRM-015 under FSQM-007 Change Management Program. That program also states which changes need no record beyond the revision of the document that describes them, and how a change of people is handled.", "> The order matters more than the paperwork. A control assessed after the change it exists to control has already failed to control it - the same reasoning FSQM-036 Part 3 applies to introducing temperature-controlled transport, and FSQM-014 Part 2 to introducing analysis.", "The monitoring of Good Manufacturing Practices, of critical control points and of other food safety controls shall be verified, and the person responsible for verifying shall authorize each verified record.", "• Verification confirms that monitoring was carried out as required, that its results were within limits, and that anything outside limits was acted on.", "• The verification signature on the record IS the authorization required by 2.5.2.1. FRM-903, FRM-913, FRM-902, FRM-401, FRM-701, FRM-507 and FRM-606 each carry one, and it is not repeated anywhere else.", "• A person shall not verify their own monitoring where a second qualified person is available. Where one is not, the record shall say so.", "> That last rule is written the way FSQM-004 had to be rewritten. An absolute separation requirement made a legitimate single-operator run non-compliant, and 11.2.5.7 asks for QUALIFIED personnel rather than independent ones. A rule the site cannot always follow is worse than a weaker one it can: the first thing that happens to it is that it is ignored.", "> A verification that leaves no signature is indistinguishable from one that did not happen. That is why 2.5.2.1 names authorization separately from verification, and why the schedule names a position against every activity rather than leaving it to whoever is free.", "> CRITICAL CONTROL POINTS ARE VERIFIED ON THEIR OWN RECORDS. The production operator records the monitoring of the two critical control points in the site's HACCP plan on FRM-507 for baking and FRM-606 for vacuum sealing. Each entry carries a required verification signature and is not submitted until the reviewer has checked it against the critical limits and confirmed that every deviation has a recorded action; that signature is the authorization 2.5.2.1 requires. The review is scheduled weekly in Part 6, one activity per record. What it cannot yet confirm is stated on the forms: the internal product temperature at CCP 1, which is not monitored, and the CCP 2 vacuum level and seal width against a specification not yet confirmed for this site's machine.", "The master verification schedule is set out below. It states every verification activity, the frequency at which it is completed, the position responsible for it, and the record that evidences it.", "• Site GMP and food safety inspection — Monthly — SQF Practitioner — FRM-913", "• Review of daily sanitation and pre-operational records — Weekly — Production Supervisor — FRM-903", "• Sanitation verification — Weekly — SQF Practitioner — FRM-902", "• Temperature monitoring record review — Monthly — SQF Practitioner — FRM-401", "• Retention sample review and disposal — When a sample on the shelf passes its discard date — SQF Practitioner — that sample's own entry on FRM-703", "• Finished product release record review — Weekly — SQF Practitioner — FRM-701", "• Dispatch and vehicle loading record review — Weekly — SQF Practitioner — FRM-801", "• CCP 1 baking monitoring record review — Weekly — SQF Practitioner — FRM-507", "• CCP 2 vacuum sealing monitoring record review — Weekly — SQF Practitioner — FRM-606", "• Glass and brittle plastic register check — Monthly — Production Supervisor — FRM-907", "• Review of open and overdue corrective actions — Monthly — SQF Practitioner — FRM-009, under \"Open corrective actions\"; each CAPA itself is recorded on FRM-007 and listed on REP-007", "• Customer complaint review and trending — Monthly — SQF Practitioner — FRM-009, under \"Complaints, incidents and recalls\"; the complaints themselves are reported on FRM-002 and listed on REP-003", "• Monthly SQF update to senior site management — Monthly — SQF Practitioner — FRM-009; the update required by 2.1.2.2 and management's response to it, distinct from the annual management review above", "• Management review of the SQF System — Annually — Senior Site Management — FRM-001", "• Blackout period declaration to the certification body — Annually — Senior Site Management — FRM-006; dated from the period the declaration in force covers, not from when it was filed, and raised 90 days ahead of the next period", "• Annual review and re-validation of critical food safety limits — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting validation of the critical limits (FSQM-016 Part 9)", "• Annual review of the Validation and Verification Program — Annually — SQF Practitioner — evidenced by the revision of FSQM-017", "• Calibration of measuring and monitoring equipment — Monthly — SQF Practitioner — FRM-705", "• Preventive maintenance check of equipment and building — Monthly — SQF Practitioner — FRM-508", "• Backflow prevention device testing — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Potable water microbiological and chemical analysis — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Internal audit of the SQF System — Quarterly — SQF Practitioner — FRM-010", "• Traceability and mock recall test — Annually — SQF Practitioner — FRM-012", "• Crisis management plan review and test — Annually, before 1 June — Senior Site Management — FRM-013", "• Environmental monitoring sampling round — Every four months — SQF Practitioner — FRM-706", "• Food defense and food fraud review and test — Annually — SQF Practitioner — FRM-014", "• Allergen cleaning verification swab — Annually, one changeover clean on each machine — SQF Practitioner — FRM-916", "> The schedule is maintained in the Team Portal under Compliance, where it is the same record the reminder system reads. Adding, retiring or re-timing an activity is done there, and the list above is this program's copy of it as at the effective date of this revision. A change to the schedule is therefore a revision of this program, and the annual review in Part 10 is the occasion that catches it.", "> AN ACTIVITY MARKED NOT YET IMPLEMENTED IS SCHEDULED AND IS NOT BEING PERFORMED, because the program that governs it has not been issued. Each names the deliverable that will bring it into force, no reminder is raised for it, and no record is expected against it.", "> Listing activities the site is not yet performing is deliberate and is the harder of the two options. Omitting them would produce a schedule that looked complete and was not, and an auditor comparing it against the Code would find the gaps anyway - having also learned that the schedule does not show them. Stating them is the position that survives being read carefully.", "Verification activities that have fallen due shall be raised to the whole team within the Team Portal, labelled with the position responsible for each.", "• The prompt is raised twice each working day from the schedule. Nothing is routed to an individual: the schedule names the responsible position, and the notification carries that label.", "• A prompt is cleared for the whole team by whoever acts on it, and the clearing records who and when.", "> A NOTIFICATION IS A PROMPT, NOT A RECORD. Clearing one does not perform the activity and is not evidence that it was performed. The record is the entry on the form the notification links to. The name and time against a cleared prompt show only that somebody took the prompt, and this program does not treat them as verification.", "> The distinction is worth defending because the failure it prevents is quiet. A feed that feels like a checklist becomes one that gets ticked, and a system whose evidence is a list of dismissals has replaced the work with the reminder about the work.", "Where a verification activity finds that a control is not effective, or was not carried out, the finding shall be raised under FSQM-009 and its corrective action recorded on FRM-007.", "• The activity that found it is still recorded as completed. A verification that finds a problem has succeeded, not failed.", "> Recording the failure and the verification separately keeps both true. Marking a verification incomplete because it found something would mean the schedule showed the activity as outstanding, which would raise it again the next morning and lose the finding in the noise.", "Records of verification activities are the records named against each activity in Part 6, held and retained by the programs that define them. This program creates no record of its own.", "The SQF Practitioner shall review this program at least annually, and whenever a program it schedules is issued, amended or withdrawn. The review is evidenced by the revision of this document.", "> That is how every program in this document set evidences its annual review, and it is why this one does not carry a review form. The schedule is the part that goes stale, and it goes stale quietly: an activity keeps its place on the list long after the program that governed it changed. The annual review is also the occasion on which the not yet implemented activities are re-examined, because each becomes real the day its deliverable is issued and nothing else will announce that to this document."], "definitions": "Validation: establishing that a control is capable of achieving the result claimed for it. It asks whether the control WOULD work.\n\nVerification: confirming that a control was operated as required and that its records show it. It asks whether the control DID work.\n\nMonitoring: carrying out the control and recording the result at the time. Monitoring is neither validation nor verification, and it lives in the program that defines the control.\n\nVerification activity: one scheduled task in Part 6, with a frequency, a responsible position and a named record.\n\nNot yet implemented: the status of a scheduled activity whose governing program has not been issued. The activity is listed and is not being performed.", "responsibility": "SQF Practitioner — owns this program and the schedule. Performs or assigns each verification activity, authorizes verified records, and raises findings under FSQM-009.\nProduction Supervisor — performs the verification activities assigned to that position, and ensures monitoring is carried out so that there is something to verify.\nProduction staff — carry out the monitoring that these activities verify, and complete the records that are its evidence.\nAdmin — maintains the records and their retention.\nSenior Site Management — provides the resources the schedule requires, reviews the system under 2.1.2, and is the authority for any decision to change an activity's frequency.", "form_references": "FRM-913 GMP / Food Safety Inspection Record; FRM-903 Daily Sanitation, Pre-Operation & Release Record; FRM-902 Sanitation Verification Log; FRM-901 Master Sanitation Schedule; FRM-401 Temperature Monitoring Review; FRM-703 Retention Sample Log; FRM-701 Finished Product Release Record; FRM-801 Dispatch and Vehicle Loading Record; FRM-907 Glass & Brittle Plastic Register; FRM-007 Corrective & Preventive Action Report; FRM-002 Customer Complaint Report; FRM-001 Management Review Record; FRM-507 CCP 1 Baking Monitoring Record; FRM-606 CCP 2 Vacuum Sealing Monitoring Record; FRM-705 Calibration Directory and Check Record; FRM-508 Monthly Maintenance Check; FRM-010 Internal Audit Record; FRM-015 Change Assessment Record", "revision_history": "v17 - 2026-10-16 - The retention sample reminder is raised when a sample is due.\n\nPart 6 listed the retention sample review and disposal as weekly, evidenced by FRM-703. One FRM-703 is one sample and is submitted only when that sample leaves the shelf, so while every sample was within its period the weekly reminder could never be discharged, and the only way to clear it was to record a sample as gone that was still on the shelf. FSQM-014 asks for no weekly review: a sample is kept until thirty days after the date on its pack and its disposal is recorded on FRM-703 when it leaves. The activity is now raised when a sample on the shelf passes its discard date, links to that sample, and is discharged by recording its disposal (owner's decision, 2026-10-16). The position responsible is unchanged.\n\nv16 - 2026-10-16 - The monthly CAPA review is evidenced by the monthly SQF update.\n\nPart 6 listed the review of open and overdue corrective actions against FRM-007. FRM-007 is the report of one corrective action, so it cannot show that the month's corrective actions were reviewed, and the schedule's reminder could never be discharged - the same fault v15 corrected for the complaint review. The review is done at the monthly SQF update and recorded on FRM-009 under \"Open corrective actions\", against the CAPA log REP-007; FSQM-009 v2 says so, and the schedule line and the reminder now do too (owner's decision, 2026-10-16). Frequency and the position responsible are unchanged.\n\nv15 - 2026-10-12 - The monthly complaint review is evidenced by the monthly SQF update.\n\nPart 6 listed the customer complaint review and trending against FRM-002. FRM-002 is the report of one complaint, so it cannot show that a month's complaints were reviewed, and the schedule's reminder could never be discharged. The review is done at the monthly SQF update and recorded on FRM-009 under \"Complaints, incidents and recalls\", against the log REP-003; the schedule line and the reminder now say so (owner's decision, 2026-10-12). Frequency and the position responsible are unchanged.\n\nRev New — written 2026-09-10 against SQF Food Safety Code: Food Manufacturing, Edition 9, 2.5.1 Validation and Effectiveness and 2.5.2 Verification Activities. ISSUED 2026-09-10, approved GJM (Senior Site Management), effective 2026-09-10.\n\nWHY IT EXISTS. The gap assessment scored 2.5.1.1, 2.5.2.1 and 2.5.2.2 and no controlled document covered validation or verification as a subject. Individual programs verified themselves - FSQM-022's monthly inspection, FRM-401's monthly review - but nothing held the schedule 2.5.2.2 requires or stated the method 2.5.1.1 and 2.5.2.1 require. Both clauses are Mandatory.\n\nIT SCHEDULES RATHER THAN RESTATES. Part 1 names every program whose controls this one verifies and defers to each. An umbrella that restates the controls beneath it creates two versions of every rule, and the day they disagree the document set stops being evidence. FSQM-036 Part 7 took the same approach to unloading, pointing back at FRM-301 rather than building a second receiving form.\n\nAMENDED 2026-09-10, BEFORE ISSUE — FRM-008 WAS REDUNDANT AND HAS BEEN DELETED. This program was first drafted with a companion form: FRM-008, carrying the printed schedule and a general-purpose verification activity record. The owner questioned whether that record was doing any work, and it was not. Eleven of the thirteen active activities already record on their own form. The two that did not dissolved on inspection: no active FSQM programme in this document set records its annual review on a form - the revision is the evidence, in all eight of them - and the annual re-validation of critical food safety limits belongs with the food safety plan that establishes those limits, which does not exist, so that activity is now carried as not yet implemented alongside CCP record review for the same reason.\n\nWith the record section serving nothing, what remained was a form with a printed table and nowhere to write. 2.5.2.2 asks the PROGRAMME to have a verification schedule, so the schedule became Part 6 of this document and FRM-008 was deleted. One document instead of two, and no second copy of the schedule to keep in step. FRM-008 returns to being an unused number.\n\nThe general-purpose record was also the wrong shape on its own terms. A catch-all beside a purpose-built record produces two accounts of one activity, and invites being filled in alongside the real form rather than instead of it. Part 1 now says so in terms.\n\nTHE ANNUAL REVIEW OF THIS PROGRAM is evidenced by its revision, which is both how every other programme here does it and something the application already records in sop_document_history. The schedule reads that history to know when the review last happened, so the activity is still prompted without a form existing to carry it.\n\n\n\nSETTLED AT ISSUE — 2026-09-10:\n\n1. WHO APPROVES. Senior Site Management, GJM. This program appoints verification responsibilities across every position including the SQF Practitioner's own, so approval by the role it assigns work to would have been the appointee approving their own appointment - the same reasoning FSQM-004 records.\n\n2. THE FREQUENCIES IN PART 6 ARE THE SITE'S, FROM THIS DATE. They were seeded as proposals to give the schedule a working shape and were issued without a separate confirmation pass, which is recorded here rather than glossed: a reader should know that the cadences were adopted by issuing the document rather than derived one by one from a risk assessment. They are amended by revising this program, the schedule page is where the change is made, and the annual review in Part 10 is the occasion that re-examines them. A frequency that turns out to be wrong is a revision, not a non-conformance.\n\n3. THE ANALYTICAL LIMB OF 2.5.1.1 i IS NOT MET, AND THIS PROGRAM DOES NOT CLAIM IT. Confirming that Good Manufacturing Practices achieve their result normally rests on measurement, and this site performs no analysis at all - no laboratory, no external laboratory, no reliance on supplier certificates of analysis. Part 2 says so and rests the confirmation on inspection and record review. The environmental monitoring program for ready-to-eat product is the deliverable that changes it, and Part 2 is revised when that is issued. This is a standing limitation of the program as issued, not an open action.\n\n4. PART 3 HAS NOTHING TO BITE ON YET, for the same kind of reason. The critical limits it governs are those a food safety plan establishes, and the site has no HACCP plan under document control and no critical control points defined. The rule stands; the activity is carried on the schedule as not yet implemented; and the two limits that ARE real today are named in Part 3 together with the statement that neither is a CCP.\n\nWHAT THIS CLOSES. 2.5.2.1 and 2.5.2.2 are in force from this date. 2.5.1.1 is met in part - limb iii by Part 4, limbs i and ii as far as a site with no analysis and no food safety plan can meet them, with both gaps stated on the document. Recording that as a full closure would be closing a Mandatory clause on evidence that does not exist.\n\nREVISED 2026-09-11 — v2, approved GJM (Senior Site Management), effective 2026-09-11. PART 3 WAS WRONG ABOUT CRITICAL CONTROL POINTS, AND PART 5 CLAIMED MORE THAN THE SITE DOES.\n\nAs issued, Part 3 said the site had no critical control points defined, and item 4 of the settled block above repeats it. That came from searching the text of every controlled document, and the search never opened attached files. The site's HACCP plan is held in the document library as an attached PDF on an unnumbered reference document, and it identifies five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. The plan has no document number and no approval, so it is not under document control, and that half of the statement stood. The other half did not.\n\nTHE FIVE POINTS ARE MONITORED BUT NOT RECORDED, confirmed on 2026-09-11. That changes two Parts. Part 3 now names the five points, and states that no critical limit for them is established by a controlled document and that there is no record to review a limit against. Part 5 gains a paragraph stating that the verification of critical control point monitoring required by 2.5.2.1 is not performed, because verification confirms a record and there is none. The two schedule activities that depend on it, CCP monitoring record review and the annual review and re-validation of critical food safety limits, stay not yet implemented, and their descriptions on the schedule are corrected to say why.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. At issue 2.5.2.1 was recorded as in force. It is in force for Good Manufacturing Practices and for the other food safety controls named in Part 1, and NOT for critical control points. Unlike the analytical limb of 2.5.1.1, this is an open action rather than a standing limitation: the points are already monitored, and what is missing is the record. It closes when the food safety plan is brought under document control with a monitoring record for each point. 2.5.1.1 remains met in part, as issued.\n\nThis revision is a correction, not the annual review of the program in Part 10, although the application records it as a revision and the schedule dates the next review from it.\n\nREVISED 2026-09-11 — v3, approved GJM (Senior Site Management), effective 2026-09-11. THE v2 CORRECTION COUNTED THE CRITICAL CONTROL POINTS WRONGLY.\n\nv2 listed five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. That list was not taken from the plan's control chart, and the plan was read in full for this revision. It defines two: CCP 1, baking, and CCP 2, vacuum sealing in pouches. Sealing and sealing leak are the biological and the physical hazard of the same step, CCP 2.\n\nTHE TWO COOLING STEPS ARE NOT CRITICAL CONTROL POINTS, although one table in the plan says they are. The plan's hazard analysis marks temperature control on the racks, and cooling to room temperature before covering, as CCP 1 and calls them kill steps. Its flow diagram marks only baking and vacuum sealing, and its control chart sets critical limits and monitoring only for those two. Cooling destroys nothing, and a step with no critical limit cannot be operated as a critical control point, so this program follows the diagram and the control chart and leaves the discrepancy to be corrected in the plan.\n\nv2 ALSO SAID THE PLAN HAS NO APPROVAL. Its cover names an approver and a version. It carries no document number, it is not under document control, and its approval page is unsigned, so the conclusion stood: no critical limit is established by a controlled document. Part 3 now says so precisely.\n\nPART 3 NOW LISTS BOTH POINTS with the hazard, critical limits and monitoring the plan states for each, and records the limits the plan has not settled: the vacuum level and seal width, given only as the equipment specification, and the validation of the bake, for which the plan recommends a lethality study rather than relying on one. Part 5 and the two schedule descriptions now say two points, not five. Nothing else changes: 2.5.2.1 remains in force for Good Manufacturing Practices and the other controls and not for critical control points, as v2 recorded, and both schedule activities stay not yet implemented.\n\nREVISED 2026-09-11 — v4, approved GJM (Senior Site Management), effective 2026-09-11. THE CRITICAL CONTROL POINTS ARE NOW RECORDED.\n\nFRM-507 CCP 1 Baking Monitoring Record and FRM-606 CCP 2 Vacuum Sealing Monitoring Record were issued on the same date. The production operator records every oven load and every sealing check on them, and each entry carries a required verification signature, so the monitoring that v2 and v3 recorded as unrecorded now has a record, and the verification 2.5.2.1 requires can be performed and authorized.\n\nPart 3 now names the two forms and states the one limit still not monitored, the internal product temperature at CCP 1, which is not probed. Part 5's paragraph on critical control points describes the verification rather than its absence, and its list of records that carry a verification signature adds FRM-507 and FRM-606. Part 6 replaces the single not-yet-implemented CCP monitoring record review with two weekly activities, one per record, first due 18 September 2026. Each is in force from this date and raises its reminder like every other active activity.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. 2.5.2.1 is now in force for critical control points as well as for Good Manufacturing Practices and the other controls, with two limitations stated on the forms: the internal product temperature at CCP 1 is not monitored, so it cannot be verified, and the CCP 2 vacuum level and seal width are verified against an equipment specification not yet confirmed for this site's machine. The annual review and re-validation of critical food safety limits stays not yet implemented, because the limits are not yet established by a controlled document or validated. 2.5.1.1 remains met in part.\n\nSOP-505 is revised on the same date so that oven temperature and bake time are recorded on FRM-507 rather than on the batch sheet, which never held them.\n\nv5 — 2026-09-16 — The annual compressed air quality analysis retired from the schedule, under D-32.\n\nPart 6 carried \"Compressed air quality analysis — Annually — NOT YET IMPLEMENTED — awaiting D-32 Compressed Air and Gases\". D-32 is answered. The site's compressed air operates pneumatic equipment, where it contacts no food and no food-contact surface, and its one other use — clearing film scraps from the flow wrapper — is now performed only with the film unloaded and the table cleared, under SOP-605 v2, and is carried in FSQM-013 as a category C alternative control. 11.5.5.2's testing obligation is scoped to air that contacts food or food-contact surfaces; with that use controlled there is no air in scope to test, and an annual analysis would be a record of nothing.\n\nThe activity is RETIRED on the schedule rather than deleted, which is how this program treats an activity that stops applying, and the line is removed from this Part. The obligation returns the moment compressed air is put into contact with product or a food-contact surface — a new machine, a blow-off drying step, or the flow wrapper being cleaned with film loaded. That is a change the annual review in Part 7 is meant to catch, and it re-opens the activity rather than waiting for the review after it.\n\nv6 — 2026-09-16 — The blackout period declaration added to the schedule, under D-05.\n\nSQF 2.1.1.8 requires senior site management to designate defined blackout periods and to submit them, with their justification, to the certification body at least one month before the sixty-day unannounced re-certification window opens. FRM-006 Blackout Period Declaration is issued with this revision as the record of that designation, and the activity joins Part 6.\n\nIT IS DATED DIFFERENTLY FROM EVERY OTHER ACTIVITY ON THIS SCHEDULE, AND DELIBERATELY SO. The rest are \"do it again a period after the last time you did it\". A blackout declaration states the period it covers, so filing it early or late says nothing about when it expires. Anchored on the filing date, a declaration signed in October for the following calendar year would come due the following October — ten months after the site was already covered — and one signed late would push its own expiry out and let the site run uncovered without the schedule noticing. It is therefore dated from the last day the declaration in force covers, and raised ninety days before the next period begins: enough notice to agree the dates, sign them and send them.\n\nNO DECLARATION HAS BEEN FILED YET, so the activity will be raised as never recorded at the next run of the reminder job. That is the intended prompt and not a fault — 2.1.1.8 is open until senior site management files one.\n\nTHE SUBMISSION LIMB REMAINS OPEN, and it is not a matter of scheduling. No certification body is engaged and no certificate is held, so there is nothing to submit to and no sixty-day window to count back from. FRM-006 Section 5 stays blank until there is one, and says so on its face.\n\nv7 — 2026-09-16 — The monthly SQF update added to the schedule, under D-06.\n\nSQF 2.1.2.2 requires the SQF Practitioner to update senior site management at least monthly on matters affecting the SQF System, and for the update and management's response to be documented. FRM-009 Monthly SQF Update Record is issued with this revision as that record, governed by FSQM-005, and the activity joins Part 6.\n\nIT WAS ASSESSED COMPLIANT AT THE GAP ASSESSMENT AND WAS NOT. The management review procedure then in draft said the monthly update was recorded in a \"Flash Report\", and no such report exists anywhere in this system. The rewritten FSQM-005 first replaced that with minutes \"retained with the management review records\", which named no form and nothing to prompt it — the same weakness one level less obvious, and caught on review before issue. FRM-009 is the answer to it: a short record, on the schedule, that prompts itself.\n\nTHE ACTIVITY WILL READ AS NEVER RECORDED until the first entry is submitted. That is the prompt working rather than a fault, and it is honest: the monthly meeting has been happening without a retained record for as long as the site has been holding it.\n\nv8 — 2026-09-21 — Calibration brought into force under D-28. FSQM-030 Calibration Program and FRM-705 Calibration Directory and Check Record are issued, so the calibration activity in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-705. It was carried as annual while no program existed; FSQM-030 sets it monthly, one session covering every device on the directory. First due 2026-10-21, a month after issue, so the 25 lb certified test weight can be bought before the first check. Nothing else in the schedule changes.\n\nv9 — 2026-09-21 — Preventive maintenance check added to Part 6 at the owner's request, so the monthly FRM-508 check is prompted by the reminder system like the other monthly activities. Carried as NOT YET IMPLEMENTED until FSQM-029 and FRM-508 are issued under D-26, when it becomes active against FRM-508. Nothing else in the schedule changes.\n\nv10 — 2026-09-21 — Preventive maintenance brought into force under D-26. FSQM-029 Preventive Maintenance Program, FRM-508 Monthly Maintenance Check and FRM-509 Maintenance and Repair Record are issued, so the preventive maintenance check in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-508. First due 2026-10-21, a month after issue. Nothing else in the schedule changes.\n\nv11 — 2026-10-01 — Internal audit brought into force under D-19. FSQM-038 Internal Audit Program and FRM-010 Internal Audit Record are issued, so the internal audit in Part 6 moves from NOT YET IMPLEMENTED to active: quarterly, evidenced by FRM-010. The SQF Practitioner keeps the audit plan on schedule; the audits themselves are carried out by the Internal Auditor appointed under FSQM-038. First raised 2026-12-01 for the Q4 2026 audit. Nothing else in the schedule changes.\n\nv12 — 2026-10-05 — Part 4 revised under D-04. FSQM-007 Change Management Program and FRM-015 Change Assessment Record are issued, so Part 4 no longer says there is no general change-assessment record: it names them, and adds FRM-202 and FRM-207 to the dedicated records. The rule itself - assess before the change takes effect - is unchanged, and so is the schedule.\n\nv13 — 2026-10-07 — Recall and crisis brought into force under D-21. FSQM-023 Product Withdrawal and Recall Program and FSQM-024 Crisis Management Plan are issued with their records, and FSQM-021 Product Identification and Traceability Program was issued on 2026-10-06. In Part 6 the traceability and mock recall test moves from NOT YET IMPLEMENTED to active: yearly, evidenced by FRM-012, first due 2026-12-31. One activity is added: the crisis management plan review and test, yearly before 1 June, Senior Site Management, evidenced by FRM-013, first due 2027-05-31. Nothing else in the schedule changes.\n\nv14 — 2026-10-07 — CCP 2 monitoring stated as it is performed. Management's decision: every pouch is looked at as it comes off the sealer, for seal defects and for air in the pouch; at boxing, once the seal is cool, every pouch is looked at again and one pouch from each lot is pull tested. The June 2026 plan's hourly pull test at the sealer is withdrawn - a warm seal can be pulled open by the test itself - and so is its gauge check on every cycle, which was not being performed. Recorded on FRM-606 v2. The record, the weekly review and the schedule are unchanged.\n\nv18 — 2026-10-29 — The food safety plan named. FSQM-016 Food Safety Plan (HACCP) - Rum Cake was issued on 2026-10-29 as a limited plan and the unnumbered June 2026 plan was archived, so Part 1 now names FSQM-016 in place of it. CCP 1 is stated as FSQM-016 states it. The limits are now under document control but not yet validated; the re-validation activity stays not yet implemented, now awaiting FSQM-016 Part 9 rather than D-14. The note about the June plan's cooling steps is replaced by a reference to FSQM-016 Parts 7 and 8. The records, the weekly reviews and the rest of the schedule are unchanged.\n\nv19 — 2026-10-29 — The environmental monitoring sampling round added to the schedule, with FSQM-015's issue: every four months, SQF Practitioner, evidenced by FRM-706, first due 2027-01-31. Nothing else in the schedule changes.\n\nv20 — 2026-10-29 — The yearly food defense and food fraud review and test added to the schedule, with the issue of FSQM-025 and FSQM-026: annually, SQF Practitioner, evidenced by FRM-014, first due 2027-01-31. Nothing else in the schedule changes.\n\nv21 — 2026-10-29 — The yearly allergen cleaning verification swab added to the schedule, with the issue of FSQM-027: one changeover clean on each machine, swabbed with the allergen test kit, SQF Practitioner, evidenced by FRM-916, first due 2027-01-31 (when the validation swabs are due). Nothing else in the schedule changes.\n\nv22 - 2026-10-29 - Part 2 cites FSQM-015 Environmental Monitoring, issued 2026-10-29, as this Part said it would when that program was issued. Nothing else changes. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9.\n2.5.1 Validation and Effectiveness (MANDATORY). 2.5.1.1 requires documented and implemented methods, responsibility and criteria for ensuring the effectiveness of all applicable elements of the SQF System, validating that (i) Good Manufacturing Practices achieve the required results, (ii) critical food safety limits are reviewed annually and re-validated or justified when changes occur, and (iii) changes to processes or procedures are assessed for continued control. Parts 2, 3 and 4 respectively.\n2.5.2 Verification Activities (MANDATORY). 2.5.2.1 requires documented and implemented methods, responsibility and criteria for verifying the monitoring of GMPs, critical control points and other food safety controls, and requires that the personnel responsible for verifying monitoring authorize each verified record — Part 5. 2.5.2.2 requires a verification schedule stating the activities, their frequency and the person responsible, and that records of verification are maintained — Part 6 is the schedule, and Part 9 states where the records are held.\n2.5.3 Corrective and Preventative Action, and FSQM-009 — where a failed verification goes. This program routes to it and does not restate it.\n2.5.4.3 Regular inspections of site and equipment, and FSQM-022 — the monthly Module 11 inspection this program schedules and relies on, but does not define.\n2.1.2 Management Review — the annual review this program schedules on FRM-001."}$jx$::jsonb,
       revision = 'v22', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '89390225-eda9-46d9-8c84-6963652eae08' and status = 'active' and revision = 'v21';
update public.sop_documents set content = $jx${"scope": "Every dispatch of finished product from the site, all of which leave by collection, and the unloading of incoming material at receipt.\n\nIt does not cover the release decision that must precede any dispatch, which is FSQM-020 Product Release Program; the incoming inspection itself, which is recorded on FRM-301; the temperature-controlled storage of product on site, which is SOP-401; or the disposition of anything found unfit, which is FSQM-018.", "purpose": "This program states how finished product is loaded, transported and unloaded so that its storage conditions are maintained, cross-contamination is prevented and its exposure is minimised. It records which of the requirements of 11.6.5 apply to this site and which do not, and why. It satisfies the Loading, Transport and Unloading element of the SQF Food Safety Code: Food Manufacturing, Edition 9 (11.6.5).", "records": "FRM-801 Dispatch and Vehicle Loading Record — one record per vehicle-load: the vehicle check, the loading and weather confirmations, any seal identifier, the collecting carrier and the batches loaded.\nFRM-701 Finished Product Release Record — the release that must precede every collection.\nFRM-301 Incoming Material Receiving & Inspection Log — the vehicle and material inspection at receipt.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where a load or a delivery is refused or held.\nCarrier and customer notice — the sent copy of the notice given under Part 1, retained as correspondence. No acknowledgement is required or recorded.\nThere are no refrigerated transport records, because no product is carried under temperature control — see Part 3.\nRetention: two years, or the shelf life of the product plus twelve months, whichever is longer, on the same basis as FSQM-009 Part 10.", "procedure": ["Finished product leaves this site by collection, and by no other route. A carrier the customer arranges collects from the site, and responsibility for the product passes to the customer on collection.", "> This is the model FSQM-020 records. The site operates no delivery fleet, engages no carriers of its own, and uses no off-site or contract warehouse. Stating it here rather than leaving it implied is what makes the rest of this program readable: several requirements of 11.6.5 concern a journey this site does not make.", "> What the site controls is the vehicle and the loading; what it does not control is the journey after collection. That is not a gap to be apologised for. 11.6.5.2 governs vehicles used to transport food FROM the site, which is precisely the collecting vehicle, so the check in Part 4 is not an edge case for an unusual dispatch. It is the whole of this site's transport control, applied to every load that leaves.", "• Before a customer's first collection, and again whenever the carrier changes or these requirements change, the customer or the carrier shall be told the product's storage requirement, which is ambient, and the condition the vehicle must be in to be loaded. The notice sent shall be retained.", "> Telling them in advance is the difference between a standard and an argument on the dock, and it is the site's only opportunity to influence a journey it does not control.", "> This notice is the site's own control and is not required by 11.6.5, which asks for practices that maintain the product's storage conditions and prevent cross-contamination and says nothing about notifying a carrier. It is kept because it is what makes the check in Part 4 workable: a driver who has been told what is expected is not being ambushed at the dock, and the person who would otherwise have that argument is whoever is on the floor. No acknowledgement is required and none is tracked. The sent notice is the record.", "No dispatch shall leave the site before the product on it has been released under FSQM-020.", "> FSQM-020 already forbids product being made available for collection before release, and repeating it here is deliberate: loading is the moment at which an unreleased pallet is most easily taken, and once the vehicle has gone a release recorded afterwards records nothing.", "Every finished product made by this site ships ambient. No product is carried under chilled or frozen conditions, for any customer.", "> Confirmed by the owner on 2026-09-10. Three requirements of 11.6.5 govern refrigerated transport and on this determination they do not arise, and are recorded Not Applicable: 11.6.5.5, that refrigerated units maintain the product at its required temperature; 11.6.5.6, that the unit is operational at all times and checked; and 11.6.5.7, that the vehicle's refrigeration temperature is checked on arrival before the doors are opened.", "> This determination says nothing about refrigeration on the site. A freezer remains in service under SOP-401, and the storage of product under temperature control is governed by 11.6.2 rather than by this program. What is determined here is narrow and is only about carriage: nothing leaves this site under temperature control.", "> Ambient is a specified condition, not the absence of one. 11.6.5.1 requires practices that maintain the storage conditions of the food, and product carried ambient must still be protected from heat, damp, direct sun and contamination. Treating ambient as nothing to control is the usual way this requirement is failed, and Parts 5 and 6 exist because of it.", "> What would reverse this: if any product requiring chilled or frozen carriage is introduced, whether a new product, a reformulation, or a customer requiring temperature-controlled delivery of an existing one, this program shall be revised and the controls of 11.6.5.5 to .7 implemented BEFORE that product first ships. The revision comes first. A control that arrives after the event it exists to control is not a control.", "No vehicle shall be loaded until it has been checked and found fit to carry food, and the check shall be recorded on FRM-801.", "• The load space shall be clean, dry and free of odour, free of pest activity and of residue from a previous load, and sound enough to keep weather out.", "• Where the previous load is known to have been a non-food material, the vehicle shall not be loaded.", "• A vehicle that fails the check shall not be loaded. The refusal and its reason shall be recorded, and the collection shall not proceed until a fit vehicle is provided.", "> The vehicle belongs to the customer or to a carrier the customer arranges, and it is checked anyway. 11.6.5.2 does not distinguish by who owns the vehicle, and the reason is plain once stated: if a vehicle arrives dirty or carrying an odour it is this site's product that would be affected, and this site's control that failed. Responsibility passing on collection does not reach backwards to the moment of loading.", "Product shall be transferred from the building into the vehicle without being exposed to weather or contamination, and the load shall be secured so that packaging is not damaged.", "• Palletised loads are moved by forklift or pallet jack from the building to the vehicle across an outdoor concrete area, and are therefore briefly exposed to the outdoor environment. There is no loading dock.", "• Pallets shall be wrapped before they leave the building.", "• Product shall not be loaded in rain, snow or driving wind unless the load is covered for the crossing.", "• The concrete loading area shall be kept clean and free of standing water, and no pallet shall be set down on wet or soiled ground.", "• The crossing shall be as direct and as brief as the equipment allows. Pallets shall not be staged outdoors to wait for a vehicle.", "• Product shall not be placed directly on the ground or on an unclean surface at any point.", "> There is no dock, so 11.6.5.4 is met by practice rather than by structure, and this Part says so plainly. An earlier draft of this program stated that product never crossed open ground. That was a misreading of what the site had described and it was wrong: bulk loads cross a concrete parking area. A document asserting that product is never exposed, read by an auditor who then watches a pallet cross a car park in the rain, would cost more credibility than the exposure itself ever could.", "> What the weather threatens here is the packaging rather than the food. Every unit is vacuum sealed inside its box before it is cased and palletised, so a brief crossing does not reach the product. Wet cartons are the real risk: they lose strength, they can support mould, and they carry soil into the vehicle and on to the customer. The rules above are aimed at the outer packaging, which is the thing actually at risk.", "• The load shall be stacked and restrained so that packaging is not crushed, punctured or abraded.", "The load compartment shall be closed and secured before the vehicle leaves the site.", "• Where the vehicle has a lock, the compartment shall be locked. Where it has a latch only, the compartment shall be latched and the driver shall confirm it is closed.", "• Where a customer or a carrier requires a seal, one shall be applied and its number recorded on FRM-801.", "• The confirmation shall be recorded on FRM-801 for every dispatch.", "> 11.6.5.3 requires that vehicles be secured from tampering using seals or other agreed-upon and acceptable devices or systems. It asks for the vehicle to be SECURED, and a lock is a device that secures it. A seal secures nothing; it evidences afterwards that somebody opened the load. The clause contemplates both, and this site uses the one that fits how its product actually leaves.", "> A seal would not fit. Every dispatch is a collection and a collecting vehicle is commonly on a multi-drop route, so a seal applied here has to be cut at the next stop. Requiring one would be writing a rule that cannot be followed, and a rule the site cannot follow is worse than a lighter one it can: the first thing that happens to it is that it is ignored, and the second is that everything written beside it is trusted a little less.", "> This is a risk-based choice and is recorded as one rather than left to look like an omission. The product is ambient and shelf stable, collected locally in small quantities, and is not the kind of load that attracts interference. The site does not claim that the product's own packaging satisfies this requirement, because 11.6.5.3 is about the vehicle - but a unit vacuum sealed inside a taped box on a wrapped pallet is a further barrier, and it is part of why the control at the vehicle need not be heavy.", "> What would change it: the food defence threat assessment is the document that formally tests this judgement. FSQM-025 Food Defense Plan, issued 2026-10-29, found no threat this Part does not answer, and the rule stands. If it identifies a threat this Part does not answer, this Part is revised. The annual review is the other occasion on which that should be asked.", "Incoming loads shall be unloaded promptly and without unnecessary exposure, and the vehicle and the material shall be inspected at receipt as required by FRM-301.", "> FRM-301 already records the condition of the delivering vehicle at receipt, so this program does not create a second route for the same check. Anything found unfit is held under FSQM-018.", "Records are retained as set out in the Records section of this program.", "The SQF Practitioner shall review this program at least annually, and whenever the products shipped, the collection arrangements or the loading area change.", "> The determination in Part 3 is the part most likely to go stale, because it will be a new product or a new customer requirement that reverses it, and neither of those announces itself to this document."], "definitions": "Dispatch: one vehicle-load leaving the site. A dispatch may carry several batches; it is one dispatch.\n\nCollection: the only way finished product leaves this site. A carrier the customer arranges collects from the site, and responsibility for the product passes to the customer on collection.\n\nAmbient: the storage condition of a product that requires no chilling or freezing. It is a specified condition and not the absence of one - product held ambient must still be protected from heat, damp, direct sun and contamination.\n\nVehicle check: the examination of a collecting vehicle before it is loaded, to establish that it is fit to carry food.", "not_applicable": [{"clause": "11.6.5.5", "reason": "Every finished product ships ambient; nothing is carried under temperature control."}, {"clause": "11.6.5.6", "reason": "Every finished product ships ambient; nothing is carried under temperature control."}, {"clause": "11.6.5.7", "reason": "Every finished product ships ambient; nothing is carried under temperature control."}], "responsibility": "SQF Practitioner — owns this program. Decides release under FSQM-020 before any dispatch, and may stop a dispatch. Reviews the dispatch records.\nProduction Supervisor — ensures the vehicle check is performed before loading and that a vehicle that fails it is not loaded.\nProduction staff — carry out the vehicle check and the loading, and complete FRM-801.\nAdmin — arranges carriage and gives the carrier or the collecting customer the site's loading requirements.\nSenior Site Management — provides the resources loading and dispatch require, and is notified where a dispatch is stopped.", "form_references": "FRM-801 Dispatch and Vehicle Loading Record; FRM-701 Finished Product Release Record; FRM-301 Incoming Material Receiving & Inspection Log; FRM-702 Non-Conforming Material Hold & Tagging Record", "revision_history": "Rev New — written 2026-09-10 against SQF Food Safety Code: Food Manufacturing, Edition 9, 11.6.5 Loading, Transport, and Unloading. ISSUED 2026-09-10, approved GJM, effective 2026-09-10.\n\nWHY IT EXISTS. The gap assessment scored eight findings across 11.6.5 and no controlled document covered loading, transport or unloading at all. Before this, nothing in the document set cited 11.6.5.\n\nTHE AMBIENT DETERMINATION. The owner confirmed on 2026-09-10 that every finished product ships ambient, which records 11.6.5.5, .6 and .7 Not Applicable and removes task 35.6 from the deliverable. It is written into Part 3 rather than filed separately, so that a reader looking for 11.6.5 finds the determination in the document that governs the subject — the mechanism FSQM-014 used for 2.4.4.3 and .4.\n\nPart 3 is written to prevent two wrong inferences. It does not say the site has no refrigeration: a freezer remains in service under SOP-401 and refrigerated storage is 11.6.2, which D-34 closed. And it does not say ambient is the absence of a condition: 11.6.5.1 requires the storage conditions of the food to be maintained, so product carried ambient must still be protected from heat, damp and sun. The reversal trigger is stated in the same terms FSQM-014 Part 2 uses for introducing analysis — the programme is revised before the first such product ships, not after.\n\nTHE VACUUM SEAL AND THE VEHICLE SEAL ARE DIFFERENT QUESTIONS. Product is vacuum sealed, boxed as a single serving and closed with a clear tape disc. The vacuum pack is a genuine tamper-evident barrier and Part 6 says so. But 11.6.5.3 is about securing the VEHICLE, and recording the pack's integrity as though it satisfied the requirement would close it on evidence that does not address it. The two are stated separately, and the vehicle question is answered in Part 6 by a lock rather than a seal.\n\nEVERY DISPATCH IS A COLLECTION, AND THE FIRST DRAFT GOT THAT WRONG. It described three dispatch modes taken from the FRM-701 seed file. FRM-701 was amended twice after seeding and no longer carries a Destination field at all, and FSQM-020 - active since 2026-09-04 - records that the site uses no off-site or contract warehouse and that finished product is collected by a carrier the customer arranges, responsibility passing on collection. Describing a mode the site does not operate would have re-added a limb FSQM-020 deliberately removed. Corrected before seeding, and caught by a guard that checked the live document rather than trusting the file it had been seeded from.\n\nThe correction sharpens Part 4 rather than weakening it. Because every load leaves in a vehicle the site does not own, the vehicle check is not an edge case for an unusual dispatch - it is the whole of this site's transport control. 11.6.5.2 governs vehicles transporting food FROM the site without regard to who owns them, and responsibility passing on collection does not reach backwards to the moment of loading.\n\nSETTLED BEFORE ISSUE — the three open items, answered by the owner on 2026-09-10:\n\n1. VEHICLE SECURITY IS ANSWERED BY A LOCK, NOT A SEAL. See the amendment recorded below. Part 6 states a control the site can operate on every load, so 11.6.5.3 is met on issue rather than stated as a requirement the site does not meet.\n\n2. WRAPPING AND THE ADVERSE-WEATHER RULE ARE CURRENT PRACTICE. Part 5 records what the site already does and introduces nothing new to the floor. Whether a physical fix is worth making, such as a canopy over the crossing, remains a judgement for the site and is not a condition of this program.\n\n3. THE COLLECTING VEHICLE IS NOT CHECKED TODAY. Part 4 is therefore a new requirement on the floor from the effective date rather than a description of existing practice, and this is recorded rather than glossed. The gap assessment already scored 11.6.5.2 as not met, and a program written as though the check had always happened would contradict the finding it exists to close. The production staff who will perform it were briefed before issue. The customers and carriers whose vehicles it may turn away are told by the notice Admin sends under Part 1, and the site has accepted that the first collections after the effective date may be checked before that notice has reached everyone.\n\nTHE PART 1 NOTICE IS THE SITE'S OWN CONTROL, NOT A CLAUSE REQUIREMENT. Nothing in 11.6.5 requires a carrier to be told anything; 11.6.5.1 asks for practices designed to maintain storage conditions and prevent cross-contamination. The notice is kept because it makes the Part 4 check workable. It was first written to be given before every collection, which for a customer collecting weekly is a rule nobody would keep and — with no acknowledgement tracked — one that could not be evidenced either. It is now given before a customer's first collection and again when the carrier or the requirement changes, and the sent copy is retained. Not tracking acceptance is the owner's decision of 2026-09-10.\n\nAMENDED 2026-09-10, BEFORE ISSUE — PART 5 ASSERTED SOMETHING THAT IS NOT TRUE. It said product does not cross open ground between the building and the vehicle. The owner had said the product is not transported across open ground and that was read as meaning it is never outdoors; in fact bulk loads are palletised and crossed over a concrete parking area by forklift or pallet jack. The claim was corrected before this document was ever applied.\n\nIt is recorded rather than quietly fixed because the correction is instructive. The strongest thing a programme can do is describe what actually happens; the weakest is to describe what would be convenient. An auditor who reads that product is never exposed, and then watches a pallet cross a car park in the rain, has been given a reason to doubt every other statement in the document. Stating the exposure and controlling it is the stronger position, and it is also the true one.\n\nAMENDED 2026-09-10, BEFORE ISSUE — A LOCK, NOT A SEAL. Part 6 first required a tamper-evident method and recorded the vehicle question as unanswered. That over-read the clause. 11.6.5.3 asks that vehicles be SECURED from tampering using seals or other agreed and acceptable devices or systems; a lock is such a device, while a seal secures nothing and only evidences afterwards that the load was opened.\n\nA seal also does not fit how product leaves here. Every dispatch is a collection and a collecting vehicle is commonly on a multi-drop route, so a seal applied at this dock has to be cut at the next stop. Requiring one would have been a rule that cannot be followed — the same defect as the absolute pre-operational separation rule that FSQM-004 had to have removed, and the owner identified this one too.\n\nThe Part now requires the load compartment to be closed and secured before the vehicle leaves, locked where there is a lock and latched with the driver confirming where there is not, with a seal only where a customer or carrier requires one. It is one tick on FRM-801.\n\nThe reasoning is written into the Part rather than left implicit, because the defence of a light control is the argument behind it: SQF is risk-based, and ambient shelf-stable product collected locally in small quantities is not a tampering target. The Part also records what would change the judgement — the food defence threat assessment, which has not been done — so the choice can be revisited rather than settling by silence. It does not claim the product's own packaging satisfies 11.6.5.3, which is about the vehicle; the vacuum pack is recorded as a further barrier and as part of why the vehicle-level control need not be heavy.\n\nv2 - 2026-10-29 - The food defense threat assessment named here has been done: FSQM-025 was issued on 2026-10-29 and leaves the lock-or-latch rule as it is. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 11.6.5 Loading, Transport, and Unloading. 11.6.5.1 documented practices maintaining storage conditions and preventing cross-contamination; 11.6.5.2 vehicles fit to carry food; 11.6.5.3 vehicles secured from tampering; 11.6.5.4 loading docks designed to protect product; 11.6.5.8 unloading practices minimising exposure.\n11.6.5.5, 11.6.5.6 and 11.6.5.7 govern refrigerated transport. No product of this site is carried under temperature control, and all three are recorded Not Applicable on that basis — see Part 3.\n11.6.5.1 also reaches the transport itself. Every dispatch from this site is a collection and responsibility passes to the customer at that point, so the practices this site can document and implement are those of loading, of the condition of the vehicle it loads, and of what it tells the carrier beforehand. That limb is met by Parts 1, 4, 5 and 6 rather than by controls over a journey the site does not make.\n11.6.2 Temperature-Controlled Storage, and SOP-401 — the storage of product under temperature control, which this program does not cover and does not contradict.\nFSQM-020 Product Release Program — the release that must precede every collection, and the document that records the collection model.\nFSQM-018 Non-Conforming Product and Equipment — where a refused load or delivery is held."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '7e7d7f8b-af7a-4433-b941-93615e47ccd6' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"scope": "The production floor of units 415 and 425, and the movement of product across it from the receipt of ingredients at the weighing station to its transfer, packaged and coded, to warehouse storage. It covers all three configurations of the three-day rotation and issues one sheet for each.\n\nDELIBERATELY OUT OF SCOPE, and not to be read as omissions:\n\nPersonnel flow, hand-wash points and allergen segregation. This drawing answers two questions — where does equipment stand, and where does product go. Personnel movement is a different question with a different audience and a different review cycle, and drawing three overlays on one sheet makes all three harder to read. Where personnel flow across the raw / high-care boundary needs to be controlled, that is a matter for the GMP programme, and a personnel flow drawing is the right home for it if one is later required.\n\nThe process itself, which is governed by the relevant SOPs.\n\nThe food safety plan and its hazard analysis, and the flow diagram required by 2.4.3.6 — which this drawing is not. See the governing reference.", "purpose": "This document is the controlled drawing of the production floor at 415 and 425 Specialty Pt. It records where equipment stands, how the floor is divided into hygiene zones, and the route finished product takes across it. It exists so that the zoning the site works to is written down and can be pointed at, rather than being carried in people's heads.", "records": "No records are generated by this document.\n\nThe document itself is the record: four files are held as attachments to this entry — Sheet 1 (Day 1), Sheet 2 (Day 2) and Sheet 3 (Day 3) as PDF, and the editable draw.io master from which all three sheets are exported. The master is in the Reference Documents tab of this record and is edited at app.diagrams.net; all three sheets are re-exported from it and all four attachments replaced together whenever it changes.\n\nSuperseded revisions are retained by the sop_document_history trigger, which snapshots the row whenever a watched field changes on a published document.", "procedure": ["This drawing is issued as three sheets, one per day of the rotation, and all three sheets are part of the same document at the same revision.", "> Issuing one sheet would misrepresent the floor. The equipment in the room is different on each of the three days, so a single drawing would have to show either a configuration that exists a third of the time or a composite that exists never.", "> Sheet 1 carries steps 1 to 5 and the depositor. Sheet 2 carries steps 6 and 7 and the dunk station. Sheet 3 carries steps 8 to 10, the sealed product hold, the lot code printer and the route out to warehouse storage. The sheet number and the day are printed on each.", "The floor is divided into six hygiene zones, and the kill step is the oven.", "• NON-PRODUCTION — offices and reception.", "• PACKAGING MATERIALS STORAGE.", "• RAW / PRE-BAKE [LOW RISK] — ingredients, and on Day 1 weighing, mixing and depositing.", "• BAKE [KILL STEP] — the two ovens.", "• COOLING [HIGH CARE] — the post-bake racks on the west wall.", "• HIGH CARE — dunking, sealing, packaging, labelling and lot coding.", "> Everything upstream of the oven is low risk and everything downstream of it is high care. That single division is what the zoning is for, and it is the thing an auditor will look for first.", "> The premises these zones divide are governed by FSQM-012.", "THE DUNK BAY CHANGES HYGIENE STATUS BETWEEN DAY 1 AND DAY 2. It holds raw batter on Day 1 and post-bake product on Day 2.", "> This is the consequence of the rotation and it is the most important thing on the drawing. The same floor area is low risk on one day and high care on the next, so what separates them is not a wall but the changeover clean performed between Day 1 and Day 2.", "> That places weight on the changeover being performed and recorded. A zoning that depends on a clean is only as good as the record that the clean happened.", "Day 2 and Day 3 are zoned identically.", "> Nothing on Day 3 returns the area to raw use, so its hygiene status does not change between the two days and the zoning does not depend on anything done between them. By Day 3 every unit is sealed, so no product is exposed on that day.", "Sealed product is held overnight between Day 2 and Day 3, in the position the sealing unit occupies on Day 2.", "> The sealing unit is moved at the end of Day 2 and the sealed product is held in its place. That is why the hold appears on Sheet 3 only, and why Sheet 2's product route ends at the sealer.", "The weighing station is in the room on Day 1 only.", "> It is removed after Day 1, so Sheets 2 and 3 do not show it, and on those sheets the RAW / PRE-BAKE zone is the bottom strip holding the ingredients.", "This drawing is not the flow diagram required by 2.4.3.6 and shall not be offered as one. See the governing reference.", "The drawing is to scale, and the scale, its basis and its tolerance are printed on every sheet.", "> The scale was derived from a dimension printed on the original architectural plan: two equal bays spanning 49.0 pixels are labelled 11 feet 8 inches, which gives 4.2 pixels per foot. A second reading agrees — at that scale the reception rooms compute to about 122 square feet against a printed label of about 125.", "> The tolerance is about three percent, which on this building is around two feet. That is immaterial for judging which zone a machine stands in, which is what this drawing is for. It is not adequate for construction, and every sheet is marked NOT FOR CONSTRUCTION accordingly.", "The overall building measures 75.8 feet by 67.1 feet, about 5,090 square feet, divided between the two units by a demising wall at the midpoint.", "The editable master and all three issued sheets are held as attachments to this record.", "> The master is a draw.io file. A drawing that can only be reissued by redrawing it is not a controlled drawing, so the master travels with the PDFs. It is attached to this record in the Reference Documents tab as a .drawio file, and is opened and edited at app.diagrams.net (File, Open From, Device) with nothing to install. After any change to the master, re-export ALL THREE sheets and replace all four attachments together, so the record never holds sheets that disagree with the drawing they came from.", "The SQF Practitioner shall review this drawing at least annually, and before that whenever equipment is moved, added or removed, whenever the rotation changes, and whenever the hygiene zoning is revised.", "> Equipment moving is the change most likely to happen and least likely to be reported, because moving a table does not feel like changing a controlled document."], "attachments": [{"name": "415 425 SQF Facility Plan ROTATION 1.pdf", "path": "50f1511f-941c-4664-97ae-cae250ae8173/files/415_425_SQF_Facility_Plan_ROTATION_1.pdf"}, {"name": "415 425 SQF Facility Plan ROTATION 2.pdf", "path": "50f1511f-941c-4664-97ae-cae250ae8173/files/415_425_SQF_Facility_Plan_ROTATION_2.pdf"}, {"name": "415 425 SQF Facility Plan ROTATION 3.pdf", "path": "50f1511f-941c-4664-97ae-cae250ae8173/files/415_425_SQF_Facility_Plan_ROTATION_3.pdf"}, {"name": "415 425 SQF Facility Plan ROTATION.drawio", "path": "50f1511f-941c-4664-97ae-cae250ae8173/files/415_425_SQF_Facility_Plan_ROTATION.drawio"}], "definitions": "Sheet 1 (Day 1): the floor as configured for weighing, mixing, depositing and baking. The depositor and the weighing station are in the room.\n\nSheet 2 (Day 2): the floor as configured for dunking in simple syrup and sealing. The depositor and the weighing station have been removed and the dunk station occupies the depositor's bay.\n\nSheet 3 (Day 3): the floor as configured for packaging, labelling, lot coding, bulk packaging and transfer to warehouse storage. The dunk station has been removed, the sealing unit has been moved, and the sealed product is held in the sealing unit's place.\n\nDunk bay: the bay that holds the depositor on Day 1 and the dunk station on Day 2. Its hygiene status is not the same on Day 1 as on Day 2.\n\nSealed product hold: where sealed product waits overnight between Day 2 and Day 3 — the position the sealing unit occupies on Day 2.\n\nScale: the drawing is to scale. One grid square is five feet.", "responsibility": "SQF Practitioner — owns this drawing. Confirms the hygiene zones, approves the drawing, and reviews it whenever the floor changes.\nSenior Site Management — approves the document and provides the resources any change to the floor requires.\nProduction Supervisor — works to the configuration shown for the day being run, and reports any difference between the drawing and the floor.\nProduction staff — follow the product route shown for the day being run.", "form_references": "None. This is a drawing and no record is completed against it.", "revision_history": "Rev New — drawn 2026-09-15, redrawn for a three-day rotation 2026-09-18. DRAFT. Not approved, not in force.\n\nWHY IT EXISTS. No controlled document in the set described the layout of the production floor or the route product takes across it. Nothing referenced a site plan, a floor plan or a product flow diagram, so the zoning the site works to existed only as practice. That matters more here than it would at most sites, because the rotation makes one floor area low risk on one day and high care on the next.\n\nHOW IT WAS BUILT. From the architectural floor plan for 415/425, traced to vector and set to a scale derived from a dimension printed on that plan. Equipment positions were measured from the marked-up plan rather than estimated, except for a small number of soft-edged label areas drawn as approximations and marked as such.\n\nTHE THREE-SHEET STRUCTURE IS THE POINT. The floor runs a three-day rotation and the equipment in the room differs on each day. Issuing a single sheet would show a floor that either exists a third of the time or never.\n\n2026-09-18 — TWO DAYS BECAME THREE. The drawing was first built for a two-day rotation, with dunking, sealing, packaging and lot coding all on Day 2. Production confirmed the finishing work is split: Day 2 is dunking in simple syrup and sealing, Day 3 is packaging, labelling, lot coding and bulk packaging. Sheet 2 was split into Sheets 2 and 3, the Day 3 equipment was placed by the owner, and the product route was renumbered so steps 1 to 9 still run end to end across the three sheets. Two facts came with it and are recorded in the procedure: sealed product is held overnight where the sealing unit stands on Day 2, and the weighing station is removed after Day 1. The second replaces an earlier statement that the weighing station stood idle inside HIGH CARE on Day 2; it does not. Step 10, packaged product out of the high-care area to warehouse storage, was added to Sheet 3 the same day, so the route now ends at storage rather than at the lot code.\n\nOPEN BEFORE ISSUE — ONE ITEM:\n\nTHE ZONE BOUNDARIES ARE NOT YET CONFIRMED ON THE FLOOR. They were derived from the identity and position of the equipment rather than from a walk of the building. The division itself is not in doubt — the oven is the kill step, upstream is low risk, downstream is high care — but where exactly the lines fall between the cooling racks, the mixers and the ovens on the west wall is the kind of thing that is settled by standing in the room. The SQF Practitioner confirms or corrects them, and the drawing issues on that confirmation.\n\nSCOPED OUT, AND NOT OMISSIONS:\n\nPersonnel flow, hand-wash points and allergen segregation. This drawing answers where equipment stands and where product goes. Personnel movement is a different question with a different review cycle, and three overlays on one sheet make all three harder to read. Control over personnel crossing the raw / high-care boundary belongs to the GMP programme, FSQM-012.\n\nSTATED LIMITATIONS, AND NOT DEFECTS:\n\nThe scale carries a tolerance of about three percent — around two feet on this building. That is immaterial for judging which zone a machine stands in and inadequate for construction, and every sheet is marked NOT FOR CONSTRUCTION. A single tape measurement of a known wall would remove it if the drawing is ever needed for another purpose.\n\nThe sheets are 11.31 by 12.61 inches, which is not a standard paper size and will scale if printed.\n\nISSUED 2026-09-28 - FLOOR WALK PERFORMED. The SQF Practitioner walked the production floor on 2026-09-28 and confirmed the hygiene zone boundaries as drawn, including where the lines fall on the west wall between the cooling racks, the mixers and the ovens. That confirmation was the one thing this drawing waited on, and it issues on it: active, approved GJM, effective 2026-09-28, Rev New, all three sheets and the draw.io master at the same revision.\n\nTHE ZONING RESTS ON THE CHANGEOVER CLEAN, WHICH HAS NO RECORD YET. The dunk bay is low risk on Day 1 and high care on Day 2, separated by the changeover clean rather than by a wall. Changeover (2.6.1.2, D-17) is not yet documented or recorded. Issuing this drawing makes that dependency an active assertion; it is stated here rather than left to be found.\n\nsqf_reference stays null and sqf_required stays false: no clause requires a facility layout drawing, and this document still is not the 2.4.3.6 flow diagram.\n\nv2 - 2026-10-29 - The governing reference said the food safety plan was not a controlled document; FSQM-016 was issued on 2026-10-29 with its flow diagram. Approved GJM.", "governing_reference": "No clause of either SQF code requires a facility layout drawing, and this document does not close one. Both editions were searched for \"site plan\", \"floor plan\" and \"premises layout\" and neither mandates such a drawing. sqf_reference is null and sqf_required is false for that reason, and this document is not a D-xx deliverable.\n\nWHAT IT IS NOT: SQF Food Safety Code: Food Manufacturing, Edition 9, 2.4.3.6 requires the food safety team to develop and document a flow diagram covering the scope of each food safety plan, including every step in the process, all raw materials, packaging, service inputs such as water, steam and gasses, scheduled process delays, and all process outputs including waste and rework, each verified on site. This drawing carries none of those. It shows equipment placement, hygiene zoning and the physical route product takes. Offering it as a 2.4.3.6 flow diagram would close a Mandatory clause on a document that does not address it.\n\nWHAT IT SUPPORTS: the food safety plan, FSQM-016, carries the process flow diagram as its Attachment A; this drawing is an input to it, and the two are read together. 2.4.3.3 requires the scope of each plan to document start and end points and all relevant inputs and outputs; the physical route shown here informs that but does not satisfy it.\n\nFSQM-012 governs the premises and the GMP controls applying to the areas this drawing divides, and is where any control over personnel movement across the raw / high-care boundary belongs.\nSOP-401 governs the temperature-controlled units shown on the drawing.\nThe Day 1 to Day 2 changeover clean, on which the dunk bay's change of hygiene status depends, is governed by the sanitation documents in the 900 series."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '50f1511f-941c-4664-97ae-cae250ae8173' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"scope": "Every ingredient, processing aid and lubricant, every product made on site, and everyone who enters the production and storage rooms.", "purpose": "This program states how Adventure Bakery keeps an allergen out of any product that does not declare it: which allergens are on site, where they are kept, the order products are made in, the clean between them, and how that clean is proved.", "records": "• FRM-916 - one per validation or verification swab session\n• The machine cleaning logs, FRM-909 to FRM-912, with the allergen changeover ticked\n• FRM-207 - the allergens of every material\n• FRM-903 and FRM-913 - segregation checks\n• Training records for TRN-003, TRN-004 and TRN-004A in the Team Portal", "procedure": ["The allergens", "• The list used is the nine major food allergens of the United States, where the product is made and sold: milk, egg, fish, crustacean shellfish, tree nuts, peanuts, wheat, soy and sesame (SQF 2.8.1.1 iii).", "• On this site: wheat, milk, egg, soy and three tree nuts - pecans, walnuts and almonds. Not on this site, and not brought in without this program being revised first: any other tree nut, peanuts, sesame, fish and crustacean shellfish.", "• The list of allergens, and which materials and products carry each one, is posted in the production room and is in the Team Portal: the allergens of every material are on its FRM-207 entry (SQF 2.8.1.1 iv).", "The risk analysis", "• The SQF Practitioner assesses every raw material, ingredient and processing aid, and every lubricant that could touch product, for the allergens it contains or may contain. The record is the material's FRM-207 entry, taken from the manufacturer's label or specification (SQF 2.8.1.1 i).", "• What the analysis found:", "◦ Wheat, milk, egg and soy are in the cake base, the egg, the oil and the pan release spray. Every product made here - the rum cakes and the products packed for another customer - contains all four and declares all four, so between products they cannot make one unsafe for a person who can eat another. The risk there is the label, not cross-contact. A new product that does not declare one of the four makes that allergen a changeover for it, the same as a nut.", "◦ Tree nuts are in some products and not in others: pecans in some rum cakes, walnuts and almonds in products packed for another customer. This is the allergen that can cross from one product to another, on the mixer, the depositor, the pans, the racks, the dipping and packing tables, utensils, hands and clothing. It is the risk this program is built around.", "◦ Each tree nut is its own allergen on a label. A product with one nut made after a product with a different nut is a changeover, the same as a product with no nuts.", "◦ Processing aid: the pan release spray contains soy, which every cake already declares.", "◦ Lubricants: the grease and oil used on the depositors and the mixer are assessed from the manufacturer's allergen statement, kept with the material's FRM-207 entry. The depositors' lubricants are food-grade. The Hobart mixer's planetary gear oil is not; it is a known gap, replaced with an NSF H1 food-grade lubricant under FSQM-029.", "◦ A new material, a new brand of an existing material, or a new product is assessed before it is used (SOP-2.3.2, SOP-2.3.4).", "Allergens brought in by people", "• Staff food, drink and bags are kept and eaten only in the break area, which is separate from the production and storage rooms. Nothing is eaten or drunk in production (FSQM-012).", "• Hands are washed on entering the production room and after eating. Outer clothing worn in production is not worn in the break area while eating.", "• Visitors and contractors agree to the same rules on the entrance screen before they go in (FRM-906), and bring no food past reception.", "• There is no vending machine on site. Peanuts and peanut products are the allergen most likely to arrive in a lunch; the hand wash and the break area rule are the control (SQF 2.8.1.1 ii).", "Receiving and storing", "• At receipt the brand and product are checked against FRM-207 on FRM-301. A different brand is a new material: its allergen statement, including any \"may contain\", is checked before it is used (SOP-2.3.4).", "• Nuts are kept in closed, labelled containers on the allergen rack in the production room, below other materials and never above them. An opened pack is resealed or put in a lidded container labelled with the product and the word NUTS.", "• A scoop, bowl or container that has been used for nuts is washed with detergent, rinsed and sanitized before it is used for anything else. It is part of the changeover clean. Sanitizer alone does not remove an allergen; the wash and rinse do. A spill is cleaned up at once.", "• Segregation is checked on every day nuts are handled, on that day's FRM-903 (\"Allergen controls / segregation followed\"), and every month in the GMP inspection on FRM-913 (SQF 2.8.1.3).", "Making product - the changeover rule", "• Products without nuts are made first. Products with nuts are made last in the day, and the full clean follows them.", "• A changeover clean is done before any product that does not declare an allergen the product before it contained. On this site that means: after a product with a nut and before a product without that nut (SQF 2.8.1.6).", "• The changeover clean is the full clean in each machine's cleaning procedure - SOP-901 for the mixer, SOP-902 and SOP-903 for the depositors, SOP-904 for the kettle - and covers everything else the product touched: pans, racks, tables, scoops and utensils. It removes all visible residue from every product contact surface (SQF 2.8.1.4).", "• It is recorded on that machine's cleaning log - FRM-909, FRM-910, FRM-911 or FRM-912 - with \"Allergen changeover\" ticked and the line \"every food contact surface checked under good light\" completed.", "• Aprons and gloves are changed and hands washed after handling nuts and before handling a product without them.", "• Rework: a unit whose seal failed is re-pouched as the same product only, keeps the product name and lot code it had, and is counted on that lot's record (FRM-520). Product is never reworked into a different product, so a nut is never carried into a product that does not declare it (FSQM-018) (SQF 2.8.1.10).", "• Labels: the allergens on every label are approved on FRM-601 and the label applied is checked at release on FRM-701 (SOP-2.3.2.3). Every product made on the shared equipment is labelled with its allergens as United States law requires, and every pack also states that the nut is present or that the facility processes tree nuts. That statement does not replace the changeover clean (SQF 2.8.1.7).", "• These controls are carried into the food safety plan: the allergen hazards at each step are in FSQM-016 Part 7 (SQF 2.8.1.1 v, vi).", "Proving the clean works", "• Looking at a surface does not prove that an allergen is gone. The changeover clean is validated and verified with a test kit that detects the nut that was run, recorded on FRM-916 (SQF 2.8.1.5).", "• Validation: for each machine, the first three changeover cleans after a nut cake are swabbed after cleaning and before the next use. All three must show nothing detected.", "• Verification: every changeover clean is inspected under good light and recorded on the machine's cleaning log. In addition, one changeover clean on each machine is swabbed at least once a year.", "• How often to swab depends on the product made after the nut. Once a year is enough where its pack lists the nut or states that the facility processes tree nuts, because a person with a nut allergy is warned off it. Every product made here has such a pack today: the rum cake box lists pecans and states that the facility processes nuts, and the other customer's packs state \"manufactured in a facility that processes tree nuts, peanuts\". A new product whose pack has no such wording is swabbed at least every three months, and does not follow a nut product on a machine until that machine's validation has passed.", "• The clean is validated again when the cleaning method, the detergent, the equipment, or the nut changes.", "• If a swab detects the allergen: the surface is cleaned and swabbed again, nothing is made on it until it passes, any product made since the last passing check is held on FRM-702 under FSQM-018, and a CAPA is raised on FRM-007.", "If something goes wrong", "• A nut found in or on a product that does not declare it, a wrong label, or a clean that was missed: stop, hold the product on FRM-702, and tell the SQF Practitioner. If product has left the site, FSQM-023 starts.", "Instruction", "• All staff complete the allergen training modules in the Team Portal (TRN-003, TRN-004 and TRN-004A) when they start and as they come due. Whoever receives, stores or handles nuts is shown this program and the changeover rule on the floor. The Team Portal keeps the record (SQF 2.8.1.2).", "Review", "• The SQF Practitioner reviews this program at least once a year, and before a new allergen, material or product is brought in. The review is recorded as a revision of this document.", "Stated limitations at issue", "> THIS PROGRAM WAS ISSUED ON 2026-10-29 WITH THESE OPEN, by management's decision. Each names what closes it, who owns it and when. When one closes, this Part is revised.", "• THE TEST KIT. A kit that detects pecans, walnuts and almonds on a cleaned surface is chosen and bought by 2026-11-30. Owner: Senior Site Management.", "• VALIDATION. The first three changeover cleans on each machine after a nut product are swabbed and recorded on FRM-916 by 2027-01-31. Until then the changeover clean is checked by looking, as it has been. Owner: SQF Practitioner.", "• THE CLEANING LOGS. The mixer and depositor logs (FRM-909, FRM-910, FRM-911) have not yet been used. From the next nut product, every changeover clean is recorded on the machine's log with 'Allergen changeover' ticked. Owner: SQF Practitioner.", "• THE MATERIALS. Pecans, walnuts, almonds, the liquid egg and the lubricants are entered on FRM-207 with their allergen statements, and the allergen list is posted in the production room, by 2026-12-31. Owner: SQF Practitioner.", "• TRAINING. TRN-003, TRN-004 and TRN-004A are read against this program, and changed where they disagree with it, by 2026-12-31. Owner: SQF Practitioner.", "Records", "• FRM-207, FRM-301, FRM-903, FRM-913, the cleaning logs FRM-909 to FRM-912, FRM-916 and FRM-007 are kept as SOP-2.2.3 requires."], "definitions": "Allergen: one of the nine major food allergens listed in this program.\nCross-contact: an allergen getting into a product that does not contain it.\nChangeover: going from a product that contains an allergen to a product that does not declare it.\nChangeover clean: the full clean of everything the first product touched, done before the second product.\nValidation: proving once that the clean removes the allergen.\nVerification: checking, each time and at intervals, that the clean was done and still works.", "not_applicable": [{"clause": "2.8.1.11", "reason": "The site handles allergenic materials and makes allergenic products. 2.8.1.11 is for sites that do neither; this program meets 2.8.1.1 to 2.8.1.10 instead."}], "responsibility": "SQF Practitioner - carries out the risk analysis, keeps the allergen list and this program current, plans the swabs and decides what is done with a failed result. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves new materials, products and labels, and sets the production order.\nProduction staff - follow the production order, keep nuts apart, do and record the changeover clean, and report anything that goes wrong.\nAll staff - keep food in the break area and wash hands on entering production.", "form_references": "FRM-916 - Allergen Cleaning Verification Record\nFRM-909 - Mixer Cleaning & Pre-Use Check Log\nFRM-910 - Kook-E-King Depositor Cleaning & Pre-Use Check Log\nFRM-911 - Depositor Cleaning & Pre-Use Check Log (Beldos 275)\nFRM-912 - Kettle Cleaning & Pre-Use Check Log (Groen TDB)\nFRM-207 - Material Specification Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-913 - GMP / Food Safety Inspection Record\nFRM-601 - Label Review & Approval Form\nFRM-701 - Finished Product Release Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "New - 2026-10-05 - DRAFT under D-23, for the Minor findings against 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.5 and 2.8.1.6. The site had no allergen management program.\n\nOWNER'S ANSWERS (2026-10-05): the allergens on site are wheat, milk, egg, soy, pecans and other tree nuts; cakes with nuts are made last in the day; the changeover clean is checked by looking only, with no swab; staff eat and keep their food in a separate break area. The finished pack declares wheat, milk, egg and soy on every cake.\n\nSOP-204 Allergen Cleaning Procedure (a three-line draft, never issued) is REPLACED by this program and is archived when this program is issued. Its ATP swab does not show that an allergen is gone, which was the finding against 2.8.1.5. The changeover clean was already written, machine by machine, in SOP-901 to SOP-904, and recorded on FRM-909 to FRM-912. So there is no separate Allergen Changeover Log, and the number clash on FRM-204 goes away: FRM-204 stays the supplier evaluation checklist.\n\n2.8.1.4 was scored Compliant against SOP-204, so this program takes it over.\n\nNEW REQUIREMENT, NOT YET DONE: swabbing with an allergen test kit (validation, then once a year).\n\nAT ISSUE: archive SOP-204; add a three-monthly 'allergen cleaning verification' row (the shorter of the two intervals) to the verification schedule (FSQM-017 Part 6) against FRM-916.\n\nTO CONFIRM BEFORE ISSUE: (1) for each product packed for another customer: which of wheat, milk, egg and soy it contains and declares, and whether its packaging carries a tree nut statement; (2) every material in use, including the nuts, the egg and the lubricants, entered on FRM-207 with its allergen statement; (3) the allergen list posted in the production room; (4) the nuts' place on the allergen rack; (5) a test kit chosen that detects the nuts used, and the three validation cleans per machine recorded on FRM-916; (6) that there is no vending machine; (7) the machine cleaning logs FRM-909 to FRM-912 in use on changeover days; (8) TRN-003, TRN-004 and TRN-004A read against this program.\n\nOWNER'S DECISION (2026-10-05): nuts do not have their own scoop. A utensil used for nuts is washed, rinsed and sanitized before any other use. SQF 2.8.1.4 asks for separate equipment only where a clean is not possible. The first draft's dedicated scoop went further than the clause.\n\nOWNER'S DECISION (2026-10-05): segregation is checked on the days nuts are handled and in the monthly inspection, not on every production day. Tree nuts are the only allergen that can cross between products here, so a day without nuts has nothing to keep apart beyond the closed containers on the rack. SQF 2.8.1.3 asks for continual monitoring; monthly alone was judged too little.\n\nOWNER'S DECISION (2026-10-05): every cake is packed in the same box, which lists pecans and carries the facility statement. On that basis the verification swab is once a year, not every three months, and the first draft's rule that no nut-free cake follows a nut cake until validation has passed is removed. The changeover clean itself stays: a label statement does not replace it (FDA guidance; SQF 2.8.1.4 and 2.8.1.6), and SQF 2.8.1.5 sets verification by risk assessment. The easing applies only to product packed with that wording.\n\nOWNER'S ANSWERS (2026-10-05): the only tree nuts on site besides pecans are walnuts and almonds, and they are in products packed in another customer's packaging, not in the rum cake box. The program now names the three nuts. The yearly swab, which rests on the rum cake box's wording, is limited to the rum cakes; a product whose pack has no such wording keeps the three-monthly swab and waits for the machine's validation. The earlier draft said every cake made here contains wheat, milk, egg and soy; that is stated of the rum cakes only until the other customer's products are checked.\n\nNew - 2026-10-29 - ISSUED, approved GJM, effective 2026-10-29, with the open items stated in a new Part 'Stated limitations at issue'. Management decided to issue before a test kit is chosen, reversing the decision of 2026-10-07 to wait for one. OWNER'S ANSWERS: the other customer's walnut and almond products contain the same four allergens plus the nut (2026-10-07), and their packs state \"manufactured in a facility that processes tree nuts, peanuts\" (2026-10-29); so every product made here declares the four and carries nut wording, and the yearly verification swab applies to all of them. Rework (2.8.1.10) and allergen labelling (2.8.1.7) are now cited on the lines that meet them; 2.8.1.11 is declared not applicable. Limitations: test kit by 2026-11-30; validation swabs by 2027-01-31; changeover cleans recorded on FRM-909 to FRM-911 from the next nut product; nuts, egg and lubricants on FRM-207 and the allergen list posted by 2026-12-31; TRN-003/004/004A read against the program by 2026-12-31. At issue: SOP-204 archived; the yearly allergen swab joined the verification schedule (FSQM-017 v21), first due 2027-01-31.\n\nv2 - 2026-10-29 - The lubricant line said the mixer's lubricants are food-grade; FSQM-029 records that the Hobart's planetary gear oil is not, so the line now says so. Rework cites FSQM-018, the issued program that authorises it, instead of the draft FSQM-019. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.4, 2.8.1.5, 2.8.1.6 (Allergen Management).\n\nSOP-901, SOP-902, SOP-903, SOP-904 - the cleaning procedure for each machine.\nSOP-2.3.2 specification control; SOP-2.3.4 Vendor Approval; SOP-2.3.2.3 Label Control.\nFSQM-012 Good Manufacturing Practices Program.\nFSQM-016 Food Safety Plan (HACCP) - Part 7, the hazard analysis.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-009 CAPA Program; FSQM-023 Product Withdrawal and Recall Program.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here."}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '2363dbc0-d209-4cc4-a1cb-b2d77efc27e4' and status = 'active' and revision = 'New';

update public.sop_documents set status = 'archived' where id = '7282e1cc-b6a9-4355-8b30-5e9b30b4468f' and status = 'active';
update public.sop_documents set status = 'archived' where id in ('e0208578-ebb7-45c1-be4d-dcbafe6cc581', '395c9058-db59-494c-9bc5-5148a4437880', 'c3c9dab8-4516-4331-8e2a-328376b6c6d6', '3e09017b-ea1d-4900-bbbb-90cf18ee1456', '76c28fb3-2dcf-40db-b7e6-c6e73aadb1f3', '12144e6d-b151-448c-855b-fb7cecf93002') and status = 'draft';
update public.sop_documents set title = 'Mission and Vision' where id = '9e0e9e3e-69c0-41d4-b379-d505c5c0c9e0' and title = 'Mission and Vison';

do $verify$
begin
  if exists (select 1 from public.sop_documents where status = 'active' and (content - 'revision_history')::text like '%SOP-204%') then
    raise exception 'an active document still cites SOP-204.';
  end if;
  if (select (content->'procedure')::text not like '%pecans in the flavours that contain them%' from public.sop_documents where sop_number = 'FSQM-016') then
    raise exception 'FSQM-016 does not name pecans.';
  end if;
  if exists (select 1 from public.sop_documents where id = '7282e1cc-b6a9-4355-8b30-5e9b30b4468f' and status <> 'archived') then raise exception 'SOP-2.1.2 not archived.'; end if;
  if (select count(*) from public.sop_documents where sop_number in ('FSQM-012', 'SOP-901', 'SOP-902', 'SOP-903', 'SOP-904', 'SOP-906', 'SOP-503', 'SOP-504', 'FSQM-016', 'FSQM-005', 'FSQM-009', 'FSQM-014', 'FSQM-017', 'FSQM-036', 'FSQM-039', 'FSQM-027') and status = 'active' and effective_date = date '2026-10-29') <> 16 then
    raise exception 'not every revised document was written.';
  end if;
end $verify$;

commit;
